body_md:
\label{condalphabeta}
 Both on ${{\mathchoice{\hbox{\bfT}}{\hbox{\bfT}} 
        {\hbox{\scriptsize\bfT}}{\hbox{\tiny\bfT}}}}^d$ and ${{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d$, we assume that $\xi$ is a translation-invariant Gaussian noise with covariance given by 
 \begin{equs}
\mathrm{Cov}(x)\stackrel{\mbox{\tiny def}}{=}{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\xi(x)\xi(0)]=\langle\nabla\rangle^{2\alpha-2\beta-d}(x)\,,
 \end{equs}
 where
\begin{equation}\label{condbeta}
    0\vee (\alpha/2-d/{4})<\beta\leqslant\alpha/2\,.
\end{equation}

The choice of covariance kernel is for concreteness. In fact, we could handle any Gaussian noise with covariance kernel satisfying the estimate 
    \begin{equs}
        |\partial^\mathfrak{l}_x\mathrm{Cov}(x)|\lesssim |x|^{-2(\alpha-\beta)-|\mathfrak{l}|}{\mathrm{e}}^{-c|x|}\,.
    \end{equs}
Regarding the restrictions on $\beta$, they come from the following:
\begin{itemize}
    \par\hangindent 40\p@ For $\beta>\alpha/2$, the equation is not singular. Indeed, $\xi$ being of almost sure regularity $-\alpha+\beta-\kappa$, the solution $u$ will be of regularity $\beta-\kappa$, so the product $\xi u$ is well-defined since the regularities sum to $\beta-2\kappa>0$.
    \par\hangindent 40\p@ The equation is scaling subcritical for $\beta>0$. Indeed, with the above heuristic, one can expect the solution to be of regularity $\beta-2\kappa$, so multiplying the noise by the solution should improve its behaviour only for $\beta>0$ (one can hope that $\xi u$ behaves like the product of the regularities, so $-\alpha+2\beta-2\kappa>-\alpha$).
    \par\hangindent 40\p@ If $d< 2\alpha$, then for $\beta\leqslant \alpha/2-d/4$ the equation could display a covariance blow up. Indeed, with the above heuristic, the product $\xi u$ would indeed behaves like $-\alpha+2\beta-2\kappa<-d/2$, so its covariance might not be of finite total variation.
\end{itemize}

\label{assum:torus}
 On the torus ${{\mathchoice{\hbox{\bfT}}{\hbox{\bfT}} 
        {\hbox{\scriptsize\bfT}}{\hbox{\tiny\bfT}}}}^d$, we consider the following three situations:
    \begin{enumerate}
     \par\hangindent 40\p@ The Laplacian: $\alpha=2$ and $m=0$, so $\mathrm{D}^{2,0}=-\Delta$.
      \par\hangindent 40\p@ The massive fractional Laplacian: $\alpha\in(0,2)$ and $m>0$, so $\mathrm{D}^{\alpha,m}=(-\Delta+m^2)^{\alpha/2}$. 
        \par\hangindent 40\p@ The massless fractional Laplacian: $\alpha\in(0,2)$ and $m=0$, so $\mathrm{D}^{\alpha,0}=|\nabla|^{\alpha}$.  
    \end{enumerate}

\label{assum:infinitevol}
 In infinite volume ${{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d$, we consider the following three situations:
  \begin{enumerate}
  \par\hangindent 40\p@ The Laplacian: $\alpha=2$ and $m=0$, so   
      $\mathrm{D}^{2,0}=-\Delta$.
        \par\hangindent 40\p@ The massive fractional Laplacian: $\alpha\in(0,2)$ and $m>0$, so $\mathrm{D}^{\alpha,m}=(-\Delta+m^2)^{\alpha/2}$. 

 \par\hangindent 40\p@ The harmonic oscillator: $\alpha=2$ and $m=q$, so  
      $\mathrm{H}=-\Delta+q^2$. 
    \end{enumerate}

\label{maintheoremspde}
Suppose that Assumption~ \ref{condalphabeta} is satisfied. Let $r\in[1,\infty]$ and $\kappa>0$ a small parameter.
\begin{enumerate}
    \par\hangindent 40\p@ Consider the equation~(\@saveref{Eq:RenomalizedParabolicRegularized}) on ${{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}_{\geqslant0}\times{{\mathchoice{\hbox{\bfT}}{\hbox{\bfT}} 
        {\hbox{\scriptsize\bfT}}{\hbox{\tiny\bfT}}}}^d$, in the setting of either items of Assumption~\ref{assum:torus} ({\it i.e.}\@ifnextchar,{}{\ } with the Laplacian or the possibly massless fractional Laplacian) and with initial condition $u_0\in\mathcal{B}^{-\sigma}_{r,\infty}({{\mathchoice{\hbox{\bfT}}{\hbox{\bfT}} 
        {\hbox{\scriptsize\bfT}}{\hbox{\tiny\bfT}}}}^d)$ for some $\sigma\in[0,\beta)$. Then, there exists a diverging deterministic constant $\mathfrak{C}^{\alpha,m}_\varepsilon$ unique up to shift by a real number, such that the solution $u_\varepsilon$ of (\ref{Eq:RenomalizedParabolicRegularized}) converges in probability to some non-trivial function $u$ in $L_t^\infty\mathcal{B}_{p,\infty}^{\gamma}({{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}_{\geqslant0}\times{{\mathchoice{\hbox{\bfT}}{\hbox{\bfT}} 
        {\hbox{\scriptsize\bfT}}{\hbox{\tiny\bfT}}}}^d)$. This limit is independent from the choice of mollification. Moreover, the solution $u$ satisfies the estimate uniformly in $t>0$ and for $(\sigma,\gamma,p,\eta)$ such that $\eta>0$, $p\geqslant r$, $0<\sigma<\beta$ and $0\leqslant \gamma< \beta-\sigma-d(1/r-1/p)$,
    \begin{equation}\label{Eq:EstimateS-G}
        \big\|u(t)-{\mathrm{e}}^{-t\mathrm{D}^{\alpha,m}}u_0\big\|_{\mathcal{B}_{p,\infty}^\gamma({{\mathchoice{\hbox{\bfT}}{\hbox{\bfT}} 
        {\hbox{\scriptsize\bfT}}{\hbox{\tiny\bfT}}}}^d)}\leqslant {\mathrm{e}}^{ct}(t\wedge1)^{(\beta-\sigma-\gamma-d(1/r-1/p)-\eta)/\alpha}  \|u_0\|_{\mathcal{B}_{r,\infty}^{-\sigma}({{\mathchoice{\hbox{\bfT}}{\hbox{\bfT}} 
        {\hbox{\scriptsize\bfT}}{\hbox{\tiny\bfT}}}}^d)}\,,
    \end{equation}
    for some positive random constant $c$.
    \par\hangindent 40\p@ Consider the equation~(\@saveref{Eq:RenomalizedParabolicRegularized}) on ${{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}_{\geqslant0}\times{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d$, in the setting of one of the first two items of Assumption~\ref{assum:infinitevol} (i.e with the heat operator or the massive fractional Laplacian). Then, there exists a diverging constant $\mathfrak{C}^{\alpha,m}_\varepsilon$ unique up to shift by a real number such that for any $u_0\in\mathcal{B}^{-\sigma}_{r,\infty}({{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d)$ and $T>0$, the solution $u_\varepsilon$ converges in probability to some function $u$ in the weighted space $\mathcal{E}^{\gamma,-\gamma-\sigma-d(1/r-1/p)}_{p,\ell,T}$ for $(\sigma,\gamma,p,\eta)$ such that $\eta>0$, $p\geqslant r$, $q\in[1,\infty]$, $0<\sigma<\beta$, and $0\leqslant \gamma< \beta-\sigma-d(1/r-1/p)$ (see (\@saveref{weightedspace}) for a definition of this space), and for every $\ell>0$. This limit is independent of the choice of mollification. Moreover, the solution satisfies for $t\in(0,T]$,



    \begin{equation}\label{eq:estimateS-Ginf}
        \|\mcb e_{-\ell-t} (u(t)-{\mathrm{e}}^{-t\mathrm{D}^\alpha}u_0)\|_{\mathcal{B}_{p,q}^\gamma({{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d)}\lesssim_T(t\wedge 1)^{(\beta-\sigma-\gamma-d(1/r-1/p)-\eta)/\alpha}  \|\mcb e_{-\ell}u_0\|_{\mathcal{B}_{r,q}^{-\sigma}({{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d)}\,.
    \end{equation}
    \par\hangindent 40\p@ Consider the equation~(\@saveref{Eq:RenomalizedParabolicRegularized}) on ${{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}_{\geqslant0}\times{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d$, in the setting of the third item of Assumption~\ref{assum:infinitevol} ({\it i.e.}\@ifnextchar,{}{\ } with harmonic oscillator) and with initial condition $u_0\in\mathscr{B}^{-\sigma}_{r,\infty}({{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d)$ for some $\sigma\in[0,\beta)$. Then, taking the same renormalisation constant as in the above point for the Laplacian, i.e. setting $\mathfrak{C}^{2,q}_\varepsilon=\mathfrak{C}^{2,0}_\varepsilon$, the solution $u_\varepsilon$ of (\ref{Eq:RenomalizedParabolicRegularized}) converges in probability to some non-trivial function $u$ in $L_t^\infty \mathscr{B}_{p,\infty}^{\gamma}({{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}_{\geqslant0}\times{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d)$. This limit is independent from the choice of mollification. Moreover, the solution $u$ satisfies the estimate uniformly in $t>0$ and for $(\sigma,\gamma,p,\eta)$ such that $\eta>0$, $p\geqslant r$, $0<\sigma<\beta$ and $0\leqslant \gamma< \beta-\sigma-d(1/r-1/p)$,
    \begin{equation}\label{Eq:EstimateS-GOH}
        \big\|u(t)-{\mathrm{e}}^{-t\mathrm{H}}u_0\big\|_{\mathscr{B}_{p,\infty}^\gamma({{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d)}\leqslant {\mathrm{e}}^{ct}(t\wedge1)^{(\beta-\sigma-\gamma-d(1/r-1/p)-\eta)/2}  \|u_0\|_{\mathscr{B}_{r,\infty}^{-\sigma}({{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d)}\,,
    \end{equation}
    for some positive random constant $c$.
\end{enumerate}

\label{Rem:RemarksTheorem1}
    A few remarks are in order.
    \begin{itemize}
        \par\hangindent 40\p@ The sharp estimate (\@saveref{Eq:EstimateS-G}) was obtained for the first time in \cite{BDM22} in the case of the Anderson operator on compact Riemannian surfaces via paracontrolled calculus. Our result generalises it to an arbitrarily long ansatz. It is, in addition, extended to the more general contexts with (\@saveref{eq:estimateS-Ginf}) and (\@saveref{Eq:EstimateS-GOH}).
        \par\hangindent 40\p@ These estimates are refined versions of the Schauder estimate that reads in the case of the torus for example
        \begin{equation}
            \|  u(t)\|_{\mathcal{B}_{p,\infty}^\gamma({{\mathchoice{\hbox{\bfT}}{\hbox{\bfT}} 
        {\hbox{\scriptsize\bfT}}{\hbox{\tiny\bfT}}}}^d)}\leqslant {\mathrm{e}}^{ct}(t\wedge 1)^{(-\sigma-\gamma-d(1/r-1/p))/\alpha}  \|u_0\|_{\mathcal{B}_{r,\infty}^{-\sigma}({{\mathchoice{\hbox{\bfT}}{\hbox{\bfT}} 
        {\hbox{\scriptsize\bfT}}{\hbox{\tiny\bfT}}}}^d)}\,.
        \end{equation}
        \par\hangindent 40\p@ In the third estimate (\@saveref{Eq:EstimateS-GOH}), we have used Besov spaces based on the harmonic oscillator $\mathrm{H}$. Using these spaces is more demanding than their classical counterparts. Indeed, we have the inclusions $\mathcal{B}_{p,\infty}^{-\sigma}({{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d)\subset\mathscr{B}_{p,\infty}^{-\sigma}({{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d)$, and $\mathscr{B}_{p,\infty}^{\gamma}({{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d)\subset\mathcal{B}_{p,\infty}^{\gamma}({{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d)$. Intuitively, the operator takes as input functions that have an authorised additional growth at infinity and yields an output that has additional decay at infinity.
        \par\hangindent 40\p@ In (\@saveref{eq:estimateS-Ginf}), we do not keep track of the growth as in the other items for simplicity. We believe though that it is possible with more efforts and that one should expect super-exponential growth.
    \end{itemize}

\label{Th:ExistenceAndersonOp}
    Suppose that Assumption \ref{condalphabeta} is satisfied.
    \begin{enumerate}
        \par\hangindent 40\p@ On ${{\mathchoice{\hbox{\bfT}}{\hbox{\bfT}} 
        {\hbox{\scriptsize\bfT}}{\hbox{\tiny\bfT}}}}^d$, under Assumption \ref{assum:torus}, there exists an event of probability one, on which the following holds.
        \begin{enumerate}
            \par\hangindent 40\p@ For any $p\in(1,\infty)$, there exists a quasi-sectorial operator $\mathrm{A}^{\!\alpha,m}_\xi$ on $L^p_x$ such that the solution $u$ of (\@saveref{mainSPDE}), constructed in Theorem \ref{maintheoremspde}, solves
            $$\partial_t u + \mathrm{A}^{\!\alpha,m}_\xi u= 0.$$
            Moreover, $\mathrm{A}^{\!\alpha,m}_\xi$ is the limit in norm-resolvent of
            $$\mathrm{A}^{\!\alpha,m}_{\xi,\varepsilon_k} = \mathrm{D}^{\alpha,m}+\xi_{\varepsilon_k}-\mathfrak{C}_{\varepsilon_k}\,,$$
            where $\varepsilon_k$ is a deterministic sequence going to $0$, and for any $0<\gamma<\beta$ and $z>0$ large enough, $(\mathrm{A}^{\!\alpha,m}_\xi+z)^{-\frac{\gamma}{\alpha}}\in\mathcal{L}(L^p_x,H^{\gamma,p})$.
            \par\hangindent 40\p@ On $L^2_x$, $\mathrm{A}^{\!\alpha,m}_\xi$ is self-adjoint and has compact resolvent. Thus, there exists a complete orthonormal basis $(\varphi_n)_{n\in{{\mathchoice{\hbox{\bfN}}{\hbox{\bfN}} 
        {\hbox{\scriptsize\bfN}}{\hbox{\tiny\bfN}}}}}$ and a non-decreasing sequence
            $$\lambda_0 \leqslant \lambda_1 \leqslant \cdots \leqslant \lambda_n \to \infty$$
            such that $\mathrm{A}^{\!\alpha,m}_\xi\varphi_n=\lambda_n\varphi_n$ and 
            \begin{equation}\label{Eq:WeylLawAndersonTheorem}
                \#\{n\in{{\mathchoice{\hbox{\bfN}}{\hbox{\bfN}} 
        {\hbox{\scriptsize\bfN}}{\hbox{\tiny\bfN}}}},\; \lambda_n\leqslant\lambda\}\sim \frac{\pi^{\frac{d}{2}}\lambda^{\frac{d}{\alpha}}}{\Gamma\bgroup\bgroup\bgroup\bgroup\left(\frac{d}{2}+1\right)\egroup\egroup\egroup\egroup}
            \end{equation}
            as $\lambda$ goes to $\infty$. Moreover, for any $p\in(1,\infty)$, the spectrum of $\mathrm{A}^{\!\alpha,m}_\xi$ on $L^p_x$ is given exactly by the previous sequence of eigenvalues, with same multiplicity and eigenfunctions.
            \par\hangindent 40\p@ Finally, for any $\lambda>-\lambda_0$, $\mathrm{A}^{\!\alpha,m}_\xi+\lambda$ is sectorial with bounded holomorphic calculus of any angle on any $L^p_x$.
        \end{enumerate}
        \par\hangindent 40\p@ On ${{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d$, under Assumption \ref{assum:infinitevol} 1. or 2., almost surely, there exists an unbounded self-adjoint operator $\mathrm{A}^{\!\alpha,m}_\xi$ on $L^2_x$ such that the solution $u$ of (\@saveref{mainSPDE}), constructed in Theorem \ref{maintheoremspde}, solves
        $$\partial_t u + \mathrm{A}^{\!\alpha,m}_\xi u= 0.$$ 
        \par\hangindent 40\p@ On ${{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d$, under Assumption \ref{assum:infinitevol} 3. (i.e. with the harmonic oscillator), there exists an event of probability one, on which the following holds.
        \begin{enumerate}
            \par\hangindent 40\p@ For any $p\in(1,\infty)$, there exists a quasi-sectorial operator $\mathrm A^{\!2,q}_\xi$ on $L^p_x$ such that the solution $u$ of (\@saveref{mainSPDE}), constructed in Theorem \ref{maintheoremspde}, solves
            $$\partial_t u + \mathrm A^{\!2,q}_\xi u= 0.$$
            Moreover, $\mathrm A^{\!2,q}_\xi$ is the limit in norm-resolvent of
            $$\mathrm A^{\!2,q}_{\xi,\varepsilon_k} = \mathrm{D}^{2,q}+\xi_{\varepsilon_k}-\mathfrak{C}_{\varepsilon_k}\,,$$
            where $\varepsilon_k$ is a deterministic sequence going to $0$, and for any $0<\gamma<\beta$ and $z>0$ large enough, $(\mathrm A^{\!2,q}_\xi+z)^{-\frac{\gamma}{\alpha}}\in\mathcal{L}(L^p_x,\mathscr{H}^{\gamma,p})$.
            \par\hangindent 40\p@ On $L^2_x$, $\mathrm A^{\!2,q}_\xi$ is self-adjoint and has compact resolvent. Thus, there exists a complete orthonormal basis $(\varphi_n)_{n\in{{\mathchoice{\hbox{\bfN}}{\hbox{\bfN}} 
        {\hbox{\scriptsize\bfN}}{\hbox{\tiny\bfN}}}}}$ and a non-decreasing sequence
            $$\lambda_0 \leqslant \lambda_1 \leqslant \cdots \leqslant \lambda_n \to \infty$$
            such that $\mathrm A^{\!2,q}_\xi\varphi_n=\lambda_n\varphi_n$ and 
            \begin{equation}\label{Eq:WeylLawAndersonTheoremOH}
                \#\{n\in{{\mathchoice{\hbox{\bfN}}{\hbox{\bfN}} 
        {\hbox{\scriptsize\bfN}}{\hbox{\tiny\bfN}}}},\; \lambda_n\leqslant\lambda\}\sim \frac{\lambda^{d}}{2^d\Gamma\bgroup\bgroup\bgroup\bgroup\left(d+1\right)\egroup\egroup\egroup\egroup}
            \end{equation}
            as $\lambda$ goes to $\infty$. Moreover, for any $p\in(1,\infty)$, the spectrum of $\mathrm A^{\!2,q}_\xi$ on $L^p_x$ is given exactly by the previous sequence of eigenvalues, with same multiplicity and eigenfunctions.
            \par\hangindent 40\p@ Finally, for any $\lambda>-\lambda_0$, $\mathrm A^{\!2,q}_\xi+\lambda$ is sectorial with bounded holomorphic calculus of any angle on any $L^p_x$.
        \end{enumerate}
    \end{enumerate}

We denote by $S_{\varepsilon,\mu}^{\alpha,m}$ and $T_{\varepsilon,\mu}^{\alpha,m}$ the possibly approximate solutions to the inviscid Polchinski flow equation (\@saveref{eq:flotFam}) with initial condition respectively $S_{\varepsilon}^{\alpha,m}$ and $T_\varepsilon^{\alpha,m}$, these quantifies being introduced in (\@saveref{eq:defS0}) and (\@saveref{eq:defT0}). There are respectively called the \textit{stationary effective force} and the \textit{translated effective force}. We expand these forces respectively over the \textit{stationary force coefficients} $(\upxi_{{\varepsilon,\mu}}^{\alpha,m;n})$ and the \textit{translated force coefficients} $(\uptau_{{\varepsilon,\mu}}^{\alpha,m;k,n})$, writing 
 \begin{equs}
S^{\alpha,m}_{\varepsilon,\mu}[v](z)&=\sum_{n=0}^{N_{0}}\upxi_{{\varepsilon,\mu}}^{\alpha,m;n}[v](z)\,,\\
T^{\alpha,m}_{\varepsilon,\mu}[v](z)&=T^{\alpha,m;0}_{\varepsilon,\mu}(z)+T^{\alpha,m;1}_{\varepsilon,\mu}[v](z)=\sum_{n=0}^{N_{0}}\uptau_{{\varepsilon,\mu}}^{\alpha,m;0,n}(z)+\sum_{n=0}^{N_{0}}\uptau_{{\varepsilon,\mu}}^{\alpha,m;1,n}[v](z)\,.
\end{equs}
The stationary force coefficients satisfy the hierarchy
\begin{equs}\label{eq:hierarchyxi}
\partial_\mu \upxi^{{\alpha,m};n}_{\varepsilon,\mu}(z, 
  \mathbin{\mathpalette\bigcdot@{}} 
)=-\sum_{i=0}^{n-1}\upxi_{\varepsilon,\mu}^{{\alpha,m};i}[\dot G^{\alpha,m}_\mu\upxi_{\varepsilon,\mu}^{{\alpha,m};n-1-i}( 
  \mathbin{\mathpalette\bigcdot@{}} 
)](z)
\end{equs}
and the translated force coefficients satisfy the hierarchy
\begin{equs}\label{eq:hierarchytau}
\partial_\mu \uptau^{{\alpha,m};k,n}_{\varepsilon,\mu}(z, 
  \mathbin{\mathpalette\bigcdot@{}} 
)=-\sum_{i=0}^{n-1}\uptau_{\varepsilon,\mu}^{{\alpha,m};1,i}[\dot G^{\alpha,m}_\mu\uptau_{\varepsilon,\mu}^{{\alpha,m};k,n-1-i}( 
  \mathbin{\mathpalette\bigcdot@{}} 
)](z)\,.
\end{equs}

Moreover, we assume that the stationary force coefficients satisfy the following initial condition, which is compatible with $S_{\varepsilon,0}^{\alpha,m}=S_{\varepsilon}^{\alpha,m}$:
\begin{equation}
\upxi^{\alpha,m;0}_{\varepsilon,0}(z_1,z_2)=\xi_\varepsilon(z_1)\delta(z_1-z_2)\,,
\end{equation}
as well as
\begin{equation}
    \upxi_{0,\varepsilon}^{{\alpha,m};n}(z_1,z_2)=\begin{cases}\mathfrak{c}_\varepsilon^{{\alpha,m};n}\delta(z_1-z_2)&\mathrm{if}~~1\leqslant n\leqslant N_1\,,\\
    0&\mathrm{otherwise}.
\end{cases}
\end{equation}

\label{exampleforce}
We would like to point out that the stochastic terms $\upxi_{\varepsilon,\mu}^n$ can be seen, as in regularity structures, as trees. In particular, as the equation is linear, they are ladder trees. $n$ would stand for the number of edges. We give below an example for the \textnormal{unrenormalised} version of $\upxi_{\varepsilon,\mu}^2$, for $m\neq q$.
\begin{equs}
    ~&\int_{\Lambda}\upxi_{\varepsilon,\mu}^2(z_1,z_2)\varphi(z_2)\,\mathrm{d} z_2=\begin{tikzpicture}[scale=0.4,baseline=0.15cm]
            \draw[line width=0.25mm, color=blue] (0,2.25) -- (0,3.25);
            \draw[line width=0.25mm] (0,0.25) node[dot] {} -- (0.5,1.25) node[dot] {} -- (0,2.25) node[dot] {};
            \draw (0,-0.25) node[scale=0.7] {$z_1$};
\end{tikzpicture}\\
&=\int_{\Lambda^2}{\xi}_\varepsilon(z_1)(G^{\alpha,m}-G^{\alpha,m}_\mu)(z_1-z){\xi}_\varepsilon(z)(G^{\alpha,m}-G^{\alpha,m}_\mu)(z-z_2){\xi}_\varepsilon(z_2)\varphi(z_2)\,\mathrm{d} z\,\mathrm{d} z_2\,.
\end{equs}
The black dots represent the noise, the black edges represent convolutions with the kernel $G-G_\mu$, and the loose blue edge represents $\varphi$. The hierarchy of flow equations (\@saveref{eq:hierarchyxi}) also has a graphical representation. For $n=2$, it would read
    \begin{equs}
        \partial_\mu\begin{tikzpicture}[scale=0.4,baseline=0.15cm]
            \draw[line width=0.25mm, color=blue] (0,2.25) -- (0,3.25);
            \draw[line width=0.25mm] (0,0.25) node[dot] {} -- (0.5,1.25) node[dot] {} -- (0,2.25) node[dot] {};
            \draw (0,-0.25) node[scale=0.7] {$z_1$};
\end{tikzpicture}=\begin{tikzpicture}[scale=0.4,baseline=0.15cm]
            \draw[line width=0.25mm, color=blue] (0,2.25) -- (0,3.25);
            \draw[line width=0.25mm, color=red] (0,0.25) node[dot] {} -- (0.5,1.25) node[dot] {};
            \draw[line width=0.25mm] (0.5,1.25) node[dot] {} -- (0,2.25) node[dot] {};
            \draw (0,-0.25) node[scale=0.7] {$z_1$};
\end{tikzpicture}+\begin{tikzpicture}[scale=0.4,baseline=0.15cm]
            \draw[line width=0.25mm, color=blue] (0,2.25) -- (0,3.25);
            \draw[line width=0.25mm] (0,0.25) node[dot] {} -- (0.5,1.25) node[dot] {};
            \draw[line width=0.25mm, color=red] (0.5,1.25) node[dot] {} -- (0,2.25) node[dot] {};
            \draw (0,-0.25) node[scale=0.7] {$z_1$};
\end{tikzpicture}\,,
    \end{equs}
where this time the red edges represent a convolution by the kernel $-\dot G_\mu$. The inductive part enters when splitting the trees on the red edges. For instance
\begin{equs}
    \begin{tikzpicture}[scale=0.4,baseline=0.15cm]
            \draw[line width=0.25mm, color=blue] (0,2.25) -- (0,3.25);
            \draw[line width=0.25mm, color=red] (0,0.25) node[dot] {} -- (0.5,1.25) node[dot] {};
            \draw[line width=0.25mm] (0.5,1.25) node[dot] {} -- (0,2.25) node[dot] {};
            \draw (0,-0.25) node[scale=0.7] {$z_1$};
\end{tikzpicture}\to \begin{tikzpicture}[scale=0.4,baseline=0.15cm]
            \draw[line width=0.25mm, color=blue] (0,0.25) node[dot] {} -- (0,1.25);
            \draw (0,-0.25) node[scale=0.7] {$z_1$};
\end{tikzpicture},~~\begin{tikzpicture}[scale=0.4,baseline=0.15cm]
            \draw[line width=0.25mm, color=blue] (0.5,1.25) -- (0.5,2.25);
            \draw[line width=0.25mm] (0,0.25) node[dot] {} -- (0.5,1.25) node[dot] {};
            \draw (0,-0.25) node[scale=0.7] {$v_2$};
\end{tikzpicture}\,.
\end{equs}

\label{Lem:expressiontau}
Fix some stationary force coefficients satisfying the hierarchy (\@saveref{eq:hierarchyxi}) and take
    \begin{equs}
        \uptau^{\alpha,m;0,0}_{\varepsilon,\mu}=-\psi_\varepsilon\quad \text{and}\quad\uptau^{\alpha,m;0,n}_{\varepsilon,\mu}=\upxi^{\alpha,m;n-1}_{\varepsilon,\mu}[G^{\alpha,m}_\mu\psi^{\alpha,m}_\varepsilon]\;\;\text{for}\;\;n\geqslant1\,,
    \end{equs}
alongside
\begin{equs}
  \uptau^{\alpha,m;1,n}_{\varepsilon,\mu}[v]=  \upxi_{\varepsilon,\mu}^{\alpha,1;n}[v] \;\;\text{for}\;\;n\geqslant0\,.
\end{equs}
Then, we have that the above translated force coefficients satisfy the hierarchy (\@saveref{eq:hierarchytau}).

This follows from the fact that, if $S_{\varepsilon,\mu}^{\alpha,m}$ is an exact solution to the inviscid Polchinski flow equation with initial condition $S_\varepsilon^{\alpha,m}$, then $S^{\alpha,m}_{\varepsilon,\mu}[ 
  \mathbin{\mathpalette\bigcdot@{}} 
+G_\mu^{\alpha,m}\psi^{\alpha,m}_\varepsilon]-\psi^{\alpha,m}_\varepsilon$ solves this equation with initial condition $T_\varepsilon^{\alpha,m}$.

\label{Lem:suppprop}
    In view of the support properties of the scale decomposition of the heat kernel and of the flow equation (\@saveref{eq:hierarchyxi}), we have that $\upxi^{\alpha,m;n}_{\varepsilon,\mu}(z_1,z_2)$ is supported on $t_1-2n\mu^\alpha\leqslant t_2\leqslant t_1$, which implies that 
\begin{equs}
    \upzeta^{\alpha,m;k,n}_{\varepsilon,\mu}(z, 
  \mathbin{\mathpalette\bigcdot@{}} 
)=\uptau^{\alpha,m;k,n}_{\varepsilon,\mu}(z, 
  \mathbin{\mathpalette\bigcdot@{}} 
) \qquad \text{for all} \quad t\geqslant 2n\mu^\alpha\,.
\end{equs}

