\label{Lemmarecurrence}
    Let $\tau\in(0,1)$ such that
    \begin{equation}\label{2/tau2}
        (2/\tau^\alpha-1)^{2M}\leqslant2\,.    
    \end{equation}
    Then, there is a random $T\in(0,1]$ such that, for every $p\in{{\mathchoice{\hbox{\bfN}}{\hbox{\bfN}} 
        {\hbox{\scriptsize\bfN}}{\hbox{\tiny\bfN}}}}$,
    \begin{equation}\label{HR}
        \sup_{t\leqslant T}\big\|\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle^{-\kappa}\mcb e_{-\ell-t}K_{\tau^pT^{1/\alpha}} (F_{\varepsilon,T^{1/\alpha}}[0]+R_{\varepsilon,T^{1/\alpha}})(t)\big\|_{L^{r}_{x}}\leqslant C(\tau^pT^{1/\alpha})^{-\alpha-\sigma+\beta-\kappa}\|\mcb e_{-\ell}u_0^\varepsilon\|_{\mathcal{B}_{r,q}^{-\sigma}}\,.
    \end{equation}
    Consequently, we get
    \begin{equation}
        \sup_{t\leqslant T}\big\|\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle^{-\kappa}\mcb e_{-\ell-t}K_\mu (F_{\varepsilon,T^{1/\alpha}}[0]+R_{\varepsilon,T^{1/\alpha}})(t)\big\|_{L^{r}_{x}}\lesssim\mu^{-\alpha-\sigma+\beta-\kappa}\|\mcb e_{-\ell}u_0^\varepsilon\|_{\mathcal{B}_{r,q}^{-\sigma}}\,.
    \end{equation}

The proof is very similar to the proof of Lemma 3.12 in \cite{CF24a}, with the difference that we need to integrate the weights. We proceed by induction on $p$. The base case follows directly from (\@saveref{eq:esti_force_infvol}) and Lemma \ref{Lemmafixedpoint}, and reads
    \begin{equs}
        \sup_{t\leqslant T}\big\|\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle^{-\kappa}\mcb e_{-\ell-t}K_{T^{1/\alpha}} (F_{\varepsilon,T^{1/\alpha}}[0]+R_{\varepsilon,T^{1/\alpha}})(t)\big\|_{L^{r}_{x}}\lesssim T^{(-\alpha+\beta-\kappa)/\alpha}\|\mcb e_{-\ell}u_0^\varepsilon\|_{\mathcal{B}_{r,q}^{-\sigma}}\,.
    \end{equs}
    Now suppose that (\@saveref{HR}) holds for some $p\in{{\mathchoice{\hbox{\bfN}}{\hbox{\bfN}} 
        {\hbox{\scriptsize\bfN}}{\hbox{\tiny\bfN}}}}$. To go from $p$ to $p+1$, some care has to be taken with the weights. Recall that we have, $K_{\tau^{p+1}T^{1/\alpha}}=\mathcal{R}_{\tau^{p}T^{1/\alpha}}K_{\tau^{p+1}T^{1/\alpha}}K_{\tau^{p}T^{1/\alpha}}$. Thus we get
    \begin{equs}
        ~&\langle x\rangle^{-\kappa}\mcb e_{-\ell-t}(x)K_\mu (F_{\varepsilon,T^{1/\alpha}}[0]+R_{\varepsilon,T^{1/\alpha}})(t,x)\\
        &=\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d}\int_0^t\langle x\rangle^{-\kappa}\mcb e_{-\ell-t}(x)(\mathcal{R}_{\tau^{p}T^{1/\alpha}}K_{\tau^{p+1}T^{1/\alpha}})(t-s,x-y)K_{\tau^{p}T^{1/\alpha}}(F_{\varepsilon,T^{1/\alpha}}[0]+R_{\varepsilon,T^{1/\alpha}})(s,y)\,\mathrm{d} s\,\mathrm{d} y\\
        &\leqslant\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d}\int_0^t\langle x\rangle^{-\kappa}\mcb e_{\ell+t}(x-y)(\mathcal{R}_{\tau^{p}T^{1/\alpha}}K_{\tau^{p+1}T^{1/\alpha}})(t-s,x-y)\\
        &\qquad\qquad\qquad\qquad\qquad\qquad\qquad\quad\times\langle y\rangle^{\kappa}\langle y\rangle^{-\kappa}\mcb e_{-\ell-s}(y)K_{\tau^{p}T^{1/\alpha}}(F_{\varepsilon,T^{1/\alpha}}[0]+R_{\varepsilon,T^{1/\alpha}})(s,y)\,\mathrm{d} s\,\mathrm{d} y\\
