        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d}\int_0^t\langle x;y\rangle^{\kappa}\mcb e_{\ell+t}(x-y)(\mathcal{R}_{\tau^{p}T^{1/\alpha}}K_{\tau^{p+1}T^{1/\alpha}})(t-s,x-y)\\
        &\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad~~~\times\langle y\rangle^{-\kappa}\mcb e_{-\ell-s}(y)K_{\tau^{p}T^{1/\alpha}}(F_{\varepsilon,T^{1/\alpha}}[0]+R_{\varepsilon,T^{1/\alpha}})(s,y)\,\mathrm{d} s\,\mathrm{d} y\,.
    \end{equs}
    We have used that $\langle y\rangle^\kappa\lesssim\langle y;x\rangle^\kappa\langle x\rangle^\kappa$. Then, using the condition (\@saveref{2/tau2}) and (\@saveref{eq:Kmunu}), we get
    \begin{equs}
