Let $m\in{{\mathchoice{\hbox{\bfN}}{\hbox{\bfN}} 
        {\hbox{\scriptsize\bfN}}{\hbox{\tiny\bfN}}}}$ and $X_1,\dots,X_m$ real-valued random variables. Their joint cumulant is defined as 
\begin{equation}
\mathcal{K}(X_1,\dots,X_m)=(-\mathrm{i})^m\partial_{t_1}\dots\partial_{t_m}\log\bgroup\bgroup\bgroup\bgroup\left.{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}\big[\exp(\mathrm{i} (t_1X_1+\dots+t_mX_m))\big]\right|\egroup\egroup\egroup\egroup_{t_1=\dots=t_m=0}.
\end{equation}

For $\mu\in (0,1]$, $\varepsilon>0$, $m\in{{\mathchoice{\hbox{\bfN}}{\hbox{\bfN}} 
        {\hbox{\scriptsize\bfN}}{\hbox{\tiny\bfN}}}}$, and $n_1,\dots,n_m\in{{\mathchoice{\hbox{\bfN}}{\hbox{\bfN}} 
        {\hbox{\scriptsize\bfN}}{\hbox{\tiny\bfN}}}}$, we let the cumulant
\begin{equation}
\mathcal{K}_{\varepsilon,\mu}^{\boldsymbol{n}^m}(\boldsymbol{z}_1,\dots,\boldsymbol{z}_m)=\mathcal{K}\bgroup\bgroup\bgroup\bgroup\left(\upxi_{\varepsilon,\mu}^{n_1}(\boldsymbol{z}_1),\dots,\upxi_{\varepsilon,\mu}^{n_m}(\boldsymbol{z}_m)\right)\egroup\egroup\egroup\egroup,
\end{equation}
where we have denoted $\boldsymbol{n}^m=(n_1,\dots,n_m)$, and $\boldsymbol{z}_j=(z_1^j,z^j_2)$ for $1\leqslant j\leqslant m$.

