For $U\in{\@fontswitch\relax\mathcal S}'({\Lambda}^{2m})$, we set a norm, that is $L^\infty_{w_1^1}$ in $w_1^1$, $L^{\infty,p}_{t_i,x_i}$ in the $w_i$'s, where $w_i=(t_i,x_i)$, and $L^1_{w^{1:m}_2}$ in all the others. We have let for the rest of Section \ref{sec:stocest}, $p=1\vee d/(2\alpha-2\beta)$.
\begin{equation}
\|U\|_{\mathcal{V}^m}=\sup_{w_1^1\in{\Lambda}}\sup_{t_2,\dots, t_m\in {{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}}\bgroup\bgroup\bgroup\bgroup\left(\int_{({{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d)^{m-1}}\bgroup\bgroup\bgroup\bgroup\left(\int_{{\Lambda}^{m}}\big|U(\boldsymbol{w})|\,\mathrm{d} w^{1:m}_2\right)\egroup\egroup\egroup\egroup^{p}\,\mathrm{d} x^{2:m}_1\right)\egroup\egroup\egroup\egroup^{\frac{1}{p}}\,.
\end{equation}
We further denote by $\mathcal{V}^m$ the vector space of distributions of $2m$ variables such that the above norm is finite. We consequently define the following triple norm.
\begin{equation}
{\Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert \mathcal{K}_{\mu}^{\boldsymbol{n}^m} 
    \Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert}_\mu=\Big\|\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_{\mu,m}^{\alpha-\beta}\bgroup\bgroup\bgroup\bgroup\left(K_\mu^{\otimes 2m}\mathcal{K}^{\boldsymbol{n}^m}\right)\egroup\egroup\egroup\egroup\Big\|_{\mathcal{V}^m}\,,
\end{equation}
where the product with the weight is pointwise.
\begin{remark}
    The power $\alpha-\beta$ is arbitrary. One could have instead chosen any $0<\varsigma<\alpha$ with $\varsigma$ close enough to $\alpha$, but we decide not to add any supplementary notation to avoid to create any confusion with the deterministic analysis.
\end{remark}

We give another example for a graphical representation of this norm.
\begin{equs}
    {\Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert \mathcal{K}_{\varepsilon,\mu}^{(1,1)} 
    \Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert}_\mu=\mathcal{K}\Bigg(\begin{tikzpicture}[scale=0.4,baseline=0.15cm]
            \draw[line width=0.3mm, color=indigo] (0.5,1.25) -- (0.5,2.25);
            \draw[line width=0.3mm, color=indigo] (0,0.25) -- (0,-0.75);
            \draw[line width=0.25mm] (0,0.25) node[dot] {} -- (0.5,1.25) node[dot] {};
            \draw (0,-1.3) node[scale=0.7] {$L^\infty_{w_1^1}$};
            \draw (0,2.75) node[scale=0.7] {$L^1_{w_2^1}$};
\end{tikzpicture},\begin{tikzpicture}[scale=0.4,baseline=0.15cm]
            \draw[line width=0.3mm, color=indigo] (0.5,1.25) -- (0.5,2.25);
            \draw[line width=0.3mm, color=indigo] (0,0.25) -- (0,-0.75);
            \draw[line width=0.25mm] (0,0.25) node[dot] {} -- (0.5,1.25) node[dot] {};
            \draw (0,-1.3) node[scale=0.7] {$L^{\infty,p}_{w_1^2}$};
            \draw (0,2.75) node[scale=0.7] {$L^1_{w_2^2}$};
\end{tikzpicture}\Bigg)\,.
\end{equs}
We have also omitted the weights in this representation.

We define $A_j:{\@fontswitch\relax\mathcal S}'({\Lambda})\times\mathcal{V}^{m+1}\to\mathcal{V}^m$ and $B_j:{\@fontswitch\relax\mathcal S}'({\Lambda})\times\mathcal{V}^{m_1+1}\times\mathcal{V}^{m_2+1}\to\mathcal{V}^m$, with $m_1+m_2=m+1$ by
\begin{equation}
A_j(G,U)(\boldsymbol{w}_1,\dots,\boldsymbol{w}_m)=\int_{{\Lambda}^2}U\big(\boldsymbol{w}_1,\dots,(w_1^j,v_1),(v_2,w_2^j),\dots,\boldsymbol{w}_m\big)G(v_1-v_2)\,\mathrm{d} v_1\,\mathrm{d} v_2\,.
\end{equation}
\begin{multline}
B_j(G,U,V)(\boldsymbol{w}_1,\dots,\boldsymbol{w}_m)=\int_{{\Lambda}^2}U\big(\boldsymbol{w}_1,\dots,(w_1^j,v_1),\dots,\boldsymbol{w}_{m_1}\big)G(v_1-v_2)\\\times V\big((v_2,w_2^j),\boldsymbol{w}_{m_1+1},\dots,\boldsymbol{w}_{m_1+m_2+1}\big)\,\mathrm{d} v_1\,\mathrm{d} v_2\,.
\end{multline}

\label{estimateAB}
The following estimates hold.
\begin{equation}
    \|A_j(G,U)\|_{\mathcal{V}^m}\lesssim\|G\|_{L^{1,q}_{t,x}}\|U\|_{\mathcal{V}^{m+1}}\,.
\end{equation}
We have denoted by $q$ the Hölder conjugate of $p$, {\it i.e.}\@ifnextchar,{}{\ } the only $q>1$ such that $1/p+1/q=1$, with the convention that $q=\infty$ if $p=1$. Moreover, with $m_1+m_2=m+1$,
\begin{equation}
    \|B_j(G,U,V)\|_{\mathcal{V}^m}\lesssim \|U\|_{\mathcal{V}^{m_1+1}}\|G\|_{L_{t,x}^1}\|V\|_{\mathcal{V}^{m_2+1}}\,.
\end{equation}

Let us begin with the estimate on $A_j$. We will keep in a generic way the notations $w=(t,x)$ and $v=(r,u)$. We have, by doing a $L^\infty-L^1$ Hölder inequality in $v_1$, then a $L^p-L^q$ Hölder inequality in $u_2$, and a $L^\infty-L^1$ Hölder inequality in $r_2$,
\begin{equs}
~&\|A_j(G,U)\|_{\mathcal{V}^m}\\&=\sup_{w_1}\sup_{t_{2:m}}\bgroup\bgroup\bgroup\bgroup\left(\int_{({{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d)^{m-1}}\bgroup\bgroup\bgroup\bgroup\left(\int_{{\Lambda}^m}\bgroup\bgroup\bgroup\bgroup\left|\int_{{\Lambda}^2}U\big(\boldsymbol{w}_1,.,(w_1^j,v_1),(v_2,w_2^j),.,\boldsymbol{w}_m\big)G(v_1-v_2)\,\mathrm{d} v_1\,\mathrm{d} v_2\right|\egroup\egroup\egroup\egroup\,\mathrm{d} w_2^{1:m}\right)\egroup\egroup\egroup\egroup^p\,\mathrm{d} x_1^{2:m}\right)\egroup\egroup\egroup\egroup^\frac{1}{p}\\
&\leqslant\sup_{w_1}\sup_{t_{2:m}}\bgroup\bgroup\bgroup\bgroup\left(\int_{({{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d)^{m-1}}\bgroup\bgroup\bgroup\bgroup\left(\int_{{\Lambda}}\int_{{\Lambda}^{m+1}}|U\big(\dots\big)|\,\mathrm{d} v_1\,\mathrm{d} w_2^{1:m}\times\sup_{v_1}|G(v_1-v_2)|\,\mathrm{d} v_2\right)\egroup\egroup\egroup\egroup^p\,\mathrm{d} x_1^{2:m}\right)\egroup\egroup\egroup\egroup^\frac{1}{p}\\
&\leqslant\sup_{w_1}\sup_{t_{2:m}}\Biggl(\int_{({{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d)^{m-1}}\Biggl(\sup_{r_2}\Biggl(\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d}\bgroup\bgroup\bgroup\bgroup\left(\int_{{\Lambda}^{m+1}}|U\big(\dots\big)|\,\mathrm{d} v_1\,\mathrm{d} w_2^{1:m}\right)\egroup\egroup\egroup\egroup^p\,\mathrm{d} u_2\Biggl)^\frac{1}{p}\times\\
&~~~~~~~~\int_{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}\bgroup\bgroup\bgroup\bgroup\left(\int_{{\Lambda}}\sup_{v_1}|G(v_1-v_2)|^q\,\mathrm{d} u_2\right)\egroup\egroup\egroup\egroup^\frac{1}{q}\,\mathrm{d} r_2\Biggl)^p\,\mathrm{d} x_1^{2:m}\Biggl)^\frac{1}{p}\\
&\leqslant\int_{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}\bgroup\bgroup\bgroup\bgroup\left(\int_{{\Lambda}}\sup_{v_1}|G(v_1-v_2)|^q\,\mathrm{d} u_2\right)\egroup\egroup\egroup\egroup^\frac{1}{q}\,\mathrm{d} r_2\sup_{w_1}\sup_{t_{2:m}}\sup_{r_2}\bgroup\bgroup\bgroup\bgroup\left(\int_{({{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d)^{m}}\bgroup\bgroup\bgroup\bgroup\left(\int_{{\Lambda}^{m+1}}|U\big(\dots\big)|\,\mathrm{d} v_1\,\mathrm{d} w_2^{1:m}\right)\egroup\egroup\egroup\egroup^p\,\mathrm{d} x_1^{2:m}\,\mathrm{d} u_2\right)\egroup\egroup\egroup\egroup^\frac{1}{p}\\
&=\int_{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}\bgroup\bgroup\bgroup\bgroup\left(\int_{{\Lambda}} |G(v_2)|^q\,\mathrm{d} u_2\right)\egroup\egroup\egroup\egroup^\frac{1}{q}\,\mathrm{d} r_2\times \|U\|_{\mathcal{V}^{m+1}},
\end{equs}
which concludes the proof of the first estimate. For the second one, the proof is slightly less involved, since we just have to take a supremum in $v_1$ in $G$, and a supremum in $v_2$ in $V$. We get
\begin{equs}
~&\|B_j(G,U,V)\|_{\mathcal{V}^m}\\
&=\sup_{w_1}\sup_{t_{2:m}}\Biggl(\int_{({{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d)^{m-1}}\Biggl(\int_{{\Lambda}^m}\Biggl|\int_{{\Lambda}^2}U\big(\boldsymbol{w}_1,\dots,(w_1^j,v_1),\dots,\boldsymbol{w}_{m_1}\big)G(v_1-v_2)\times\\
&~~~~~~~~ V\big((v_2,w_2^j),\boldsymbol{w}_{m_1+1},\dots,\boldsymbol{v}_{m_1+m_2+1}\big)\,\mathrm{d} v_1\,\mathrm{d} v_2\Biggl|\,\mathrm{d} w_2^{1:m}\Biggl)^p\,\mathrm{d} x_1^{2:m}\Biggl)^\frac{1}{p}\\
&\leqslant\sup_{w_1}\sup_{t_{2:m}}\Biggl(\int_{({{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d)^{m-1}}\Biggl(\int_{{\Lambda}^m}\int_{{\Lambda}^2}|U\big(\boldsymbol{w}_1,\dots,(w_1^j,v_1),\dots,\boldsymbol{w}_{m_1}\big)|\sup_{v_1}|G(v_1-v_2)|\times\\
&~~~~~~~~\sup_{v_2}|V\big((v_2,w_2^j),\boldsymbol{w}_{m_1+1},\dots,\boldsymbol{v}_{m_1+m_2+1}\big)|\,\mathrm{d} v_1\,\mathrm{d} v_2\,\mathrm{d} w_2^{1:m}\Biggl)^p\,\mathrm{d} x_1^{2:m}\Biggl)^\frac{1}{p}\\
&=\sup_{w_1}\sup_{t_{2:m_1}}\Biggl(\int_{({{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d)^{m_1}}\Biggl(\int_{{\Lambda}^{m_1+1}}|U\big(\dots\big)|\,\mathrm{d} v_1\,\mathrm{d} w_2^{1:j-1}\,\mathrm{d} w_2^{j+1:m_1}\Biggl)^p\,\mathrm{d} x_1^{2:m_1}\Biggl)^\frac{1}{p}\times\sup_{v_1}\int_{{\Lambda}}|G(v_1-v_2)|\,\mathrm{d} v_2\times\\
&~~~~\sup_{v_2}\sup_{t_{m_1+1:m_1+m_2+1}}\Biggl(\int_{({{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d)^{m_2}}\Biggl(\int_{{\Lambda}^{m_2+1}}|V\big(\dots\big)|\,\mathrm{d} w_2^j\,\mathrm{d} w_2^{m_1+1:m_1+m_2+1}\Biggl)^p\,\mathrm{d} x_1^{m_1+1:m_1+m_2+1}\Biggl)^\frac{1}{p}\\
&=\|U\|_{\mathcal{V}^{m_1+1}}\|G\|_{L_{t,x}^1}\|V\|_{\mathcal{V}^{m_2+1}}.
\end{equs}

\label{estimateABfancy}
The following estimates hold.
\begin{equation}
{\Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert A_j\big(\dot G_\mu,\mathcal{K}_\mu^{\boldsymbol{n}^m}\big) 
    \Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert}_\mu\lesssim\mu^{-1+\alpha-d/p}{\Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert \mathcal{K}_{\mu}^{\boldsymbol{n}^m} 
    \Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert}_\mu.
\end{equation}
We have denoted by $q$ the Hölder conjugate of $p$, {\it i.e.}\@ifnextchar,{}{\ } the only $q>1$ such that $1/p+1/q=1$, with the convention that $q=\infty$ if $p=1$. Moreover, with $m_1+m_2=m+1$,
\begin{equation}
{\Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert B_j\big(\dot G_\mu,\mathcal{K}_\mu^{\boldsymbol{n}^{m_1}},\mathcal{K}_\mu^{\boldsymbol{n}^{m_2}}\big) 
    \Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert}_\mu\lesssim \mu^{-1+\alpha}{\Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert \mathcal{K}_\mu^{\boldsymbol{n}^{m_1}} 
    \Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert}_\mu{\Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert \mathcal{K}_\mu^{\boldsymbol{n}^{m_2}} 
    \Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert}_\mu.
\end{equation}

We begin by recalling the estimate (\@saveref{triangleineq}) that gives
\begin{equs}
\langle w_1^j;w_2^j\rangle_{\mu}^{\alpha-\beta}&\lesssim\langle w_1^j;v_1\rangle_{\mu}^{\alpha-\beta}\langle v_1;v_2\rangle_{\mu}^{\alpha-\beta}\langle v_2;w_2^j\rangle_{\mu}^{\alpha-\beta}.
\end{equs}
Using it and the fact that $\mathcal{R}^*_\mu K_\mu=\delta_0$, we get that for $U\in\mathcal{V}^{m+1}$,
\begin{equs}
\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_{\mu,m}^{\alpha-\beta} \Big(K_\mu^{\otimes 2m}A_j(\dot G_\mu,U)\Big)=A_j\Big(\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^{\alpha-\beta}\mathcal{R}_\mu^2 \dot G_\mu,\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_{\mu,m+1}^{\alpha-\beta}\big(K_\mu^{\otimes2(m+1)}U\big)\Big).
\end{equs}
and for $U\in\mathcal{V}^{m_1+1}$ and $V\in\mathcal{V}^{m_2+1}$ with $m_1+m_2=m+1$,
\begin{equs}
\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_{\mu,m}^{\alpha-\beta}\Big(K_\mu^{\otimes 2m}B_j(\dot G_\mu,U,V)\Big)=B_j\Big(\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^{\alpha-\beta}\mathcal{R}_\mu^2\dot G_\mu,\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_{\mu,m_1}^{\alpha-\beta}\big(K_\mu^{\otimes 2(m_1+1)}U\big),\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_{\mu,m_2}^{\alpha-\beta}\big(K_\mu^{\otimes 2(m_2+1)}V\big)\Big).
\end{equs}
From that, using the fact that $\|\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^{\alpha-\beta}\mathcal{R}_\mu^2\dot G_\mu\|_{L_{t,x}^1}\lesssim\mu^{-1+\alpha}$ and $\|\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^{\alpha-\beta}\mathcal{R}_\mu^2\dot G_\mu\|_{L_{t,x}^{1,q}}\lesssim\mu^{-1+\alpha-d/p}$ (see Lemma \ref{estimdotGmu}), where we recall that $1/p+1/q=1$, we get, using Lemma \ref{estimateAB},
\begin{equs}
\Big\|\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_{\mu,m}^{\alpha-\beta}\Big( K_\mu^{\otimes 2m}A_j(\dot G_\mu,U)\Big)\Big\|_{\mathcal{V}^{m}}\lesssim\mu^{-1+\alpha-d/p}\Big\|\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_{\mu,m+1}^{\alpha-\beta}\Big(K_\mu^{\otimes 2(m+1)}U\Big)\Big\|_{\mathcal{V}^{m+1}},
\end{equs}
and
\begin{multline*}
    \Big\|\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_{\mu,m}^{\alpha-\beta}\Big(K_\mu^{\otimes 2m}B_j(G,U,V)\Big)\Big\|_{\mathcal{V}^{m}}\lesssim\mu^{-1+\alpha}\Big\|\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_{\mu,m_1}^{\alpha-\beta}\Big(K_\mu^{\otimes 2(m_1+1)}U\Big)\Big\|_{\mathcal{V}^{m_1+1}}\times\\ \Big\|\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_{\mu,m_2}^{\alpha-\beta}\Big(K_\mu^{\otimes 2(m_2+1)}V\Big)\Big\|_{\mathcal{V}^{m_2+1}},
\end{multline*}
which allows to conclude.

Let $U\in\mathcal{V}^1$. We define, for $w_1\in\Lambda$,
\begin{equation}
    ({{\mathchoice{\hbox{\bfI}}{\hbox{\bfI}} 
        {\hbox{\scriptsize\bfI}}{\hbox{\tiny\bfI}}}} U)(w_1)=\int_{{\Lambda}}U(w_1,w_2)\,\mathrm{d} w_2\,,
\end{equation}
as well as, for $k\in{{\mathchoice{\hbox{\bfN}}{\hbox{\bfN}} 
        {\hbox{\scriptsize\bfN}}{\hbox{\tiny\bfN}}}}^{d+1}$ and $w_1,w_2\in\Lambda$,
\begin{equation}
    ({{\mathchoice{\hbox{\bfL}}{\hbox{\bfL}} 
        {\hbox{\scriptsize\bfL}}{\hbox{\tiny\bfL}}}}^k U)(w_1,w_2)=\frac{|k|}{k!}\int_0^1(1-\tau)^{|k|-1}\tau^{-d-\alpha}(X^kU)\big(w_1,w_1+(w_2-w_1)/\tau\big)\,\mathrm{d}\tau\,.
\end{equation}
We have used the notation $X^k(w_1,w_2)=(w_1-w_2)^k$.

\label{taylor}
From the integral form of the Taylor formula, we have, for $U\in\mathcal{V}^1$ and $w_1,w_2\in\Lambda$,
\begin{equation}
    U(w_1,w_2)=({{\mathchoice{\hbox{\bfI}}{\hbox{\bfI}} 
        {\hbox{\scriptsize\bfI}}{\hbox{\tiny\bfI}}}} U)(w_1)\delta(w_2-w_1)+\sum_{|k|_\mathfrak{s}=2}\partial^k_{w_2}({{\mathchoice{\hbox{\bfL}}{\hbox{\bfL}} 
        {\hbox{\scriptsize\bfL}}{\hbox{\tiny\bfL}}}}^kU)(w_1,w_2)\,.
\end{equation}
Moreover, we have the following estimate
\begin{equation}\label{eq:estimI}
    |{{\mathchoice{\hbox{\bfI}}{\hbox{\bfI}} 
        {\hbox{\scriptsize\bfI}}{\hbox{\tiny\bfI}}}} U(w_1)|\leqslant\|U\|_{\mathcal{V}^1}\,.                                                                 
\end{equation}

\label{cumuofproduct}
Let $X_1,\dots,X_m$ as above, and $Y$ and $Z$ real random variables, we have
\begin{equation}
\mathcal{K}(X_1,\dots,X_m,YZ)=\mathcal{K}(X_1,\dots,X_m,Y,Z)+\sum_{I\sqcup J=[m]}\mathcal{K}(X_I,Y)\mathcal{K}(X_J,Z)\,,
\end{equation}
where we have denoted $X_I=\{X_i\colon i\in I\}$.

\label{estimatemoment}
There is a choice of constants $\mathfrak{c}_{\varepsilon}^{n}$ such that for every $m\in{{\mathchoice{\hbox{\bfN}}{\hbox{\bfN}} 
        {\hbox{\scriptsize\bfN}}{\hbox{\tiny\bfN}}}}_{\geqslant1}$ and $\boldsymbol{n}^m$,
\begin{equation}
{\Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert \mathcal{K}_{\varepsilon,\mu}^{\boldsymbol{n}^m} 
    \Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert}_\mu \lesssim \mu^{\deg(\boldsymbol{n}^m)}\,,
\end{equation}
uniformly in $\varepsilon$.

\label{estimatemomentdmu}
    The estimate above holds true for cumulants of the type
    \begin{equation}
        \mathcal{K}\bgroup\bgroup\bgroup\bgroup\left(\upxi_{\varepsilon,\mu}^{n_1}(\boldsymbol{z}_1),\dots,\partial_\mu\upxi_{\varepsilon,\mu}^{n_j}(\boldsymbol{z}_j),\dots,\upxi_{\varepsilon,\mu}^{n_m}(\boldsymbol{z}_m)\right)\egroup\egroup\egroup\egroup\,,
    \end{equation}
    with the difference that the bound scales as $\mu^{\deg(\boldsymbol{n}^m)-1}$.

\textit{Base case.} We first tackle the term having $\boldsymbol{n}^2=(0,0)$ (the other cases being trivial as cumulants of order greater than $2$ of Gaussians vanish), that is, denoting $z_i=(s_i,y_i)$ and $w_i=(t_i,x_i)$,
\begin{equs}
\mathcal{K}\bgroup\bgroup\bgroup\bgroup\left(\upxi_{\varepsilon,\mu}^{0}(z_1),\upxi_{\varepsilon,\mu}^{0}(z_2)\right)\egroup\egroup\egroup\egroup=\langle\nabla\rangle^{2\alpha-2\beta-d}(y_1-y_2)\,,
\end{equs}
which behaves like $|y_1-y_2|^{-2\alpha+2\beta}$ on small scales. Also note that the latter is independent of $s_1$ and $s_2$. We first need to run some preliminary computations. We denote in a generic way $z=(s,y)$ and $w=(t,x)$. We have
\begin{equs}
{\Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert \mathcal{K}_{\varepsilon,\mu}^{\BF{1}^2} 
    \Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert}_\mu=\sup_{w_1^1\in{\Lambda}}\sup_{t_2\in{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}}\Biggl(\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d}\Biggl(\int_{{\Lambda}^2}\langle w_1^1;w_2^1\rangle_\mu^{\alpha-\beta}\langle w_1^2;w_2^2\rangle_\mu^{\alpha-\beta}\bgroup\bgroup\bgroup\bgroup\left|\bgroup\bgroup\bgroup\bgroup\left(K_\mu^{\otimes4}\mathcal{K}_{\varepsilon,\mu}^{\BF{1}^2}\right)\egroup\egroup\egroup\egroup(\boldsymbol{w})\right|\egroup\egroup\egroup\egroup\,\mathrm{d} w_2^1\,\mathrm{d} w_2^2\Biggr)^p\,\mathrm{d} x_1^2\Biggr)^\frac{1}{p}.
\end{equs}
With the changes of variables $w_2^1\to w_2^1+z_1$ and $w_2^2\to w_2^2+z_2$, the estimate $\langle w_1^i;w_2^i+z_i\rangle_\mu^{\alpha-\beta}\lesssim\langle  w_1^i;z_i\rangle_\mu^{\alpha-\beta}\langle w_2^i\rangle_\mu^{\alpha-\beta}$ for $i\in\{1,2\}$ (see (\@saveref{estimweight})), and the fact that $\|\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^{\alpha-\beta} K_\mu\|_{L_{t,x}^1}\lesssim1$, we get that
\begin{equs}
~&\int_{{\Lambda}^2}\langle w_1^1;w_2^1\rangle_\mu^{\alpha-\beta}\langle w_1^2;w_2^2\rangle_\mu^{\alpha-\beta}\bgroup\bgroup\bgroup\bgroup\left(K_\mu^{\otimes4}\mathcal{K}_{\varepsilon,\mu}^{\BF{1}^2}\right)\egroup\egroup\egroup\egroup(\boldsymbol{w})\,\mathrm{d} w_2^1\,\mathrm{d} w_2^2\\
&\lesssim\int_{({{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d)^2}\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^2}\langle w_1^1;z_1\rangle_\mu^{\alpha-\beta}\langle w_1^2;z_2\rangle_\mu^{\alpha-\beta} K_\mu(w_1^1-z_1)K_\mu(w_1^2-z_2)\,\mathrm{d} s_1\,\mathrm{d} s_2\mathcal{K}_{\varepsilon,\mu}^{\BF{1}^2}(y_1,y_2)\,\mathrm{d} y_1\,\mathrm{d} y_2.
\end{equs}
With the help of Lemma \ref{intKmuweight}, we get that the quantity above is bounded by
\begin{equs}
~&\int_{({{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d)^2} \langle x_1^1;y_1\rangle_\mu^{\alpha-\beta}\langle x_1^2;y_2\rangle_\mu^{\alpha-\beta}Q_\mu^{-2N}(x_1^1-y_1)Q_\mu^{-2N}(x_1^2-y_2)\mathcal{K}_{\varepsilon,\mu}^{\BF{1}^2}(y_1,y_2)\,\mathrm{d} y_1\,\mathrm{d} y_2\\
&\lesssim\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d}\langle x_1^1-x_1^2;y\rangle_\mu^{\alpha-\beta}Q_\mu^{-2N}(x_1^1-x_1^2-y)\langle\nabla\rangle^{2\alpha-2\beta-d}(y)\,\mathrm{d} y.
\end{equs}
Note that we have used the invariance by translation of $\mathcal{K}_{\varepsilon,\mu}^{\BF{1}^2}$, and again the fact that $\|\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^{\alpha-\beta} K_\mu\|_{L_{t,x}^1}\lesssim1$. We finally get that 
\begin{equs}
{\Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert \mathcal{K}_{\varepsilon,\mu}^{\BF{1}^2} 
    \Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert}_\mu&\lesssim\sup_{x_1^1}\bgroup\bgroup\bgroup\bgroup\left(\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d}\bgroup\bgroup\bgroup\bgroup\left(\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d}\langle x_1^1-x_1^2;y\rangle_\mu^{\alpha-\beta}Q_\mu^{-2N}(x_1^1-x_1^2-y)\langle\nabla\rangle^{2\alpha-2\beta-d}(y)\,\mathrm{d} y\right)\egroup\egroup\egroup\egroup^p\,\mathrm{d} x_1^2\right)\egroup\egroup\egroup\egroup^\frac{1}{p}\\
&\lesssim\mu^{d/p}\sup_{x_1^1}\bgroup\bgroup\bgroup\bgroup\left(\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d}\bgroup\bgroup\bgroup\bgroup\left(\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d}\langle x_1^1-x_1^2;y\rangle^{\alpha-\beta}\langle\nabla\rangle^{-2N}(x_1^1-x_1^2-y)\langle\nabla\rangle^{2\alpha-2\beta-d}(\mu y)\,\mathrm{d} y\right)\egroup\egroup\egroup\egroup^p\,\mathrm{d} x_1^2\right)\egroup\egroup\egroup\egroup^\frac{1}{p}\\
&=\mu^{d/p}\bgroup\bgroup\bgroup\bgroup\left(\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d}\bgroup\bgroup\bgroup\bgroup\left(\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d}\langle x;y\rangle^{\alpha-\beta}\langle\nabla\rangle^{-2N}(x-y)\langle\nabla\rangle^{2\alpha-2\beta-d}(\mu y)\,\mathrm{d} y\right)\egroup\egroup\egroup\egroup^p\,\mathrm{d} x\right)\egroup\egroup\egroup\egroup^\frac{1}{p}\\
\end{equs}
One can notice that the integrability of this latter quantity in large volume comes around naturally. To make sense of the convolution above, we require that $N>\beta$. We have chosen $p$ such that $\deg(\BF{1}^2)=-2\alpha+2\beta+d/p\leqslant0$, whether we are in the integrable case or not, which is crucial as we would otherwise get that the norm above is bounded by $1$ only. Finally, we have that
\begin{equs}
{\Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert \mathcal{K}_{\varepsilon,\mu}^{\BF{1}^2} 
    \Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert}_\mu\lesssim\mu^{-2\alpha+2\beta+d/p},
\end{equs}
which concludes the base case.\\

\noindent\textit{Induction.} For the induction, we write the following flow equation on the cumulants using Lemma \ref{cumuofproduct}.
\begin{equs}\label{inductionmoment}
~&\partial_\mu \mathcal{K}_{\varepsilon,\mu}^{\boldsymbol{n}^m}(\boldsymbol{z}_1,\dots,\boldsymbol{z}_m)=\sum_{j=1}^m \mathcal{K}\bgroup\bgroup\bgroup\bgroup\left(\upxi_{\varepsilon,\mu}^{n_1}(\boldsymbol{z}_1),\dots,\partial_\mu \upxi_{\varepsilon,\mu}^{n_j}(\boldsymbol{z}_j),\dots,\upxi_{\varepsilon,\mu}^{n_m}(\boldsymbol{z}_m)\right)\egroup\egroup\egroup\egroup\\
&=-\sum_{j=1}^m\sum_{k=1}^{n_j-1}\int_{{\Lambda}^2} \mathcal{K}\bgroup\bgroup\bgroup\bgroup\left(\upxi_{\varepsilon,\mu}^{n_1}(\boldsymbol{z}_1),\dots, \upxi_{\varepsilon,\mu}^{k}(z_1^j,v_1) \upxi_{\varepsilon,\mu}^{n_j-k}(v_2,z_2^j),\dots,\upxi_{\varepsilon,\mu}^{n_m}(\boldsymbol{z}_m)\right)\egroup\egroup\egroup\egroup\dot G_\mu(v_1-v_2)\,\mathrm{d} v_1\,\mathrm{d} v_2\\
&=-\sum_{j=1}^m\sum_{k=1}^{n_j-1}\int_{{\Lambda}^2} \mathcal{K}_{\varepsilon,\mu}^{(n_1,\dots, k,n_j-k,\dots,n_m)}(\boldsymbol{z}_1,\dots,(z_1^j,v_1),(v_2,z_2^j),\dots,\boldsymbol{z}_m)\dot G_\mu(v_1-v_2)\\
&~~~~-\sum_{I\sqcup J=\boldsymbol{n}^m\backslash\{j\}}\mathcal{K}_{\varepsilon,\mu}^{(n_{I\cup\{k\}})}(\boldsymbol{z}_I,(z_1^j,v_1))\dot G_\mu(v_1-v_2)\mathcal{K}_{\varepsilon,\mu}^{(n_{J\cup\{n_j-k\}})}((v_2,z_2^j),\boldsymbol{z}_J)\,\mathrm{d} v_1\,\mathrm{d} v_2\\
&=-\sum_{j=1}^m\sum_{k=1}^{n_j-1}A_j\bigg(\dot G_\mu,\mathcal{K}_{\varepsilon,\mu}^{(n_1,\dots, k,n_j-k,\dots,n_m)}\bigg)-\sum_{I\sqcup J=\boldsymbol{n}^m\backslash\{j\}}B_j\bigg(\dot G_\mu,\mathcal{K}_{\varepsilon,\mu}^{(n_{I\cup\{k\}})},\mathcal{K}_{\varepsilon,\mu}^{(n_{J\cup\{n_j-k\}})}\bigg)
\end{equs}
We have used in the first inequality (\@saveref{eq:Kmunu}) and the fact that, for $\nu\leqslant\mu$, $\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu\leqslant\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\nu$. Note that the cumulants do not depend on the order of their inputs, so that the notation in the penultimate line above is well-defined.

