For irrelevant cumulants, {\it i.e.}\@ifnextchar,{}{\ } the ones having $\deg(\boldsymbol{n}^m)>0$, we have that $\mathcal{K}_{0,\varepsilon}^{\boldsymbol{n}^m}=0$. Indeed, either $m=1$ and it is the expectation of a force term of positive regularity that vanishes when $\mu=0$, or $m\geqslant 2$ and at least one term in the cumulant is deterministic so it vanishes as well. We get, using Lemma \ref{estimateABfancy}, (\@saveref{eq:Kmunu}) and the fact that $\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu\leqslant\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\nu$ for $\nu\leqslant\mu$,
\begin{equs}
~&{\Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert \mathcal{K}_{\varepsilon,\mu}^{\boldsymbol{n}^m} 
    \Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert}_\mu\lesssim\int_0^\mu{\Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert \partial_\nu \mathcal{K}_{\nu,\varepsilon}^{\boldsymbol{n}^m} 
    \Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert}_\nu\,\mathrm{d}\nu\\
&\lesssim\int_0^\mu\sum_{j=1}^m\sum_{k=1}^{n_j-1}\nu^{-1+\alpha-d/p}\nu^{\deg(n_1,\dots, k,n_j-k,\dots,n_m)}+\sum_{I\sqcup J=\boldsymbol{n}^m\backslash\{j\}}\nu^{-1+\alpha}\nu^{\deg(n_{I\cup\{k\}})}\nu^{\deg(n_{J\cup\{n_j-k\}})}\,\mathrm{d}\nu\\
&\lesssim\int_0^\mu\nu^{-1+\alpha-d/p}\nu^{\deg(\boldsymbol{n}^m)+md/p-\alpha}+\nu^{-1+\alpha}\nu^{\deg(\boldsymbol{n}^m)-\alpha}\,\mathrm{d}\nu\lesssim\int_0^\mu\nu^{\deg(\boldsymbol{n}^m)-1}\,\mathrm{d}\nu\\
&\lesssim\mu^{\deg(\boldsymbol{n}^m)}.
\end{equs}

We now turn to the relevant cumulants, {\it i.e.}\@ifnextchar,{}{\ } the ones having $\deg(\boldsymbol{n}^m)\leqslant0$. It is paramount to see that this implies $m=1$. Indeed, if $d\geqslant2\alpha$, recalling the condition (\@saveref{condbeta}), then $p=d/(2\alpha-2\beta)$ and, if $m\geqslant2$,
\begin{equs}
\deg(\boldsymbol{n}^m)\geqslant m(-\alpha+2\beta)+(m-1)\frac{d}{p}=(m-2)\alpha+2\beta>0.
\end{equs}
If we are in the second case {\it i.e.}\@ifnextchar,{}{\ } $\alpha\leqslant2d$, either $p=d/(2\alpha-2\beta)$ and we proceed as above, or $p=1$ and
\begin{equs}
\deg(\boldsymbol{n}^m)\geqslant m(-\alpha+2\beta+d)-d> m\frac{d}{2}-d\geqslant0.
\end{equs}
Our goal is to use the Taylor formula \ref{taylor} to localize these terms, then renormalise the local part, and finally control the remainder. We have,
\begin{equs}
{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\varepsilon,\mu}^n]&=\mathfrak{c}_\varepsilon^n\delta+\int_0^\mu\partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n]\,\mathrm{d}\nu\\
&=\bgroup\bgroup\bgroup\bgroup\left(\mathfrak{c}_\varepsilon^n+\int_0^\mu{{\mathchoice{\hbox{\bfI}}{\hbox{\bfI}} 
        {\hbox{\scriptsize\bfI}}{\hbox{\tiny\bfI}}}}\big(K_\nu^{\otimes2}\partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n]\big)\,\mathrm{d}\nu\right)\egroup\egroup\egroup\egroup\delta+\int_0^\mu{{\mathchoice{\hbox{\bfI}}{\hbox{\bfI}} 
        {\hbox{\scriptsize\bfI}}{\hbox{\tiny\bfI}}}}\Big(\big(\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^{-2}-1\big)\big(K_\nu^{\otimes2}\partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n]\big)\Big)\,\mathrm{d}\nu\times\delta\\
&~~~~+\sum_{|k|_\mathfrak{s}=2}\int_0^\mu\partial^k{{\mathchoice{\hbox{\bfL}}{\hbox{\bfL}} 
        {\hbox{\scriptsize\bfL}}{\hbox{\tiny\bfL}}}}^k\big(\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^{-2}K_\nu^{\otimes2}\partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n]\big)\,\mathrm{d}\nu+\int_0^\mu\bgroup\bgroup\bgroup\bgroup\left(\partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n]-K_\nu^{\otimes2}\partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n]\right)\egroup\egroup\egroup\egroup\,\mathrm{d}\nu\\
&~~~~+\big(\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^{-2}-1\big)\int_0^\mu K_\nu^{\otimes2}\partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n]\,\mathrm{d}\nu.
\end{equs}
Note that we have made a slight abuse of notation by denoting simply $\delta$ the distribution $(z_1,z_2)\mapsto\delta(z_2-z_1)$, and similarly for the weights. We have five terms to control.\\

\noindent\textit{(i)} For the first one, we need to make a choice of renormalising constant $\mathfrak{c}_\varepsilon^n$. Taking
\begin{equs}
\mathfrak{c}_\varepsilon^n=-\int_0^1{{\mathchoice{\hbox{\bfI}}{\hbox{\bfI}} 
        {\hbox{\scriptsize\bfI}}{\hbox{\tiny\bfI}}}}(K_\nu^{\otimes2}\partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n])\,\mathrm{d}\nu,
\end{equs}
yields
\begin{equs}
\mathfrak{c}_\varepsilon^n+\int_0^\mu{{\mathchoice{\hbox{\bfI}}{\hbox{\bfI}} 
        {\hbox{\scriptsize\bfI}}{\hbox{\tiny\bfI}}}}(K_\nu^{\otimes2}\partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n])\,\mathrm{d}\nu=-\int_\mu^1{{\mathchoice{\hbox{\bfI}}{\hbox{\bfI}} 
        {\hbox{\scriptsize\bfI}}{\hbox{\tiny\bfI}}}}(K_\nu^{\otimes2}\partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n])\,\mathrm{d}\nu.
\end{equs}
By (\@saveref{eq:estimI}), we have the bound
\begin{equs}
\int_\mu^1\big|{{\mathchoice{\hbox{\bfI}}{\hbox{\bfI}} 
        {\hbox{\scriptsize\bfI}}{\hbox{\tiny\bfI}}}}(K_\nu^{\otimes2}\partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n]\big|\,\mathrm{d}\nu&\leqslant\int_\mu^1\|K_\nu^{\otimes2}\partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n]\|_{\mathcal{V}^1}\,\mathrm{d}\nu\leqslant\int_\mu^1\big\|\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^{\alpha-\beta}\big(K_\nu^{\otimes2}\partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n]\big)\big\|_{\mathcal{V}^1}\,\mathrm{d}\nu\\
&\leqslant\int_\mu^1{\big\vert\kern-0.25ex\big\vert\kern-0.25ex\big\vert \partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}] 
    \big\vert\kern-0.25ex\big\vert\kern-0.25ex\big\vert}_\nu\,\mathrm{d}\nu\lesssim\int_\mu^1\nu^{\deg(n)-1}\,\mathrm{d}\nu\lesssim\mu^{\deg(n)}.
\end{equs}
Then, following the proof of Lemma 71 in \cite{DGR23},                                                                                                            
\begin{equs}
{\Biggl\vert\kern-0.25ex\Biggl\vert\kern-0.25ex\Biggl\vert \bgroup\bgroup\bgroup\bgroup\@oldleft(\mathfrak{c}_\varepsilon^n+\int_0^\mu{{\mathchoice{\hbox{\bfI}}{\hbox{\bfI}} 
        {\hbox{\scriptsize\bfI}}{\hbox{\tiny\bfI}}}}(K_\nu^{\otimes2}\partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n])\,\mathrm{d}\nu\@oldright)\egroup\egroup\egroup\egroup\delta 
    \Biggl\vert\kern-0.25ex\Biggl\vert\kern-0.25ex\Biggl\vert}_\mu\lesssim\big\|\langle  
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^{\alpha-\beta}K_{2N,\mu}\big\|_{L_{t,x}^1}\int_\mu^1\big|{{\mathchoice{\hbox{\bfI}}{\hbox{\bfI}} 
        {\hbox{\scriptsize\bfI}}{\hbox{\tiny\bfI}}}}(K_\nu^{\otimes2}\partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n])\big|\,\mathrm{d}\nu\lesssim\mu^{\deg(n)}.
\end{equs}
\textit{(ii)} Similarly, we get, for $\nu\leqslant\mu$,
\begin{equs}
~{\Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert {{\mathchoice{\hbox{\bfI}}{\hbox{\bfI}} 
        {\hbox{\scriptsize\bfI}}{\hbox{\tiny\bfI}}}}\Big(\big(\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^{-2}-1\big)\big(K_\mu^{\otimes2}\partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n]\big)\Big)\times\delta 
    \Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert}_\mu&\lesssim\sup_{w_1}\int_{{\Lambda}^2}\langle w_1;w_2\rangle_\mu^{\alpha-\beta} K_\mu(w_1-w)K_\mu(w_2-w)\times\\
&~~~~\int_{\Lambda}\big(\langle w;v\rangle_\mu^{-2}-1\big)\big(K_\mu^{\otimes2}\partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n]\big)(w,v)\,\mathrm{d} v\,\mathrm{d} w\,\mathrm{d} w_2
\end{equs}
Now we use the estimate (\@saveref{triangleineq}) twice to write
\begin{equs}
\langle w_1;w_2\rangle_\mu^{\alpha-\beta}\lesssim\langle w_1;w\rangle_\mu^{\alpha-\beta}\langle w;v\rangle_\mu^{\alpha-\beta}\langle v;w_2\rangle_\mu^{\alpha-\beta},
\end{equs}
so that the quantity above is bounded by
\begin{equs}
~&\big\|\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^{\alpha-\beta}K_\mu\big\|_{L_{t,x}^1}^2\big\|\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^{\alpha-\beta}\big(\langle  
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^{-2}-1\big)\big(K_\mu^{\otimes2}\partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n]\big)\big\|_{\mathcal{V}^1}\lesssim\big\|\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^{\alpha-\beta}\big(\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^{-2}-1\big)\big(K_\nu^{\otimes2}\partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n]\big)\big\|_{\mathcal{V}^1}\\
&\lesssim\bgroup\bgroup\bgroup\bgroup\left\|\frac{\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^{\alpha-\beta}}{\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\nu^{\alpha-\beta}}\big(\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^{-2}-1\big)\right\|\egroup\egroup\egroup\egroup_{L_{t,x}^\infty}{\big\vert\kern-0.25ex\big\vert\kern-0.25ex\big\vert \partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n] 
    \big\vert\kern-0.25ex\big\vert\kern-0.25ex\big\vert}_\nu\lesssim\mu^{\beta-\alpha}\nu^{\alpha-\beta}\nu^{\deg(n)-1}
\end{equs}
For the last inequality, we have used Lemma \ref{estimweight}. Eventually, notice that with our choice of parameters, $\deg(n)+\alpha-\beta>0$. Indeed, following Assumption \ref{condalphabeta}, we have for every $n\geqslant1$, $\deg(n)\geqslant-\alpha+2\beta>-\alpha+\beta$. We get the bound
\begin{equs}
{\Biggl\vert\kern-0.25ex\Biggl\vert\kern-0.25ex\Biggl\vert \int_0^\mu{{\mathchoice{\hbox{\bfI}}{\hbox{\bfI}} 
        {\hbox{\scriptsize\bfI}}{\hbox{\tiny\bfI}}}}\Big(\big(\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^{-2}-1\big)\big(K_\nu^{\otimes2}\partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n]\big)\Big)\,\mathrm{d}\nu\times\delta 
    \Biggl\vert\kern-0.25ex\Biggl\vert\kern-0.25ex\Biggl\vert}_\mu\lesssim\mu^{\beta-\alpha}\int_0^\mu\nu^{\deg(n)+\alpha-\beta-1}\,\mathrm{d}\nu\lesssim\mu^{\deg(n)}\,.
\end{equs}
\textit{(iii)} Fix $k$ such that $|k|_\mathfrak{s}=2$. We use Lemma \ref{estimateiii} to get the delicate estimate,
\begin{equs}
{\Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert \partial^k{{\mathchoice{\hbox{\bfL}}{\hbox{\bfL}} 
        {\hbox{\scriptsize\bfL}}{\hbox{\tiny\bfL}}}}^k\big(\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^{-2}K_\nu^{\otimes2}\partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n]\big) 
    \Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert}_\mu\lesssim\mu^{-2}\nu^2{\big\vert\kern-0.25ex\big\vert\kern-0.25ex\big\vert \partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n] 
    \big\vert\kern-0.25ex\big\vert\kern-0.25ex\big\vert}_\nu
\end{equs}
Then, by induction hypothesis, and proceeding as above, we get
\begin{equs}
{\Biggl\vert\kern-0.25ex\Biggl\vert\kern-0.25ex\Biggl\vert \int_0^\mu\partial^k{{\mathchoice{\hbox{\bfL}}{\hbox{\bfL}} 
        {\hbox{\scriptsize\bfL}}{\hbox{\tiny\bfL}}}}^k\big(\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^{-2}K_\nu^{\otimes2}\partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n]\big)\,\mathrm{d}\nu 
    \Biggl\vert\kern-0.25ex\Biggl\vert\kern-0.25ex\Biggl\vert}_\mu\lesssim\mu^{-2}\int_0^\mu\nu^{\deg(n)+1}\,\mathrm{d}\nu\lesssim\mu^{\deg(n)}\,.
\end{equs}
\textit{(iv)} We have, for $\nu\leqslant\mu$,
\begin{equs}
    {\Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert \partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n]-K_\nu^{\otimes2}\partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n] 
    \Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert}_\mu&=\Big\|\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^{\alpha-\beta}(K_\mu^{\otimes2}- K_\mu^{\otimes2}K_\nu^{\otimes2})\partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n]\Big\|_{\mathcal{V}^1}


\end{equs}
Noticing that, for any $\mu,\nu\in(0,1]$, one has $K_\mu-K_\mu K_\nu=\mu^{-\alpha}\nu^\alpha(K_\nu-K_\nu K_\mu)$, we get
\begin{equs}
~&K_\mu^{\otimes2}-K_\mu^{\otimes2}K_\nu^{\otimes2}=K_\mu^{\otimes2}\big(\delta\otimes(\delta-K_\nu)\big)+K_\mu^{\otimes2}\big(K_\nu\otimes(\delta-K_\nu)\big)\\
&\leqslant\mu^{-\alpha}\nu^\alpha\Big(K_\mu\otimes\big(K_\nu(\delta-K_\mu)\big)\Big)+\mu^{-\alpha}\nu^\alpha\Big(K_\mu K_\nu\otimes\big(K_\nu(\delta-K_\mu)\big)\Big)
\end{equs}
To control these terms, we state that $K_\mu=\mathcal{R}_\nu K_\mu*K_\nu$ and recall that $\|\mathcal{R}_\nu K_\mu\|_{L_{t,x}^1}=1$ for $\nu\leqslant\mu$ (see for example \cite{Duc22}, Lemma 4.5). We also use the crude estimate $\|\delta-K_\mu\|_{L_{t,x}^1}\leqslant2$. Using Young's convolution inequality and the same trick on the weights as in \textit{(ii)}, we eventually get that
\begin{equs}
{\Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert \partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n]-K_\nu^{\otimes2}\partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n] 
    \Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert}_\mu\lesssim\mu^{-\alpha}\nu^\alpha{\big\vert\kern-0.25ex\big\vert\kern-0.25ex\big\vert \partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n] 
    \big\vert\kern-0.25ex\big\vert\kern-0.25ex\big\vert}_\nu\lesssim\mu^{-\alpha}\nu^{\deg(n)+\alpha-1}\,,
\end{equs}
and we can thus conclude as in \textit{(ii)}, noticing that we have $\deg(n)+\alpha>0$ for $n\geqslant1$.\\

\noindent\textit{(v)} We proceed with the same weight decomposition as in \textit{(ii)} and with Lemma \ref{estimweight}. It yields, for $\nu\leqslant\mu$,
\begin{equs}
{\Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert \big(\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^{-2}-1\big) K_\nu^{\otimes2}\partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n] 
    \Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert}_\nu&\lesssim\big\|\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^{\alpha-\beta} K_\mu\big\|_{L_{t,x}^1}^2\big\|\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^{\alpha-\beta}\big(\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^{-2}-1\big)K_\nu^{\otimes2}\partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n]\big\|_{\mathcal{V}^1}\\
&\lesssim\bgroup\bgroup\bgroup\bgroup\left\|\frac{\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^{\alpha-\beta}}{\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\nu^{\alpha-\beta}}\big(\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^{-2}-1\big)\right\|\egroup\egroup\egroup\egroup_{L_{t,x}^\infty}{\big\vert\kern-0.25ex\big\vert\kern-0.25ex\big\vert \partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n] 
    \big\vert\kern-0.25ex\big\vert\kern-0.25ex\big\vert}_\nu\lesssim\mu^{\beta-\alpha}\nu^{\deg(n)+\alpha-\beta-1}\,,
\end{equs}
and we conclude as in case \textit{(ii)}.\\
Putting everything together, we have the desired estimate
\begin{equs}
{\big\vert\kern-0.25ex\big\vert\kern-0.25ex\big\vert {{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\varepsilon,\mu}^n] 
    \big\vert\kern-0.25ex\big\vert\kern-0.25ex\big\vert}_\mu\lesssim\mu^{\deg(n)}\,.
\end{equs}
This concludes the proof of Proposition \ref{estimatemoment}.

