\label{estimateiii}
Let $\nu\leqslant\mu$, and $k$ such that $|k|_\mathfrak{s}=2$. The following estimate holds
\begin{equs}
{\Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert \partial^k{{\mathchoice{\hbox{\bfL}}{\hbox{\bfL}} 
        {\hbox{\scriptsize\bfL}}{\hbox{\tiny\bfL}}}}^k\big(\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^{-2}K_\nu^{\otimes2}\partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n]\big) 
    \Big\vert\kern-0.25ex\Big\vert\kern-0.25ex\Big\vert}_\mu\lesssim\mu^{-2}\nu^2{\big\vert\kern-0.25ex\big\vert\kern-0.25ex\big\vert \partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n] 
    \big\vert\kern-0.25ex\big\vert\kern-0.25ex\big\vert}_\nu
\end{equs}

We first write the left-hand side as
\begin{equs}
\sup_{w_1\in{\Lambda}}\int_{\Lambda}\langle w_1;w_2\rangle_\mu^2 \bgroup\bgroup\bgroup\bgroup\left|\int_{{\Lambda}^2}K_\mu(w_1-v_1)K_\mu(w_2-v_2)\partial^k_{v_2}{{\mathchoice{\hbox{\bfL}}{\hbox{\bfL}} 
        {\hbox{\scriptsize\bfL}}{\hbox{\tiny\bfL}}}}^k\big(\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^{-2}K_\nu^{\otimes2}\partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n]\big)(v_1,v_2)\,\mathrm{d} v_1\,\mathrm{d} v_2\right|\egroup\egroup\egroup\egroup\,\mathrm{d} w_2\,.
\end{equs}
Let us carry a change of variable on ${{\mathchoice{\hbox{\bfL}}{\hbox{\bfL}} 
        {\hbox{\scriptsize\bfL}}{\hbox{\tiny\bfL}}}}^k$. We have, for fixed $w_2$ and $v_1$, and $U\in\mathcal{V}^1$,
\begin{equs}
~&\int_{\Lambda} K_\mu(w_2-v_2)\partial^k_{v_2}({{\mathchoice{\hbox{\bfL}}{\hbox{\bfL}} 
        {\hbox{\scriptsize\bfL}}{\hbox{\tiny\bfL}}}}^kU)(v_1,v_2)\,\mathrm{d} v_2\\
&=\int_{\Lambda} \partial^k K_\mu(w_2-v_2)\frac{|k|}{k!}\int_0^1(1-\tau)^{|k|-1}\tau^{-d-\alpha}(X^kU)\big(v_1,v_1+(v_2-v_1)/\tau\big)\,\mathrm{d}\tau\,\mathrm{d} v_2\\
&=\frac{|k|}{k!}\int_0^1(1-\tau)^{|k|-1}\int_{\Lambda} \partial^k K_\mu\big(w_2-v_1-\tau(v_2-v_1)\big)(X^kU)(v_1,v_2)\,\mathrm{d} v_2\,\mathrm{d}\tau\,.
\end{equs}
Using again the estimate (\@saveref{estimweight}),
\begin{equs}
\langle w_1;w_2\rangle_\mu^2\lesssim\langle w_1;v_1\rangle_\mu^2\langle v_1;v_1+\tau(v_2-v_1)\rangle_\mu^2\langle v_1+\tau(v_2-v_1);w_2\rangle_\mu^2\,,
\end{equs}
and noticing that $\langle v_1;v_1+\tau(v_2-v_1)\rangle_\mu^2\lesssim\langle v_1;v_2\rangle_\mu^2$, we have, using Young's convolution inequality two times, that our quantity of interest is bounded by
\begin{equs}
~&\big\|\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^2 K_\mu\big\|_{L^1_{t,x}}\big\|\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^2 \partial^k K_\mu\big\|_{L^1_{t,x}}\big\| X^k\big(K_\nu^{\otimes2}\partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n]\big)\big\|_{\mathcal{V}^1}\\
&\lesssim\mu^{-2}\big\|X^k\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\nu^{-2}\big\|_{L_{t,x}^\infty}{\big\vert\kern-0.25ex\big\vert\kern-0.25ex\big\vert \partial_\nu{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[\upxi_{\nu,\varepsilon}^n] 
    \big\vert\kern-0.25ex\big\vert\kern-0.25ex\big\vert}_\nu.
\end{equs}
Since $\big\|X^k\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\nu^{-2}\big\|_{L_{t,x}^\infty}\leqslant\nu^2$, we get the desired result.

\label{momentkolmogorov}
For every $\kappa>0$, $m\in2{{\mathchoice{\hbox{\bfN}}{\hbox{\bfN}} 
        {\hbox{\scriptsize\bfN}}{\hbox{\tiny\bfN}}}}$, and $\ell\in{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}$, it holds
    \begin{equation}
        {{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}\Big[
\,\begin{tikzpicture}[baseline=-0.7ex]
    \draw[line width=.5pt] (0,-0.2) rectangle (0.08,0.20);
\end{tikzpicture}\,
\upxi
\,\begin{tikzpicture}[baseline=-0.7ex]
    \draw[line width=.5pt] (0,-0.2) rectangle (0.08,0.20);
\end{tikzpicture}\,
^m_{\kappa,\ell,\varsigma}\Big]\lesssim \big(m(n+1)\big)^{m/2}\,,
    \end{equation}
    with $0<\varsigma<\alpha$ if $\alpha<2$ and $\varsigma>0$ if $\alpha=2$.

In regard of Lemma \ref{supinside}, it is sufficient to show that, for $s\in\{0,1\}$,
\begin{equs}
    {{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}\left[\|\partial_\mu^s\upxi_{\varepsilon,\mu}^n\|_{\mu,\kappa,\ell,\varsigma}^m\right]\egroup\egroup\egroup\egroup\lesssim\mu^{m\deg(n)-s-\kappa m}\,.
\end{equs}
It is easy to see that, thanks to Corollary \ref{estimatemomentdmu}, it suffices to show the above with $s=0$ and that the other case is dealt with similarly. Using Lemmas \ref{lemma:incrmoment} and \ref{lemma:transfercompactweight}, it is sufficient to show that (for some potentially bigger $m$)
\begin{equs}
    {{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}\left[\bgroup\bgroup\bgroup\bgroup\left(\sup_{w_1\in{\Lambda}}\langle w_1\rangle^{-\kappa}\int_{\Lambda}\langle w_1;w_2\rangle_\mu^{\varsigma-\kappa}\mcb e_{\ell}(x_1;x_2)\mcb k_\mu(w_1;w_2)\big|\big(K_\mu^{\otimes2}\upxi_{\varepsilon,\mu}^n\big)(w_1,w_2)\big|\,\mathrm{d} w_2\right)\egroup\egroup\egroup\egroup^m\right]\egroup\egroup\egroup\egroup\lesssim\mu^{m\deg(n)-\kappa}\,,
\end{equs}
where $\mcb k_\mu$ is a smooth function supported in the parabolic ball of radius $\mu$ and we denoted for compactness $\mcb k_\mu(w_1;w_2)=\mcb k_\mu(w_1-w_2)$. This quantity is bounded by
\begin{equs}
~&\bgroup\bgroup\bgroup\bgroup\left(\sup_{w_1\in{\Lambda}}\int_{\Lambda}\langle w_1;w_2\rangle_\mu^{\varsigma-\kappa}\mcb e_{\ell}(x_1;x_2)\mcb k_\mu(w_1;w_2)\,\mathrm{d} w_2\right)\egroup\egroup\egroup\egroup^m\times{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}\left[\bgroup\bgroup\bgroup\bgroup\left(\sup_{w_1,w_2\in{\Lambda}}\langle w_1\rangle^{-\kappa}\big|\big(K_\mu^{\otimes2}\upxi_{\varepsilon,\mu}^n\big)(w_1,w_2)\big|\right)\egroup\egroup\egroup\egroup^m\right]\egroup\egroup\egroup\egroup\\
&\lesssim\mu^{m(d+\alpha)}{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}\left[\bgroup\bgroup\bgroup\bgroup\left(\sup_{w_1,w_2\in{\Lambda}}\langle w_1\rangle^{-\kappa}\big|\big(K_\mu^{\otimes2}\upxi_{\varepsilon,\mu}^n\big)(w_1,w_2)\big|\right)\egroup\egroup\egroup\egroup^m\right]\egroup\egroup\egroup\egroup.
\end{equs}
Using Lemma \ref{LinfLm} below, it is bounded by
\begin{equs}
\mu^{(m-2)(d+\alpha)}{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}\Big[\big\|\langle w_1\rangle^{-\kappa}\big(K_{N-1,\mu}^{\otimes2}\upxi_{\varepsilon,\mu}^n\big)\big\|_{L^m_{w_1,w_2}}^m\Big].
\end{equs}
Let us take a closer look at the expectation appearing here. Using Fubini's theorem, it is equal to
\begin{equs}
~&\int_{{\Lambda}^2}\langle w_1\rangle^{-\kappa m}{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}\left[\big|\big(K_{N-1,\mu}^{\otimes2}\upxi_{\varepsilon,\mu}^n\big)(w_1,w_2)\big|^m\right]\egroup\egroup\egroup\egroup\,\mathrm{d} w_1\,\mathrm{d} w_2\\
&\lesssim\int_{{\Lambda}^2}\langle w_1\rangle^{-\kappa m}\langle w_1;w_2\rangle_\mu^{-(\alpha-\beta)m}{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}\left[\Big|\langle w_1;w_2\rangle_\mu^{\alpha-\beta}\big(K_{N-1,\mu}^{\otimes2}\upxi_{\varepsilon,\mu}^n\big)(w_1,w_2)\Big|^m\right]\egroup\egroup\egroup\egroup\,\mathrm{d} w_1\,\mathrm{d} w_2\\
&\lesssim\int_{{\Lambda}^2}\langle w_1\rangle^{-\kappa m}\langle w_1;w_2\rangle_\mu^{-(\alpha-\beta)m}\,\mathrm{d} w_1\,\mathrm{d} w_2\times\sup_{w_1,w_2\in{\Lambda}}{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}\left[\Big|\langle w_1;w_2\rangle_\mu^{\alpha-\beta}\big(K_{N-1,\mu}^{\otimes2}\upxi_{\varepsilon,\mu}^n\big)(w_1,w_2)\Big|^m\right]\egroup\egroup\egroup\egroup\\
&\lesssim \big(m(n+1)\big)^{m(n+1)/2}\mu^{d+\alpha}\sup_{w_1,w_2\in{\Lambda}}{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}\left[\Big|\langle w_1;w_2\rangle_\mu^{\alpha-\beta}\big(K_{N-1,\mu}^{\otimes2}\upxi_{\varepsilon,\mu}^n\big)(w_1,w_2)\Big|^2\right]\egroup\egroup\egroup\egroup^{m/2}
\end{equs}
We used hypercontractivity in the last inequality. Then we use the moment-cumulant relation (\@saveref{momcumu}) to develop the expectation above in cumulants. Moreover, using Lemma \ref{LinfV} and Proposition \ref{estimatemoment}, we get, putting everything together,
\begin{equs}
    {{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}\left[\|\upxi_{\varepsilon,\mu}^n\|_{\mu}^m\right]\egroup\egroup\egroup\egroup&\lesssim \big(m(n+1)\big)^{m(n+1)/2}\mu^{(m-1)(d+\alpha)}\mu^{-\frac{m}{2}\big(d/p+2(d+\alpha)\big)}\mu^{\frac{m}{2}(2\deg(n)+d/p)}\\
    &=\big(m(n+1)\big)^{m(n+1)/2}\mu^{m\deg(n)-m\kappa},
\end{equs}
where we have set $\kappa=(d+\alpha)/m$. It then yields the desired result.

\label{lemma:incrmoment}
For any $n,m\in {{\mathchoice{\hbox{\bfN}}{\hbox{\bfN}} 
        {\hbox{\scriptsize\bfN}}{\hbox{\tiny\bfN}}}}$ it holds
    \begin{equation}\label{eq:incrmoment}
        \sup_{\mu\in(0,1]}\mu^{-\deg(n)+\kappa_n}{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}\big[\|\upxi_{\varepsilon,\mu}^n\|_{\mu,\kappa_n,\ell,\varsigma}^m\big]^\frac{1}{m}\lesssim1+\sup_{i\leqslant n}\sup_{\mu\in(0,1]}\Big(\mu^{-\deg(i)+\kappa_i}{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}\big[\|\mcb k_\mu\upxi_{\varepsilon,\mu}^i\|_{\mu,\kappa_i,\ell,\varsigma}^{2^n m}\big]^\frac{1}{2^nm}\Big)^{2^n}\,,
    \end{equation}
    and
    \begin{equation}\label{eq:incrmomentderivative}
        \sup_{\mu\in(0,1]}\mu^{-\deg(n)+1+\kappa_n}{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}\big[\|\partial_\mu\upxi_{\varepsilon,\mu}^n\|_{\mu,\kappa_n,\ell,\varsigma}^m\big]^\frac{1}{m}\lesssim1+\sup_{i\leqslant n}\sup_{\mu\in(0,1]}\Big(\mu^{-\deg(i)+\kappa_i}{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}\big[\|\mcb k_\mu\upxi_{\varepsilon,\mu}^i\|_{\mu,\kappa_i,\ell,\varsigma}^{2^n m}\big]^\frac{1}{2^nm}\Big)^{2^n}\,.
    \end{equation}

The proof follows quite closely the one of Lemma 38 in \cite{DGR23}, with the slight difference that we need to take into account the exponential weights. The proof works by induction on $n$. Let us first prove (\@saveref{eq:incrmomentderivative}) for $n$, assuming that (\@saveref{eq:incrmoment}) and (\@saveref{eq:incrmomentderivative}) hold for all $i\leqslant n$. We have, using (\@saveref{triangleineq}) and Lemma \ref{ITexp},
    \begin{equs}
        \langle w_1;w_2\rangle_\mu^{\varsigma-\kappa_n}\lesssim\langle w_1;z_1\rangle_\mu^{\varsigma-\kappa_n}\langle z_1;z_2\rangle_\mu^{\varsigma}\langle z_2;w_2\rangle_\mu^{\varsigma-\kappa_j}\,,
    \end{equs}
    and
    \begin{equs}
        \mcb e_\ell(x_1;x_2)\lesssim\mcb e_\ell(x_1;y_1)\mcb e_\ell(y_1;y_2)\mcb e_\ell(y_2;x_2)\,.
    \end{equs}
    Using the flow equation on coefficients (\@saveref{eq:hierarchyxi}), we get
    \begin{equs}
        ~&\sup_{w_1\in\Lambda}\int_\Lambda \langle w_1\rangle^{-2^n \kappa}\langle w_1;w_2\rangle_\mu^{\varsigma-\kappa_n}\mcb e_\ell(x_1;x_2)\big|\big(K_\mu^{\otimes2}\partial_\mu\upxi_{\varepsilon,\mu}^n\big)(w_1,w_2)\big|\,\mathrm{d} w_2\\
        &\lesssim\sum_{i+j=n-1}\sup_{w_1\in\Lambda}\int_\Lambda \langle w_1\rangle^{-\kappa_i}\langle w_1;z_1\rangle_\mu^{\varsigma-2^{i}\kappa}\mcb e_\ell(x_1;y_1)\big|\big(K_\mu^{\otimes2}\upxi_{\varepsilon,\mu}^i\big)(w_1,w_2)\big|\,\mathrm{d} z_1\\
        &\quad\times\sup_{z_1\in\Lambda}\int_\Lambda \langle z_1;z_2\rangle^{\kappa_j} \mcb e_\ell(y_1;y_2) \big|\big(\mathcal{R}^2_\mu\dot G_\mu\big)(z_1,z_2)\big|\,\mathrm{d} z_2\\
        &\quad\times \sup_{z_2\in\Lambda}\int_\Lambda \langle z_2\rangle^{-\kappa_j}\langle z_2;w_2\rangle_\mu^{\varsigma-\kappa_j}\mcb e_\ell(y_2;x_2)\big|\big(K_\mu^{\otimes2}\upxi_{\varepsilon,\mu}^j\big)(z_2,w_2)\big|\,\mathrm{d} w_2\,.
    \end{equs}
    We have used the inequality $\langle z_2\rangle^{\kappa_j}\lesssim\langle z_2;z_1\rangle_\mu^{\kappa_j}\langle z_1;w_1\rangle_\mu^{\kappa_j} \langle w_1\rangle^{\kappa_j}$. It yields, using Lemma \ref{heatkernelestimate} and the Hölder inequality,
    \begin{multline*}
        \mu^{-\deg(n)+1+\kappa_n}{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}\big[\|\partial_\mu\upxi_{\varepsilon,\mu}^n\|_{\mu,\kappa_n,\ell,\varsigma}^m\big]^\frac{1}{m}\\\lesssim\sum_{i+j=n-1}\mu^{-\deg(i)+\kappa_i}{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}\big[\|\upxi_{\varepsilon,\mu}^i\|_{\mu,\kappa_i,\ell,\varsigma}^{2m}\big]^\frac{1}{2m}\mu^{-\deg(j)+\kappa_j}{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}\big[\|\upxi_{\varepsilon,\mu}^j\|_{\mu,\kappa_j,\ell,\varsigma}^{2m}\big]^\frac{1}{2m}\,,
    \end{multline*}
    which concludes the proof of (\@saveref{eq:incrmomentderivative}). The proof of (\@saveref{eq:incrmoment}) follows as in \cite[Lemma 38]{DGR23}. The important point to see this is that the exponential weights do not depend on $\mu$, and this do not interact with the other weights in the proof.

\label{lemma:transfercompactweight}
    There is a kernel $\Tilde {\mcb k}_\mu$ with compact support in the parabolic ball of radius $\mu$ such that
    \begin{equation}
        \|\mcb k_\mu\upxi_{\varepsilon,\mu}^n\|_{\mu,\kappa,\ell,\varsigma}\lesssim\sup_{w_1\in\Lambda}\int_\Lambda \langle w_1\rangle^{-\kappa_n}\langle w_1;w_2\rangle^{\varsigma-\kappa_n}_\mu\mcb e_\ell(x_1;x_2)\Tilde {\mcb k}_\mu(w_1;w_2)\big|\big(K_\mu^{\otimes2}\upxi_{\varepsilon,\mu}^n\big)(w_1,w_2)\big|\,\mathrm{d} w_2\,.
    \end{equation}

We have
    \begin{equs}
        \big(K_\mu^{\otimes2}\mcb k_\mu\upxi_{\varepsilon,\mu}^n\big)(w_1,w_2)&=\int_{\Lambda^2}K_\mu(w_1-z_1)K_\mu(w_2-z_2)\mcb k_\mu(z_1;z_2)\upxi_{\varepsilon,\mu}^n(z_1,z_2)\,\mathrm{d} z_1\,\mathrm{d} z_2\\
        &=\int_{\Lambda^2}\mathcal{R}_\mu^2\Big(K_\mu(w_1-z_1)K_\mu(w_2-z_2)\mcb k_\mu(z_1;z_2)\Big)\big(K_\mu^{\otimes2}\upxi_{\varepsilon,\mu}^n\big)(z_1,z_2)\,\mathrm{d} z_1\,\mathrm{d} z_2\,,
    \end{equs}
    where the operators $\mathcal{R}_\mu$ act on the $z$ variables. One can see that there is a discrete set $\mathfrak{P}$ such that
    \begin{multline*}
        \mathcal{R}_\mu^2\Big(K_\mu(w_1-z_1)K_\mu(w_2-z_2)\mcb k_\mu(z_1;z_2)\Big)\\=\sum_{\pi_1,\pi_2,\pi_3\in \mathfrak{P}}({\@fontswitch\relax\mathcal S}_\mu K^{\pi_1})(w_1-z_1)({\@fontswitch\relax\mathcal S}_\mu K^{\pi_2})(w_2-z_2)\mcb k_\mu^{\pi_3}(z_1;z_2)\,,
    \end{multline*}
    where $K^\pi$ is integrable with exponential decay, and $\mcb k_\mu^{\pi}$ has compact support in the parabolic ball of radius $\mu$. For more details, we refer the reader to the proof of Lemma 61 in \cite{DGR23}. Letting $\Tilde{\mcb k}_\mu=\sum_\pi \mcb k_\mu^{\pi}$, using the same triangle inequalities as in the proof of Lemma \ref{lemma:incrmoment}, and using Young's convolution inequality, one can conclude the proof.

We have, for $m\in{{\mathchoice{\hbox{\bfN}}{\hbox{\bfN}} 
        {\hbox{\scriptsize\bfN}}{\hbox{\tiny\bfN}}}}$,
\begin{equation}\label{momcumu}
{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}[X_1\dots X_m]=\sum_{j=1}^m\sum_{I_1\sqcup\dots\sqcup I_j=[m]}\mathcal{K}(X_{I_1})\times\dots\times\mathcal{K}(X_{I_j}).
\end{equation}

\label{LinfLm}
Let $m\in2{{\mathchoice{\hbox{\bfN}}{\hbox{\bfN}} 
        {\hbox{\scriptsize\bfN}}{\hbox{\tiny\bfN}}}}$ and $U\in L^\infty_{w_1,w_2}$. The following estimate holds
\begin{equs}
    {{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}\Big[\big\|K_{1,\mu}^{\otimes2}U\big\|_{L^\infty_{w_1,w_2}}^m\Big]\lesssim\mu^{-2(d+\alpha)}{{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
