\label{LinfV}
Let $U\in \mathcal{V}^2$. The following estimate holds
\begin{equs}
\big\|\langle  
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_{\mu,2}^{\alpha-\beta} K_{1,\mu}^{\otimes4}U\big\|_{L^\infty(\Lambda^4)}^2\lesssim\mu^{-2(d+\alpha)-d/p}\big\|\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_{\mu,2}^{\alpha-\beta}U\big\|_{\mathcal{V}^2}.
\end{equs}

Let us write, using the notations introduced at the beginning of Section~\ref{sec:stocest},
    \begin{equs}
        \big\|\langle  
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_{\mu,2}^{\alpha-\beta} K_{1,\mu}^{\otimes4}U\big\|_{L^\infty(\Lambda^4)}&=\sup_{\boldsymbol{w}\in\Lambda^4}\langle w_1^1;w_2^1\rangle_\mu^{\alpha-\beta}\langle w_1^2;w_2^2\rangle_\mu^{\alpha-\beta}\big|\big(K_{1,\mu}^{\otimes4}U\big)(\boldsymbol{w})\big|\\
        &\leqslant\sup_{\boldsymbol{w}\in\Lambda^4}\langle w_1^1;w_2^1\rangle_\mu^{\alpha-\beta}\langle w_1^2;w_2^2\rangle_\mu^{\alpha-\beta}\\
        &\quad\times\int_{\Lambda^4} \prod_{i=1}^2 K_{1,\mu}(w_1^i-z_1^i)K_{1,\mu}(w_2^i-z_2^i)|U(\boldsymbol{z})|\,\mathrm{d}\boldsymbol{z}\,.
