    \end{equation}
    then
    \begin{equation}
        {{\mathchoice{\hbox{\bfE}}{\hbox{\bfE}} 
        {\hbox{\scriptsize\bfE}}{\hbox{\tiny\bfE}}}}\Big[\Big(\sup_{\mu\in(0,1]}\mu^{-\eta}\|\uplambda_\mu\|_{\mathcal{V}^1}\Big)^m\Big]^\frac{1}{m}\lesssim1\,.
