Let $A$ be an unbounded operator on a Banach space $E$. We say that $A$ is sectorial of angle $\theta\in(0,\pi)$ (or $\theta$-sectorial) if
    \begin{equation}\label{Def:SectorialOp1}
        \sigma(A)\subset\overline{\Sigma_\theta}
    \end{equation}
    and for all $\omega\in(\theta,\pi)$ it holds
    \begin{equation}\label{Def:SectorialOp2}
        \sup_{\lambda\in{{\mathchoice{\hbox{\bfC}}{\hbox{\bfC}} 
        {\hbox{\scriptsize\bfC}}{\hbox{\tiny\bfC}}}}\backslash\overline{\Sigma_{\omega}}} |\lambda|\big\|(\lambda-A)^{-1}\big\|<\infty.
    \end{equation}
    We say an operator $A$ is quasi-$\theta$-sectorial if $A+\delta$ is $\theta$-sectorial for some $\delta>0$. We say an operator is quasi-sectorial if it is quasi-$\theta$-sectorial for some $\theta$. We denote by $$\theta_S(A)=\inf\bgroup\bgroup\bgroup\bgroup\left\{\theta\in(0,\pi),\; A \text{ is $\theta$-sectorial}\right\}\egroup\egroup\egroup\egroup\in[0,\pi)$$
    the infimum of angles for which $A$ is sectorial.

Let $E$ be a Banach space. A family $\big(S(t)\big)_{t\geqslant 0}$ of bounded linear maps is called a $\mathcal{C}_0$-semigroup if it verifies
    \begin{enumerate}
        \par\hangindent 40\p@ $S(0)=1$,
        \par\hangindent 40\p@ for every $t,s>0$, $S(t)S(s)=S(t+s)$ and
        \par\hangindent 40\p@ for every $x\in E$, $S(t)x-x$ converges to $0$ as $t$ goes to $0$.
    \end{enumerate}
    A $\mathcal{C}_0$-semigroup is called exponentially bounded if 
    $$\omega_E(S) = \inf_{t>0}\frac{1}{t}\log\|S(t)\|_{\mathcal{L}(E)}\in{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}},$$
    or equivalently, if there exists $M>0$ and $\omega\in{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}$ such that
    $$\forall t>0,\; \|S(t)\|_{\mathcal{L}(E)}\leqslant M\mathrm{e}^{\omega t}.$$
    The real $\omega_E(S)$ is then called the growth bound of $S$ and is the infimum of the $\omega$ for which the previous bound holds for some $M$.

\label{Prop:Hille-Yosida}
    An unbounded operator $A\colon\mathrm{D}(A)\subset E\to E$ generates a $\mathcal{C}_0$-semigroup $S$ on $E$ verifying 
    $$\forall t>0,\; \|S(t)\|_{\mathcal{L}(E)}\leqslant M\mathrm{e}^{\omega t}\,,$$
    if and only if
    \begin{itemize}
        \par\hangindent 40\p@ $A$ is closed and densely defined,
        \par\hangindent 40\p@ for any ${\mathchoice{\hbox{\rmRe}}{\hbox{\rmRe}} 
        {\hbox{\scriptsize\rmRe}}{\hbox{\tiny\rmRe}}}\lambda>\omega$ and any $n\in{{\mathchoice{\hbox{\bfN}}{\hbox{\bfN}} 
        {\hbox{\scriptsize\bfN}}{\hbox{\tiny\bfN}}}}_{\geqslant1}$,
        $$\big\|(\lambda-A)^{-n}\big\|_{\mathcal{L}(E)}\leqslant\frac{M}{({\mathchoice{\hbox{\rmRe}}{\hbox{\rmRe}} 
        {\hbox{\scriptsize\rmRe}}{\hbox{\tiny\rmRe}}}\lambda-\omega)^n}\,.$$
    \end{itemize}

\label{Prop:KleinLandau}
    Fix $T>0$. Let $\big(S(t)\big)_{t\in[0,T]}$ be a collection of unbounded operators on a Hilbert space $\mathcal{H}$ with inner product $\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
, 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mathcal{H}$ such that $S(0)=1$ and $S(t)$ has domain $D_t$. Assume that $\big(S(t)\big)_{t\in[0,T]}$ satisfies the following properties:
    \begin{enumerate}
        \par\hangindent 40\p@ (Non-increasing domains with dense union) For $s\leqslant t$, $D_t\subset D_s$ and $\bigcup_{0\leqslant t\leqslant T}D_t$ is dense in $\mathcal{H}$.
        \par\hangindent 40\p@ (Semigroup) For $0\leqslant s\leqslant t\leqslant T$, $S(s) D_t\subset D_{t-s}$ and $S(t-s)S(s)=S(t)$ on $D_t$.
        \par\hangindent 40\p@ (Symmetry) For $f,g\in D_t$, $\langle f,S(t) g\rangle_\mathcal{H}=\langle S(t) f,g\rangle_\mathcal{H}$.
        \par\hangindent 40\p@ (Weak continuity) For $0\leqslant t\leqslant T$ and $f\in D_t$, the function $s\mapsto\langle f,S(s)f\rangle_\mathcal{H}$ is continuous on the interval $[0,t]$.
    \end{enumerate}
    Then, there exists a unique self-adjoint operator $A$ on $\mathcal{H}$ such that for every $t\in[0,T]$, $D_t\subset D({\mathrm{e}}^{-tA})$ and such that $S(t)$ is the restriction of ${\mathrm{e}}^{-tA}$ to $D_t$. Moreover, the operator $A$ is essentially self-adjoint on the core $\hat D\stackrel{\mbox{\tiny def}}{=}\bigcup_{0\leqslant t\leqslant T'}\bigcup_{0<s<t}S(s) D_t$, for any $T'\in(0,T]$.

\label{Prop:ExistenceRenormalizedSemigroupFiniteVolume}
    There exists a deterministic sequence $\varepsilon_k$ converging to $0$ and an event $\overline{\Omega}$ of probability one, on which the following holds. Let $E$ be $H^{s,p}$ or $\mathcal{B}^{s}_{p,q}$ ($p\in(1,\infty)$, $q\in[1,\infty]$ and $|s|<\beta$). For any $0<\varepsilon<1$, let $\big(S_\varepsilon(t)\big)_{t\geqslant 0}$ be the $\mathcal{C}_0$-semigroup solving (\@saveref{renormSPDE}) on $E$. Then, 
    \begin{enumerate}
        \par\hangindent 40\p@ there exists $M>0$ and $c\in{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}$ such that,
        \begin{equation}
            \forall t>0,\; \|S_\varepsilon(t)\|_{\mathcal{L}(E)}\leqslant M\mathrm{e}^{ct}\,,
        \end{equation}
        \par\hangindent 40\p@ $\big(S_{\varepsilon_k}(t)\big)_{t\geqslant 0}$ converges strongly to a $\mathcal{C}_0$-semigroup $\big(S(t)\big)_{t\geqslant 0}$ on E verifying the same bound,
        \par\hangindent 40\p@ for any $f\in E$ and $g\in E'$, it holds
        \begin{equation}\label{Eq:SymS}
            \forall t>0,\; \langle S(t)f,g\rangle_{E,E'}=\langle f,S(t)g\rangle_{E,E'}.
        \end{equation}
    \end{enumerate}

Let $E$ be $H^{s_l,p}$ with $p\in \{2,3,\dotsc \}\cup\{\frac{n}{n-1},\; n\in{{\mathchoice{\hbox{\bfN}}{\hbox{\bfN}} 
        {\hbox{\scriptsize\bfN}}{\hbox{\tiny\bfN}}}},\; n\geqslant 3\}$ and $s_l=\frac{l\beta}{|l|+1}$. Note that there exists $0<\sigma_l<\beta$ and $0<\gamma_l<\beta-\sigma_l$ such that $-\sigma_l<s_l<\gamma_l$ thus $\mathcal{B}^{\gamma_l}_{p,\infty}\subset E \subset \mathcal{B}^{-\sigma_l}_{p,\infty}$ densely and compactly. Fix $\kappa$ small enough such that $0<4\kappa<\beta-\gamma_l-\sigma_l$. Let $\Omega_{l,p}$ be the event on which 1. and 2. hold on $E$. We will prove it is of full probability. Then, by taking 
    $$\overline{\Omega} = \bigcap_{p=2}^\infty\bigcap_{l\in{{\mathchoice{\hbox{\bfZ}}{\hbox{\bfZ}} 
        {\hbox{\scriptsize\bfZ}}{\hbox{\tiny\bfZ}}}}}\Omega_{l,p}\cap\Omega_{l,\frac{p}{p-1}}\,,$$
    which is of probability $1$, 1. and 2. for general Sobolev and Besov spaces will follow by interpolation because $H^{s_\theta,p}=[H^{s_0,p},H^{s_1,p}]_\theta$, $H^{s,p_\theta}=[H^{s,p_0},H^{s,p_1}]_\theta$ and $\mathcal{B}^{s_\theta}_{p,q}=(H^{s_0,p},H^{s_1,p})_{\theta,q}$,  with $s_\theta=\theta s_1+(1-\theta)s_0$ ($s_0\neq s_1$), $\frac{1}{p_\theta}=\frac{\theta}{p_1}+\frac{1-\theta}{p_0}$ ($p_0\neq p_1$), $[\cdot,\cdot]_\theta$ the complex interpolation functor and $(\cdot,\cdot)_{\theta,q}$ the real interpolation functor. By Lemma \ref{Cor:GlobalisationSeps}, there exists $M>0$ and $c\in{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}$, such that
    \begin{equation}\label{Eq:ExponentialBoundSeps}
        \forall t\geqslant 0,\; \|S_\varepsilon(t)f\|_{E}\leqslant M\mathrm{e}^{ct}\|f\|_E.
    \end{equation}
    Let $(f_j)_{j\in{{\mathchoice{\hbox{\bfN}}{\hbox{\bfN}} 
        {\hbox{\scriptsize\bfN}}{\hbox{\tiny\bfN}}}}_{\geqslant1}}$ be an enumeration of all trigonometric polynomials with rational coefficients. By continuity on the force $F_{\varepsilon}$ of Lemma \ref{lemmafixedpointplanted} and the convergence of $F_{\varepsilon}$ of Proposition \ref{prop:stoestimate}, for any $j$, $\big(S_\varepsilon(t)f_j\big)_{0<t\leqslant T}$ converges in probability with respect to the Schauder norm
    $$\sup_{0<t\leqslant T}\left[t^{\frac{\sigma_l+\gamma_l}{\alpha}}\|u(t)\|_{\mathcal{B}^{\gamma_l}_{p,\infty}}+\|u(t)\|_{\mathcal{B}^{-\sigma_l}_{p,\infty}}\right]\egroup\egroup\egroup\egroup.$$
    By a bootstrap argument, using $S_\varepsilon$ is a semigroup, it follows for any $N\in{{\mathchoice{\hbox{\bfN}}{\hbox{\bfN}} 
        {\hbox{\scriptsize\bfN}}{\hbox{\tiny\bfN}}}}_{\geqslant1}$, $\big(S_\varepsilon(t)f_j\big)_{\frac{T}{N}<t<NT}$ converges in probability in $L^\infty\bgroup\bgroup\bgroup\bgroup\left(\bgroup\bgroup\bgroup\bgroup\left(\frac{T}{N},NT\right)\egroup\egroup\egroup\egroup,\mathcal{B}^{\gamma_l}_{p,\infty}\right)\egroup\egroup\egroup\egroup$. By a diagonal argument on $\bgroup\bgroup\bgroup\bgroup\left(\big(S_{\varepsilon}(t)f_j\big)_{\frac{T}{N}<t<NT}\right)\egroup\egroup\egroup\egroup_{N,p,j\in{{\mathchoice{\hbox{\bfN}}{\hbox{\bfN}} 
        {\hbox{\scriptsize\bfN}}{\hbox{\tiny\bfN}}}}_{\geqslant1},l\in{{\mathchoice{\hbox{\bfZ}}{\hbox{\bfZ}} 
        {\hbox{\scriptsize\bfZ}}{\hbox{\tiny\bfZ}}}}}$, there exists a deterministic sequence $\varepsilon_k$ going to $0$, independent of $N$, $j$, $p$ and $l$, such that for any $N\in{{\mathchoice{\hbox{\bfN}}{\hbox{\bfN}} 
        {\hbox{\scriptsize\bfN}}{\hbox{\tiny\bfN}}}}_{\geqslant1}$ and any $j\in{{\mathchoice{\hbox{\bfN}}{\hbox{\bfN}} 
        {\hbox{\scriptsize\bfN}}{\hbox{\tiny\bfN}}}}$, $\big(S_{\varepsilon_k}(t)f_j\big)_{\frac{T}{N}<t<NT}$ converges almost surely in $L^\infty\bgroup\bgroup\bgroup\bgroup\left(\bgroup\bgroup\bgroup\bgroup\left(\frac{T}{N},NT\right)\egroup\egroup\egroup\egroup,\mathcal{B}^{\gamma_l}_{p,\infty}\right)\egroup\egroup\egroup\egroup$ to some $\big(S(t)f_j\big)_{\frac{T}{N}<t<NT}$. Remark the limit $S(t)$ is well-defined for any $t>0$ as $S_\varepsilon$ is a semigroup and by uniqueness of the limit in probability. Denote by $\Omega'_{l,p}$ the event of probability one on which this convergence holds for all $f_j$. Then, by density of $(f_j)_{j\in{{\mathchoice{\hbox{\bfN}}{\hbox{\bfN}} 
        {\hbox{\scriptsize\bfN}}{\hbox{\tiny\bfN}}}}_{\geqslant1}}$ and (\ref{Eq:ExponentialBoundSeps}), it follows that for any $f\in E$ and any $t\in E$, $S_{\varepsilon_k}(t)f$ converges to $S(t)f$ on $\Omega'_{l,p}$ and (\ref{Eq:ExponentialBoundSeps}) holds for $S$ with the same $M$ and $c$. It follows easily, by uniqueness of the limit, that $S$ is a semigroup on $E$. Moreover, by Lemma \ref{lemmafixedpointplanted} and the convergence in $\mathcal{B}^{\gamma_l}_{p,\infty}$, we get
    \begin{align*}
        \|S(t)f-f\|_E &\leqslant \|S(t)f-G(t)f\|_E+\|G(t)f-f\|_E\\
        &\leqslant C\|S(t)f-G(t)f\|_{\mathcal{B}^{\gamma_l}_{p,\infty}}+\|G(t)f-f\|_E\\
        &\leqslant C\lim_{k\to\infty}\|S_{\varepsilon_k}(t)f-G(t)f\|_{\mathcal{B}^{\gamma_l}_{p,\infty}}+\|G(t)f-f\|_E\\
        &\leqslant Ct^\eta\|f\|_{\mathcal{B}^{-\sigma_l}_{p,\infty}}+\|G(t)f-f\|_E\\
        &\leqslant C't^\eta\|f\|_{E}+\|G(t)f-f\|_E\,,
    \end{align*}
    for some $\eta>0$, using $\mathcal{B}^{\gamma_l}_{p,\infty}\subset E \subset \mathcal{B}^{-\sigma_l}_{p,\infty}$. Taking $t$ to $0^+$ shows $S$ is in fact a $\mathcal{C}_0$-semigroup on $E$, on the event $\Omega'_{l,p}$. This achieve the proof that $\Omega'_{l,p}\subset\Omega_{l,p}$, which is thus of full probability. Now, on $\overline{\Omega}$, let $E$ be any Sobolev or Besov space of regularity $|s|<\beta$ and integrability $p\in(1,\infty)$ for any $f\in E$ and $g \in E'$, it holds
    $$\forall t,\varepsilon>0,\; \langle S_\varepsilon(t)f,g\rangle_{E,E'}=\langle f,S_\varepsilon(t)g\rangle_{E,E'}.$$
    In fact, it holds for $f$ and $g$ trigonometric polynomials, which are dense in both $E$ and $E'$, by self adjointness and both bracket are continuous bilinear forms on $E\times E'$. Thus, taking the limit along $\varepsilon_k$, 3. follows.

The main observation to prove item 1.(c) is that one has to see that the first and third items of Theorem~\ref{maintheoremspde} hold for the more general equation
    \begin{equation}\label{mainSPDErotated}
        (\partial_t+{\mathrm{e}}^{\mathrm{i}\varphi}\mathrm{D}^{\alpha,m})u^{\alpha,m}={\mathrm{e}}^{\mathrm{i}\varphi}(\xi-\infty) u^{\alpha,m}\,,\qquad u^{\alpha,m}\!\!\upharpoonright_{t=0}\,=u^{\alpha,m}_0\,
    \end{equation}
    for $|\varphi|<\frac{\pi}{2}$, viewed as the limit of 
    \begin{equation}\label{Eq:RenomalizedParabolicRegularizedRotated}
        (\partial_t+{\mathrm{e}}^{\mathrm{i}\varphi}\mathrm D^{\alpha,m})u^{\alpha,m}_\varepsilon={\mathrm{e}}^{\mathrm{i}\varphi}(\xi_\varepsilon-\mathfrak{C}^{\alpha,m}_\varepsilon) u^{\alpha,m}_\varepsilon\,,\qquad u^{\alpha,m}_\varepsilon\!\!\upharpoonright_{t=0}\,=u^{\alpha,m}_{0,\varepsilon}\,.
    \end{equation}
    This is a direct consequence of the semigroup associated with $\mathrm{D}^{\alpha,m}$ being bounded analytic on $\{{\mathchoice{\hbox{\rmRe}}{\hbox{\rmRe}} 
        {\hbox{\scriptsize\rmRe}}{\hbox{\tiny\rmRe}}} z>0\}$ on every ${L}^p_x$. In that case, (\@saveref{Eq:EstimateS-G}) and (\@saveref{Eq:EstimateS-GOH}) may hold with constants depending on $\varphi$ (which typically blow up as $|\varphi|$ goes to $\frac{\pi}{2}$). The only fact to prove is that the renormalisation of (\@saveref{mainSPDErotated}) has the form given in (\@saveref{Eq:RenomalizedParabolicRegularizedRotated}). For that purpose, one can show by induction that 
    \begin{equs}
        \upxi_{\varepsilon,\mu}^{\varphi,n}(t,x;s,y)= e^{2\mathrm{i} \varphi}\upxi^n_{\varepsilon,\mu} ({\mathrm{e}}^{\mathrm{i} \varphi}t,x;{\mathrm{e}}^{\mathrm{i} \varphi}s,y)\,.
    \end{equs}
    We have denoted for this proof $\upxi_{\varepsilon,\mu}^{\varphi,n}$ the force coefficients associated with the operator $\partial_t+{\mathrm{e}}^{\mathrm{i}\varphi}\mathrm D^{\alpha,m}$. The latter implies that $\mathfrak{C}^\varphi_\varepsilon=e^{\mathrm{i} \varphi}\mathfrak{C}_\varepsilon$. Hence, Proposition~\ref{Prop:ExistenceRenormalizedSemigroupFiniteVolume} holds for the semigroups $S^{\varphi}$ and $(S^\varphi_\varepsilon)_{0<\varepsilon<1}$ on a event $\overline{\Omega}_\varphi$ of probability one. We now work on the full-probability event
    $$\overline{\overline{\Omega}} = \bigcap_{k=0}^{\infty}\overline{\Omega}_{\frac{k\pi}{2k+1}}\cap\overline{\Omega}_{-\frac{k\pi}{2k+1}}.$$

    \begin{itemize}
        \par\hangindent 40\p@[(a)] As a consequence of Theorem \ref{Prop:Hille-Yosida} and Proposition \ref{Prop:ExistenceRenormalizedSemigroupFiniteVolume}, one can now construct the operator $\mathrm{A}^{\!\alpha,m}_\xi$                                                                                                                                                                                                                                         
        as the generator of the semigroup $S$ constructed in Proposition \ref{Prop:ExistenceRenormalizedSemigroupFiniteVolume} on $L_x^p({{\mathchoice{\hbox{\bfT}}{\hbox{\bfT}} 
        {\hbox{\scriptsize\bfT}}{\hbox{\tiny\bfT}}}}^d)$. Then, obviously, (\@saveref{mainSPDE}) can be rewritten as
        $$\partial_t u + \mathrm{A}^{\!\alpha,m}_\xi u = 0.$$
        The quasi-sectoriality of $A$ follows directly from Theorem \ref{Prop:Hille-Yosida}. Let $A_\varepsilon = \mathrm{D}^{\alpha,m}+\xi_{\varepsilon}-\mathfrak{C}_{\varepsilon}$. There exists $c,C>0$ finite a.s. such that
        $$\forall \varepsilon,t>0,\; \|S_\varepsilon(t)\|_{\mathcal{L}(L_x^p)}\leqslant C{\mathrm{e}}^{ct},$$ thus by Lumer calculus, for ${\mathchoice{\hbox{\rmRe}}{\hbox{\rmRe}} 
        {\hbox{\scriptsize\rmRe}}{\hbox{\tiny\rmRe}}} z<-c$, it holds
        \begin{equation}\label{Eq:LumerFormulaResolventA-Aeps}
            (A+z)^{-1}-(A_\varepsilon+z)^{-1} = \int_0^\infty {\mathrm{e}}^{-zt}\big(S(t)-S_{\varepsilon}(t)\big)\,\mathrm{d} t,
        \end{equation}
        thus we see that $(A_{\varepsilon_k}+z)^{-1}$ converges to $(A+z)^{-1}$ in $\mathcal{L}(L_x^p)$ by dominated convergence in the Bochner integral in the right-hand side of (\@saveref{Eq:LumerFormulaResolventA-Aeps}).                                                                         

        Likewise, for $0<\gamma<\beta$, one can write
        \begin{equation}\label{Eq:LumerFormulaResolventA-D}
            (A+z)^{-\frac{\gamma}{\alpha}}-(\mathrm{D}^{\alpha,m}+z)^{-\frac{\gamma}{\alpha}} = \int_0^\infty t^{\frac{\gamma}{\alpha}} {\mathrm{e}}^{-zt}\big(S(t)-G^{\alpha,m}(t)\big)\,\frac{\mathrm{d} t}{t}.
        \end{equation}
        Let $\sigma>0$ small enough and $\gamma<\gamma'<\beta-\sigma$. Then, for $f\in L_x^p$, (\@saveref{Eq:EstimateS-G}) implies
        \begin{align*}
            \bgroup\bgroup\bgroup\bgroup\left\|(A+z)^{-\frac{\gamma}{\alpha}}f-(\mathrm{D}^{\alpha,m}+z)^{-\frac{\gamma}{\alpha}}f\right\|\egroup\egroup\egroup\egroup_{H^{\gamma,p}} &\leqslant \int_0^\infty t^{\frac{\gamma}{\alpha}} {\mathrm{e}}^{-{\mathchoice{\hbox{\rmRe}}{\hbox{\rmRe}} 
        {\hbox{\scriptsize\rmRe}}{\hbox{\tiny\rmRe}}} zt}\|S(t)f-G^{\alpha,m}(t)f\|_{H^{\gamma,p}}\,\frac{\mathrm{d} t}{t}\\
            &\lesssim \int_0^\infty t^{\frac{\beta+\gamma-\gamma'-\sigma}{\alpha}}{\mathrm{e}}^{(c-{\mathchoice{\hbox{\rmRe}}{\hbox{\rmRe}} 
        {\hbox{\scriptsize\rmRe}}{\hbox{\tiny\rmRe}}} z)t}\|f\|_{\mathcal{B}^{-\frac{\sigma}{2}}_{p,\infty}}\,\frac{\mathrm{d} t}{t}\\
            &\lesssim \bgroup\bgroup\bgroup\bgroup\left(\int_0^\infty t^{\frac{\beta+\gamma-\gamma'-\sigma}{\alpha}}{\mathrm{e}}^{(c-{\mathchoice{\hbox{\rmRe}}{\hbox{\rmRe}} 
        {\hbox{\scriptsize\rmRe}}{\hbox{\tiny\rmRe}}} z)t}\,\frac{\mathrm{d} t}{t}\right)\egroup\egroup\egroup\egroup\|f\|_{L_x^p},
        \end{align*}
        and the integral is finite as $\beta+\gamma-\gamma'-\sigma>0$ and $c-{\mathchoice{\hbox{\rmRe}}{\hbox{\rmRe}} 
        {\hbox{\scriptsize\rmRe}}{\hbox{\tiny\rmRe}}} z<0$. Thus, as $(\mathrm{D}^{\alpha,m}+z)^{-\frac{\gamma}{\alpha}}\in\mathcal{L}(L_x^p,H^{\gamma,p})$, it follows $(A+z)^{-\frac{\gamma}{\alpha}}\in\mathcal{L}(L_x^p,H^{\gamma,p})$. This give a kind of elliptic regularity estimate for $A$.
        \par\hangindent 40\p@[(b)] Consider $p=2$. Let $f,g\in\mathrm{D}(A)$, then it holds
        \begin{align*}
            \langle Af,g\rangle_{L_x^2} &= \lim_{t\to 0} \bgroup\bgroup\bgroup\bgroup\left\langle \frac{S(t)f-f}{t},g\right\rangle\egroup\egroup\egroup\egroup_{L_x^2}\\
            &= \lim_{t\to 0} \bgroup\bgroup\bgroup\bgroup\left\langle f, \frac{S(t)g-g}{t}\right\rangle\egroup\egroup\egroup\egroup_{L_x^2}\\
            &= \langle f,Ag\rangle_{L_x^2},
        \end{align*}
        where in second line we used (\@saveref{Eq:SymS}). Thus, $A$ is symmetric and, by the previous point, $-c-1$ is in the resolvent set of $A$, implying the self-adjointness of $A$. Moreover, $(A+c+1)^{-1}$ is compact on $L_x^2$ by the previous point and the compact embedding of $H^{\gamma,2}$ in $L_x^2$. Thus, by \cite[Theorem 3.6.29.]{Ka95}, there exists a complete orthonormal basis $(\varphi_n)_{n\in{{\mathchoice{\hbox{\bfN}}{\hbox{\bfN}} 
        {\hbox{\scriptsize\bfN}}{\hbox{\tiny\bfN}}}}}$ and a non-decreasing sequence
        $$\lambda_0 \leqslant \lambda_1 \leqslant \cdots \leqslant \lambda_n \to\infty$$
        such that $A\varphi_n=\lambda_n\varphi_n$. By the previous point and Sobolev embedding, it is easily verified that $\varphi_n\in H^{\beta-,p}$ for any $p\in(1,\infty)$. As a consequence, $\lambda_n$ are eigenvalues of $A$ on  $L_x^p$. Using Sobolev embeddings and the "elliptic regularity" estimate, it is easily seen that $A+\lambda$ is injective (respectively surjective) on some $L_x^p$ if and only if it is on all $L_x^p$-spaces. 

        It only remains to prove Weyl law (\@saveref{Eq:WeylLawAndersonTheorem}) for $A$. By Lemma \ref{Cor:WeylLawEquivTrace}, it suffices to prove a small time asymptotic of $\operatorname{Tr}\big(S(t)\big)$. A direct computation gives
        $$0\leqslant \operatorname{Tr}\bgroup\bgroup\bgroup\bgroup\left({\mathrm{e}}^{-t|\nabla|^\alpha}-G^{\alpha,m}(t)\right)\egroup\egroup\egroup\egroup\lesssim t \operatorname{Tr}\bgroup\bgroup\bgroup\bgroup\left({\mathrm{e}}^{-\frac{t}{2}|\nabla|^\alpha}\right)\egroup\egroup\egroup\egroup\,,$$
        thus Lemma \ref{Lem:LooseAsymptoticFractionalHeatTrace} implies
        \begin{equation}\label{Eq:SmallTimeAsymptoticTraceMassiveFractionalHeatKernel}
            \operatorname{Tr}\big(G^{\alpha,m}(t)\big)\sim \operatorname{Tr}\bgroup\bgroup\bgroup\bgroup\left({\mathrm{e}}^{-t|\nabla|^\alpha}\right)\egroup\egroup\egroup\egroup\,.
        \end{equation}
        Now, as in \cite{BDM22}, using the semigroup property and the self adjointness, one can see
        $$\operatorname{Tr}\big(S(t)\big) = \int_{{{\mathchoice{\hbox{\bfT}}{\hbox{\bfT}} 
        {\hbox{\scriptsize\bfT}}{\hbox{\tiny\bfT}}}}^d} S(t,x,x) \,\mathrm{d} x\,,$$
        where $S(t,x,y)\stackrel{\mbox{\tiny def}}{=} S(t)\big(\delta_y\big)(x)$. Let $0<\varepsilon<\frac{\beta}{2}$, there exists $1<p<2$ such that $\delta_y \in \mathcal{B}^{-\varepsilon}_{p,\infty}$. Using (\@saveref{Eq:EstimateS-G}), it follows
        $$\sup_{y\in{{\mathchoice{\hbox{\bfT}}{\hbox{\bfT}} 
        {\hbox{\scriptsize\bfT}}{\hbox{\tiny\bfT}}}}^d}\|S(t)\delta_y-G^{\alpha,m}(t)\delta_y\|_{L^1_x} \lesssim \sup_{y\in{{\mathchoice{\hbox{\bfT}}{\hbox{\bfT}} 
        {\hbox{\scriptsize\bfT}}{\hbox{\tiny\bfT}}}}^d}\|S(t)\delta_y-G^{\alpha,m}(t)\delta_y\|_{\mathcal{B}^{\varepsilon}_{p,\infty}} \lesssim t^{\frac{\beta-d-2\varepsilon}{\alpha}}\,.$$
        Thus, using Sobolev embeddings,
        \begin{align*}
            \operatorname{Tr}\big(S(t)\big) &= \int_{{{\mathchoice{\hbox{\bfT}}{\hbox{\bfT}} 
        {\hbox{\scriptsize\bfT}}{\hbox{\tiny\bfT}}}}^d} S(t,x,x)\,\mathrm{d} x\\
            &= \int_{{{\mathchoice{\hbox{\bfT}}{\hbox{\bfT}} 
        {\hbox{\scriptsize\bfT}}{\hbox{\tiny\bfT}}}}^d} G^{\alpha,m}(t,x,x)\,\mathrm{d} x + \int_{{{\mathchoice{\hbox{\bfT}}{\hbox{\bfT}} 
        {\hbox{\scriptsize\bfT}}{\hbox{\tiny\bfT}}}}^d} S(t,x,x)-G^{\alpha,m}(t,x,x) \,\mathrm{d} x\\
            &= \operatorname{Tr}\big(G^{\alpha,m}(t)\big) + o\bgroup\bgroup\bgroup\bgroup\left(t^{-\frac{d}{\alpha}}\right)\egroup\egroup\egroup\egroup\\
            &\sim \operatorname{Tr}\bgroup\bgroup\bgroup\bgroup\left({\mathrm{e}}^{-t|\nabla|^\alpha}\right)\egroup\egroup\egroup\egroup\,,
        \end{align*}
        using (\@saveref{Eq:SmallTimeAsymptoticTraceMassiveFractionalHeatKernel}) and Lemma \ref{Lem:LooseAsymptoticFractionalHeatTrace}. Then, (\@saveref{Eq:WeylLawAndersonTheorem}) follows from Lemma \ref{Cor:WeylLawEquivTrace}.

        \par\hangindent 40\p@[(c)] Let $\lambda>-\lambda_0$. On $L^2_x$, self-adjointness and positiveness imply $\lambda+A$ generates a bounded analytic semigroup on $\{{\mathchoice{\hbox{\rmRe}}{\hbox{\rmRe}} 
        {\hbox{\scriptsize\rmRe}}{\hbox{\tiny\rmRe}}} z>0\}$. By the Hille-Yoshida theorem, for any $\varphi\in\Phi=\{\pm\frac{k\pi}{2k+1},\;k\in{{\mathchoice{\hbox{\bfN}}{\hbox{\bfN}} 
        {\hbox{\scriptsize\bfN}}{\hbox{\tiny\bfN}}}}\}$, $S^\varphi$, the semigroup defined by the solution to (\@saveref{mainSPDErotated}), admits a quasi sectorial generator on any $L^p_x$, which is equal to ${\mathrm{e}}^{i \varphi}A$ on $D_{p,2}=(\lambda+A)^{-1}(L^p_x\cap L^2_x)$, which is dense in both $D_p=(\lambda+A)^{-1}L^p_x$ and $D_2=(\lambda+A)^{-1}L^2_x$. Let 
        $$\omega(p,\varphi) = \omega_{L_x^p}(S^\varphi) = \lim_{t\to\infty}\frac{1}{t}\log\bgroup\bgroup\bgroup\bgroup\left\|S^\varphi(t)\right\|\egroup\egroup\egroup\egroup_{\mathcal{L}(L_x^p)}$$
        the growth bound of $S^\varphi$ on $L^p_x$. By the Riesz-Thorin theorem, $\omega(p,\varphi)$ is a convex function of $\frac{1}{p}$. Let $1<q<p$ and $0<\varepsilon<1$, it holds
        \begin{align*}
            \bgroup\bgroup\bgroup\bgroup\left\|S^\varphi(t)u\right\|\egroup\egroup\egroup\egroup_{L^q_x} &\leqslant \bgroup\bgroup\bgroup\bgroup\left\|S^\varphi(t)u\right\|\egroup\egroup\egroup\egroup_{L^p_x}\\
            &\lesssim \bgroup\bgroup\bgroup\bgroup\left\|S^\varphi((1-\varepsilon)t)\right\|\egroup\egroup\egroup\egroup_{\mathcal{L}(L_x^p)}\bgroup\bgroup\bgroup\bgroup\left\|S^\varphi(\varepsilon t)u\right\|\egroup\egroup\egroup\egroup_{\mathcal{B}^{d(\frac{1}{q}-\frac{1}{p})}_{q,\infty}}\\
            &\lesssim_\varphi t^{\frac{\beta-2d(\frac{1}{q}-\frac{1}{p})}{\alpha}}\bgroup\bgroup\bgroup\bgroup\left\|S^\varphi((1-\varepsilon)t)\right\|\egroup\egroup\egroup\egroup_{\mathcal{L}(L_x^p)}\|u\|_{L^q_x}
        \end{align*}
        for $|\frac{1}{q}-\frac{1}{p}|$ small enough. Thus, $\omega(q,\varphi) \leqslant \frac{1}{1-\varepsilon}\omega(p,\varphi)$. Sending $\varepsilon$ to $0$, we see $p\mapsto \omega(p,\varphi)$ is non-decreasing. Similarly, 
        \begin{align*}
            \bgroup\bgroup\bgroup\bgroup\left\|S^\varphi(t)u\right\|\egroup\egroup\egroup\egroup_{L^p_x} &\lesssim \bgroup\bgroup\bgroup\bgroup\left\|S^\varphi(t)u\right\|\egroup\egroup\egroup\egroup_{\mathcal{B}^{d(\frac{1}{q}-\frac{1}{p})}_{q,\infty}}\\
            &\lesssim_\varphi t^{\frac{\beta-2d(\frac{1}{q}-\frac{1}{p})}{\alpha}}\bgroup\bgroup\bgroup\bgroup\left\|S^\varphi((1-\varepsilon)t)\right\|\egroup\egroup\egroup\egroup_{\mathcal{L}(L_x^q)}\|u\|_{L^p_x}\,,
        \end{align*}
        implying $p\mapsto \omega(p,\varphi)$ is also non-increasing, thus constant. Hence $\omega(p,\varphi) = \omega(2,\varphi) = -\cos(\varphi)\lambda_0$. In particular, ${\mathrm{e}}^{i\varphi}(\lambda+A)$ generates a bounded $\mathcal{C}_0$-semigroup on any $L^p_x$. Hence, it is $\theta$-sectorial for any $\theta\in(\frac{\pi}{2},\pi)$, which implies that $\lambda+A$ is $\theta$-sectorial for any $\theta>0$ on any $L^p_x$.\\

        Now let $\theta \in(0,\pi)$ and $F$ be a bounded holomorphic function on $\Sigma_\theta$. We want to prove that there exists a constant $C$ depending only $\theta,p,\mathrm{D}^{\alpha,m}$, such that
        $$\bgroup\bgroup\bgroup\bgroup\left\|\int_\Gamma F(z) (z-\lambda-A)^{-1}\,\mathrm{d} z\right\|\egroup\egroup\egroup\egroup_{\mathcal{L}(L_x^p)}\leqslant C\|F\|_{L^\infty(\Sigma_\theta)}.$$
        This result is true for $\mathrm{D}^{\alpha,m}$ by the Mikhlin-Hormänder theorem. Thus, we can focus on
        $$\bgroup\bgroup\bgroup\bgroup\left\|\int_\Gamma F(z) \bgroup\bgroup\bgroup\bgroup\left((z-\lambda-A)^{-1}-(z+\lambda-\mathrm{D}^{\alpha,m})^{-1}\right)\egroup\egroup\egroup\egroup\,\mathrm{d} z\right\|\egroup\egroup\egroup\egroup_{\mathcal{L}(L_x^p)}\leqslant C\|F\|_{L^\infty(\Sigma_\theta)}.$$
        Let $\Gamma = \Gamma_+\cup \Gamma_0\cup \Gamma_-$, with $\Gamma_+ =  e^{i \theta/2}(\infty,\delta)$, $\Gamma_- = e^{-i\theta/2}(\delta,\infty)$ and $\Gamma_0 = \delta {\mathrm{e}}^{i[\theta/2,-\theta/2]}$, where $\delta>0$ is small enough so that $\bgroup\bgroup\bgroup\bgroup\left((z-\lambda-A)^{-1}\right)\egroup\egroup\egroup\egroup_{|z|=\delta}$ is uniformly bounded by the open mapping theorem. For $z\in\Gamma_\pm$,
        $$(z-\lambda-A)^{-1}-(z-\lambda-\mathrm{D}^{\alpha,m})^{-1} = \int_0^{\infty} {\mathrm{e}}^{{\mathrm{e}}^{\pm i\varphi}t(z-\lambda)}\big(S^{\pm\varphi}(t)-G^{\alpha,m}({\mathrm{e}}^{\pm i\varphi}t)\big)\,\mathrm{d} t$$
        for $\varphi\in\Phi$ such that $\frac{\pi}{2}<\varphi+\frac{\theta}{2}<\pi$. Now, by (\@saveref{Eq:EstimateS-G}) and Remark~\ref{Rem:RemarksTheorem1}, there exists $\gamma>0$ such that for any $\varepsilon>0$ small enough,
        \begin{align*}
            \bgroup\bgroup\bgroup\bgroup\left\|(z+\lambda+A)^{-1}-(z+\lambda-\mathrm{D}^{\alpha,m})^{-1}\right\|\egroup\egroup\egroup\egroup_{\mathcal{L}(L_x^p)}&\lesssim_{\varphi,\varepsilon} \int_0^{1} t^\gamma {\mathrm{e}}^{t|z|\cos(\varphi+\frac{\theta}{2})}\,\mathrm{d} t\\
            &+ \int_1^{\infty}{\mathrm{e}}^{t\bgroup\bgroup\bgroup\bgroup\left(|z|\cos(\varphi+\frac{\theta}{2})-\cos(\varphi)\lambda\right)\egroup\egroup\egroup\egroup}\bgroup\bgroup\bgroup\bgroup\left(1+{\mathrm{e}}^{t\bgroup\bgroup\bgroup\bgroup\left(\cos(\varphi)\lambda_0+\varepsilon\right)\egroup\egroup\egroup\egroup}\right)\egroup\egroup\egroup\egroup\,\mathrm{d} t\\
            &\lesssim_{\varphi,\theta,\varepsilon} |z|^{-1-\gamma}\,,
        \end{align*}
        as $\lambda>-\lambda_0$ and $\cos(\varphi+\frac{\theta}{2})<0<\cos(\varphi)$, which allows to conclude as $|z|^{-1-\gamma}$ is integrable as $|z|$ goes to infinity.
    \end{itemize}

Let $T=1$, let $D_t \stackrel{\mbox{\tiny def}}{=} L^2_{\mcb e_{t}}$ (we recall that this space has been defined below (\@saveref{eq:defLp})) and let $S(t) f$ be the unique solution to (\@saveref{mainSPDE}) at time $0\leqslant t\leqslant 1$, starting from $f\in D_t$. For $\varepsilon>0$, let $S_{\varepsilon}(t) = e^{t(\mathrm{D}^{\alpha,m}_\xi-\xi_\varepsilon+\mathfrak{C}^{\alpha,m}_\varepsilon)}$. Then, acting like in the proof of Proposition \ref{Prop:ExistenceRenormalizedSemigroupFiniteVolume}, we can ensure the existence of an event $\Omega$ of probability one and a deterministic sequence $\varepsilon_k$ going to $0$ such that for any $f\in V\stackrel{\mbox{\tiny def}}{=} \mathrm{Span}_{{{\mathchoice{\hbox{\bfQ}}{\hbox{\bfQ}} 
        {\hbox{\scriptsize\bfQ}}{\hbox{\tiny\bfQ}}}}}\bgroup\bgroup\bgroup\bgroup\left(\mathbf{1}_{B(a,r)},\; a\in{{\mathchoice{\hbox{\bfQ}}{\hbox{\bfQ}} 
        {\hbox{\scriptsize\bfQ}}{\hbox{\tiny\bfQ}}}}^d,\; r\in{{\mathchoice{\hbox{\bfQ}}{\hbox{\bfQ}} 
        {\hbox{\scriptsize\bfQ}}{\hbox{\tiny\bfQ}}}}_+\right)\egroup\egroup\egroup\egroup$, $\big(S_{\varepsilon_k}(t)f\big)_{0<t\leqslant 1}$ converges to $\big(S(t)f\big)_{0<t\leqslant 1}$ in $\mathcal{E}_{2,2,l,1}^{\gamma,\gamma-\eta}$, for any $\gamma<\beta$ and $\eta>0$, on $\Omega$. We now work on $\Omega$. Let us verify each item of Theorem \ref{Prop:KleinLandau}.
    \begin{enumerate}
        \par\hangindent 40\p@ Clearly, for $s\leqslant t$, $D_s\subset D_t$ and $\mathcal{C}^\infty_c({{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d)\subset \bigcup_{0\leqslant t\leqslant T}D_t$, which is thus dense in $L^2_x$.
        \par\hangindent 40\p@ Thanks to Theorem \ref{maintheoremspde}, and in particular (\@saveref{eq:estimateS-Ginf}), we are allowed to start the dynamic from $L^2_{\mcb e_{\ell}}$ for any $\ell\in{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}$, for $0\leqslant s\leqslant t\leqslant T$, $S(s)D_{t-s}\subset D_s$ and $S(t-s)S(s)=S(t)$ on $D_t$.
        \par\hangindent 40\p@ Let $f,g\in V$.  Then, $S_{\varepsilon_k}(t)f$ and $S_{\varepsilon_k}(t)g$ converges in $L^2_x$ to $S(t)f$ and $S(t)g$ respectively. Thus, $\langle f,S_{\varepsilon_k}(t) g\rangle_{L^2_x}=\langle S_{\varepsilon_k}(t) f,g\rangle_{L^2_x}$ converges to $\langle f,S(t) g\rangle_{L^2_x}=\langle S(t) f,g\rangle_{L^2_x}$. Now, remark that both $\langle f,S(t) g\rangle_{L^2_x}$ and $\langle S(t) f,g\rangle_{L^2_x}$ are bilinear continuous on $D_t$ and $V$ is dense, so $\langle f,S(t) g\rangle_{L^2_x}=\langle S(t) f,g\rangle_{L^2_x}$ holds for any $f,g\in D_t$.
        \par\hangindent 40\p@ Let $g\in L^2_x$ and $f\in V$. For $0\leqslant s\leqslant t$, for $\eta>0$ small enough, (\@saveref{eq:estimateS-Ginf}) implies
        \begin{align*}
            \bgroup\bgroup\bgroup\bgroup\left|\langle g,\big(S(s)-{\mathrm{e}}^{-s\mathrm{D}^{\alpha,m}}\big) f\rangle_{L^2_x}\right|\egroup\egroup\egroup\egroup 
            &\leqslant \|g\|_{L^2_x}\|\big(S(s)-G^{\alpha,m}(s)\big)f\|_{L^2_x}\\
            &\lesssim (s\wedge 1)^{(\beta-2\sigma-\eta)/\alpha}\|\mcb e_{t} f\|_{L^2_x}\|g\|_{L^2_x}\,.
        \end{align*}
        By density of $V$, this holds for any $f\in D_t$. As $\big(G^{\alpha,m}(s)\big)_{s\geqslant0}$ is a $\mathcal{C}_0$-semigroup, $S(s) f$ converges weakly to $f$ in $L^2_x({{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d)$ as $s$ goes to $0$. Moreover, as $\|S(s) f\|_{L^2_x}^2=\langle f,S(2s)f\rangle_{L^2_x}$ converges to $\langle f,f\rangle_{L^2_x}=\|f\|_{L^2_x}^2$, $S(s) f$ converges strongly to $f$ in $L^2_x$. Now, for $0< s\leqslant s'\leqslant t$ using $S(s')f=S(s'-s)S(s) f$, we get 
        \begin{align*}
            \langle f,\big(S(s')-S(s)\big)f\rangle_{L^2_x} &= \langle S(s)f,\big(S(s'-s)-1\big)f\rangle_{L^2_x}\\
            &\leqslant \|S(s) f\|_{L^2_x}\|S(s'-s)f-f\|_{L^2_x}\\
            &\lesssim \|\mcb e_{t} f\|_{L^2_x}\|S(s'-s)f-f\|_{L^2_x}\,,
        \end{align*}
        and the continuity follows.
    \end{enumerate}
    Thus, by Theorem \ref{Prop:KleinLandau}, $\big(S(t)\big)_{t>0}$ is the restriction of a unique self-adjoint operator $\mathrm{A}^{\!\alpha,m}$ on $L^2_x$.

\label{Prop:ExistenceRenormalizedSemigroupHO}
    There exists a deterministic sequence $\varepsilon_k$ converging to $0$ and an event $\overline{\Omega}$ of probability one, on which the following holds. Let $E$ be $\mathscr{H}^{s,p}$ or $\mathscr{B}^{s}_{p,q}$ ($p\in(1,\infty)$, $q\in(1,\infty)$ and $|s|<\beta$). For any $0<\varepsilon<1$, let $\big(S_\varepsilon(t)\big)_{t\geqslant 0}$ be the $\mathcal{C}_0$-semigroup solving (\@saveref{renormSPDE}) on $E$. Then, 
    \begin{enumerate}
        \par\hangindent 40\p@ there exists $M>0$ and $c\in{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}$ such that,
        \begin{equation}
            \forall t>0,\; \|S_\varepsilon(t)\|_{\mathcal{L}(E)}\leqslant M\mathrm{e}^{ct}\,,
        \end{equation}
        \par\hangindent 40\p@ $\big(S_{\varepsilon_k}(t)\big)_{t\geqslant 0}$ converges strongly to a $\mathcal{C}_0$-semigroup $\big(S(t)\big)_{t\geqslant 0}$ on E verifying the same bound,
        \par\hangindent 40\p@ for any $f\in E$ and $g\in E'$, it holds
        \begin{equation}\label{Eq:SymSOH}
            \forall t>0,\; \langle S(t)f,g\rangle_{E,E'}=\langle f,S(t)g\rangle_{E,E'}.
        \end{equation}
    \end{enumerate}

\label{estimatesKmu}
Let $\varsigma>0$ and $p,q\in[1,\infty]$. We have
\begin{equs} \label{eq:normKmu}\big\|\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^\varsigma K_\mu\big\|_{L^1_{t,x}}&\leqslant1   \,,\\
\big\|\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^\varsigma\partial_t^{\mathfrak{l}_0}\partial_x^{\mathfrak{l}}K_\mu\big\|_{L^1_{t,x}}&\lesssim\mu^{-|\mathfrak{l}_0,\mathfrak{l}|_\mathfrak{s}}\;\mathrm{for}\;\mathrm{all} \;(\mathfrak{l}_0,\mathfrak{l})\in{{\mathchoice{\hbox{\bfN}}{\hbox{\bfN}} 
        {\hbox{\scriptsize\bfN}}{\hbox{\tiny\bfN}}}}^{d+1}\,,\;|\mathfrak{l}_0,\mathfrak{l}|_\mathfrak{s}\leqslant N\,,
\label{eq:spacederivKmu}
\\
\label{eq:KmuLp} \big\|\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^\varsigma K_\mu\|_{L_{t,x}^{p,q}}&\lesssim \mu^{-\alpha\bgroup\bgroup\bgroup\bgroup\left(1-\frac{1}{p}\right)\egroup\egroup\egroup\egroup-d\bgroup\bgroup\bgroup\bgroup\left(1-\frac{1}{q}\right)\egroup\egroup\egroup\egroup} \;\mathrm{if}\;\alpha\bgroup\bgroup\bgroup\bgroup\left(1-\frac{1}{p}\right)\egroup\egroup\egroup\egroup+d\bgroup\bgroup\bgroup\bgroup\left(1-\frac{1}{q}\right)\egroup\egroup\egroup\egroup\leqslant N\,,                                                                                          
\end{equs}
uniformly in $\mu\in(0,1]$. In addition, we have the estimate with exponential weights for any $\ell\in{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}$
\begin{equs}\label{Kmuexp}
    \big\|\mcb e_\ell Q_\mu\big\|_{L^1_x}\lesssim1\,.
\end{equs}
and for $\psi\in \mathcal{D}({{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d)$ and $\nu\leqslant\mu$,
\begin{equs}\label{eq:comKmuKnu1}
    \big\| K_\mu\big(1-K_\nu\big)\psi\big\|_{L_x^p}&\lesssim \big(\nu/\mu\big)^{2}\|K_\nu\psi\|_{L_x^p}\,,
\end{equs}
and
\begin{equs}\label{eq:comKmuKnu}
    \big\|Q_\mu\mcb e_{-\ell}\big(1-Q_\nu\big)\psi\big\|_{L_x^p}&\lesssim \big(\nu/\mu\big)^{2}\| \mcb e_{-\ell}K_\nu\psi\|_{L_x^p}\,,
\end{equs}
Moreover, for $\psi\in\mathcal{D}(\Lambda)$, we have
\begin{equs} \label{eq:Kmunu} 
    \|\mcb e_{-\ell}K_\mu\psi\|_{L_{t,x}^{p,q}}&\leqslant\bigg(1\vee\Big(2\big(\nu/\mu\big)^{\alpha}-1\Big)^{2N}\bigg)  \|\mcb e_{-\ell}K_\nu\psi\|_{L_{t,x}^{p,q}}\,,
\end{equs}
uniformly in $\mu,\nu\in(0,1]$.

Let us prove (\@saveref{eq:normKmu}) and (\@saveref{eq:spacederivKmu}) at once. We start by computing explicitly
    \begin{equs}
        K_{1,\mu}^{*N}(t,x)=\mu^{-N\alpha }\BF{1}_{(0,\infty)}(t)\frac{t^{N-1}}{(N-1)!}{\mathrm{e}}^{-t/\mu^\alpha}Q_\mu^{*N}(x)\,.
    \end{equs}
    We have the heat kernel representation
    \begin{equs}\label{heatkernelrep}
        \partial_x^{\mathfrak{l}}(1-\mu^2\Delta)^{-N}(x)=\frac{1}{(N-1)!}\int_0^\infty s^{N-1}{\mathrm{e}}^{-s}\partial_x^\mathfrak{l} h(\mu^2 s,x)\,\mathrm{d} s\,,
    \end{equs}
    where $h$ is the euclidean heat kernel. We recall the standard estimate
    \begin{equs}\label{eq:classiqhk}
        |\partial_x^\mathfrak{l} h(t,x)|\lesssim t^{-(d+|\mathfrak{l}|)/2}\bgroup\bgroup\bgroup\bgroup\left(1+\frac{|x|}{\sqrt{t}}\right)\egroup\egroup\egroup\egroup^{|\mathfrak{l}|}{\mathrm{e}}^{-\frac{|x|^2}{4t}}\,.
    \end{equs}
    We first get the estimate in space
    \begin{equs}
        ~&\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d}\langle x\rangle_\mu^\varsigma|\partial_x^{\mathfrak{l}}(1-\mu^2\Delta)^{-N}(x)|\,\mathrm{d} x\\ &\lesssim\mu^{-(d+|\mathfrak{l}|)}\int_0^\infty s^{-1+(-d+2N-|\mathfrak{l}|)/2}{\mathrm{e}}^{-s}\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d}\langle x\rangle_\mu^\varsigma\bgroup\bgroup\bgroup\bgroup\left(1+\frac{|x|}{\sqrt{\mu^2 s}}\right)\egroup\egroup\egroup\egroup^{2N-2+|\mathfrak{l}|}{\mathrm{e}}^{-\frac{|x|^2}{4\mu^2 s}}\,\mathrm{d} x\,\mathrm{d} s
    \end{equs}
    We can perform the change of variables $x\to\mu\sqrt{s} x$ to get
    \begin{equs}
        ~&\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d}\langle x\rangle_\mu^\varsigma|\partial_x^{\mathfrak{l}}(1-\mu^2\Delta)^{-N}(x)|\,\mathrm{d} x\\ 
        &\lesssim\mu^{-|\mathfrak{l}|}\int_0^\infty s^{-1+(2N-|\mathfrak{l}|)/2}{\mathrm{e}}^{-s}\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d}\langle x\sqrt{s}\rangle^\varsigma\bgroup\bgroup\bgroup\bgroup\left(1+|x|\right)\egroup\egroup\egroup\egroup^{|\mathfrak{l}|}{\mathrm{e}}^{-\frac{|x|^2}{4}}\,\mathrm{d} x\,\mathrm{d} s
    \end{equs}
    We can see that
    \begin{equs}
        \int_0^\infty s^{-1+(2N-|\mathfrak{l}|)/2}{\mathrm{e}}^{-s}\langle x\sqrt{s}\rangle^\varsigma\,\mathrm{d} s\lesssim \langle x\rangle^\varsigma\,,
    \end{equs}
    provided that $|\mathfrak{l}|\leqslant 2N$, so that the above is bounded by
    \begin{equs}
        \mu^{-|\mathfrak{l}|}\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d}\langle x\rangle^\varsigma\bgroup\bgroup\bgroup\bgroup\left(1+|x|\right)\egroup\egroup\egroup\egroup^{|\mathfrak{l}|}{\mathrm{e}}^{-\frac{|x|^2}{4}}\,\mathrm{d} x\lesssim\mu^{-|\mathfrak{l}|}\,.
    \end{equs}
    Using that $\langle t,x\rangle^\varsigma_\mu\lesssim (1+t^{2/\alpha}/\mu^2)^{\varsigma/2}\langle x\rangle_\mu^\varsigma$, we have
    \begin{equs}
        \big\|\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^\varsigma\partial_t^{\mathfrak{l}_0}\partial_x^{\mathfrak{l}}K_\mu\big\|_{L^1_{t,x}}\lesssim\mu^{-N\alpha}\int_0^\infty t^{N-1-\mathfrak{l}_0}{\mathrm{e}}^{-t/\mu^\alpha}\bgroup\bgroup\bgroup\bgroup\left(1+\frac{t}{\mu^\alpha}\right)\egroup\egroup\egroup\egroup^{\mathfrak{l}_0+\frac{\varsigma}{\alpha}}\,\mathrm{d} t\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d}\langle x\rangle_\mu^\varsigma|\partial_x^{\mathfrak{l}}(1-\mu^2\Delta)^{-N}(x)|\,\mathrm{d} x\,.
    \end{equs}
    We just have to estimate the integral in time. A simple change of variables by scaling in $\mu^\alpha$ yields
    \begin{equs}
        \int_0^\infty t^{N-1-\mathfrak{l}_0}{\mathrm{e}}^{-t/\mu^\alpha}\bgroup\bgroup\bgroup\bgroup\left(1+\frac{t}{\mu^\alpha}\right)\egroup\egroup\egroup\egroup^{\mathfrak{l}_0+\frac{\varsigma}{\alpha}}\,\mathrm{d} t=\mu^{\alpha(N-\mathfrak{l}_0)}\int_0^\infty t^{N-1-\mathfrak{l}_0}{\mathrm{e}}^{-t}\bgroup\bgroup\bgroup\bgroup\left(1+t\right)\egroup\egroup\egroup\egroup^{\mathfrak{l}_0+\frac{\varsigma}{\alpha}}\,\mathrm{d} t\lesssim\mu^{\alpha(N-\mathfrak{l}_0)}\,,
    \end{equs}
    provided that $\mathfrak{l}_0\leqslant N$. Putting everything together, we get the result. The proof of (\@saveref{eq:KmuLp}) being in every point similar, we take the freedom not to do it. We now prove (\@saveref{Kmuexp}). We use again the heat kernel representation (\@saveref{heatkernelrep}) to get
    \begin{equs}
        \big\|\mcb e_\ell Q_\mu\big\|_{L^1_x}&\lesssim\mu^{-d}\int_0^\infty s^{-d/2}{\mathrm{e}}^{-s}\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d}\mcb e_{\ell}(x){\mathrm{e}}^{-\frac{|x|^2}{4\mu^2 s}}\,\mathrm{d} x\,\mathrm{d} s\\
        &=\int_0^\infty {\mathrm{e}}^{-s}\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d}{\mathrm{e}}^{\ell\langle \mu\sqrt s x\rangle^{1/2}-\frac{|x|^2}{4}}\,\mathrm{d} x\,\mathrm{d} s
    \end{equs}
    A quick computation shows that
    \begin{equs}
        {\mathrm{e}}^{-s+\sqrt{\ell\mu|x|} s^{1/4}}\lesssim {\mathrm{e}}^{-s/2}{\mathrm{e}}^{c\ell^{4/3}\mu^{2/3}|x|^{2/3}}\,,
    \end{equs}
    where $c$ is a universal constant. So
    \begin{equs}
        \int_0^\infty {\mathrm{e}}^{-s+\sqrt{\ell\mu|x|} s^{1/4}}\,\mathrm{d} s\lesssim {\mathrm{e}}^{c\ell^{4/3}\mu^{2/3}|x|^{2/3}}\,.
    \end{equs}
    Eventually, we have
    \begin{equs}
        \big\|\mcb e_\ell Q_\mu\big\|_{L^1_x}&\lesssim \int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d}{\mathrm{e}}^{c\ell^{4/3}\mu^{2/3}|x|^{2/3}-\frac{|x|^2}{4}}\,\mathrm{d} x\lesssim 1\,.
    \end{equs}
    Finally, a proof of (\@saveref{eq:comKmuKnu}) can be found in \cite{Duc22}, with an easy adaptation with the weight as above. The same holds for (\@saveref{eq:Kmunu}) whose proof can be found in \cite[Lemma 4.10]{Duc21}.

\label{fracheatkernel}
    For $\alpha<2$, we have the pointwise bound on the Green's function $G$ of $(m^2-\Delta)^{\alpha/2}$
    \begin{equs}\label{eq:estimate_heatkernel}
        \big|\partial_t^{\mathfrak{l}_0}\partial_x^\mathfrak{l} G(t,x)\big|\lesssim t^{-\frac{d+|\mathfrak{l}_0,\mathfrak{l}|_\mathfrak{s}}{\alpha}} \big(1+{|x|}/{t^{1/\alpha}}\big)^{-(d+\alpha+|\mathfrak{l}|)}{\mathrm{e}}^{-c m|x|}\,,
    \end{equs}
    where $c>0$ is a constant depending only on $\alpha$ and $d$. For $\alpha=2$, that is to say that $G$ is the Green's function of $m^2-\Delta$, (\@saveref{eq:estimate_heatkernel}) is of course not optimal and we have
    \begin{equs}\label{eq:estimate_heatkernel_alphais2}
        \big|\partial_t^{\mathfrak{l}_0}\partial_x^\mathfrak{l} G(t,x)\big|\lesssim t^{-\frac{d+|\mathfrak{l}_0,\mathfrak{l}|_\mathfrak{s}}{2}} {\mathrm{e}}^{-m^2 t}{\mathrm{e}}^{-c\frac{|x|^2}{4t}}\,,
    \end{equs}
    for any $c\in(0,1)$.

We only prove the first statement since the second one is a more standard estimate. We have the heat kernel decomposition
    \begin{equs}\label{heatrep}
        G(t,x)=\int_0^\infty\frac{1}{(4\pi s)^\frac{d}{2}}{\mathrm{e}}^{-\frac{|x|^2}{4s}}{\mathrm{e}}^{-m^2 s}\theta_\alpha(t,s)\,\mathrm{d} s\,,
    \end{equs}
    where $\theta_\alpha$ is the transition density of an $\alpha/2$-stable subordinator, uniquely characterized by the relation
    \begin{equs}\label{charactheta}
        \int_0^\infty {\mathrm{e}}^{-\lambda s}\theta_\alpha(t,s)\,\mathrm{d} s={\mathrm{e}}^{-t\lambda^\frac{\alpha}{2}}\,.
    \end{equs}
    We have the estimate
    \begin{equs}
        |\partial_t^{\mathfrak{l}_0}\theta_\alpha(t,s)|\lesssim t^{1-\mathfrak{l}_0}s^{-1-\frac{\alpha}{2}}\,.
    \end{equs}




    This yields, reusing the heat kernel estimate (\@saveref{eq:classiqhk}),
    \begin{equs}\label{side2}
        \big|\partial_t^{\mathfrak{l}_0}\partial_x^\mathfrak{l} G(t,x)\big|&\lesssim \int_0^\infty s^{-\frac{d+|\mathfrak{l}|}{2}}\bgroup\bgroup\bgroup\bgroup\left(1+\frac{|x|}{\sqrt{s}}\right)\egroup\egroup\egroup\egroup^{|\mathfrak{l}|}{\mathrm{e}}^{-\frac{|x|^2}{4s}}{\mathrm{e}}^{-m^2 s}t^{1-\mathfrak{l}_0}s^{-1-\frac{\alpha}{2}}\,\mathrm{d} s\\
        &\lesssim t^{1-\mathfrak{l}_0}{\mathrm{e}}^t|x|^{-(d+\alpha+|\mathfrak{l}|)}\int_0^\infty s^{\frac{d+\alpha+|\mathfrak{l}|}{2}-1}\big(1+\sqrt{s}\big)^{|\mathfrak{l}|}{\mathrm{e}}^{-s/4-m^2|x|^2/s}\,\mathrm{d} s\,.
    \end{equs}
    The last integral is bounded by a constant times ${\mathrm{e}}^{-cm|x|}$, where $c$ only depends on $d$ and $\alpha$. Moreover, the characterisation (\@saveref{charactheta}) gives
    \begin{equs}
        \partial_t^{\mathfrak{l}_0}\theta_\alpha(t,s)=(-1)^{\mathfrak{l}_0}t^{-\frac{2+\alpha\mathfrak{l}_0}{\alpha}}\partial_t^{\mathfrak{l}_0}\theta_\alpha(1,st^{-{2/\alpha}})\,.
    \end{equs}
    Taking back (\@saveref{heatrep}), and performing the change of variables $s\to st^{\frac{2}{\alpha}}$, we get, for $|x|^\alpha\leqslant t$,
    \begin{equs}
        \big|\partial_t^{\mathfrak{l}_0}\partial_x^\mathfrak{l} G(t,x)\big|&\lesssim t^{-\frac{d+|\mathfrak{l}|+\alpha\mathfrak{l}_0}{\alpha}}\int_0^\infty s^{-\frac{d+|\mathfrak{l}|+\alpha}{2}-1}\bgroup\bgroup\bgroup\bgroup\left(1+\frac{|x|}{s^{1/2}t^{1/\alpha}}\right)\egroup\egroup\egroup\egroup^{|\mathfrak{l}|}{\mathrm{e}}^{-\frac{|x|^2}{4st^{2/\alpha}}}{\mathrm{e}}^{-m^2st^{2/\alpha}}\partial_t^{\mathfrak{l}_0}\theta_\alpha(1,s)\,\mathrm{d} s\\
        &\lesssim t^{-\frac{d+|\mathfrak{l}_0,\mathfrak{l}|_\mathfrak{s}}{\alpha}}\,.
    \end{equs}
    This bound, together with (\@saveref{side2}), gives the desired result.

\label{heatkernelestimate}
    Let $u$ and $\ell\in{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}$ such that $\mcb e_{-\ell}u\in\mathcal{B}_{r,q}^{-\sigma}$. We have
    \begin{equation}
        \|\mcb e_{-\ell}\mathcal{R}_\mu^2G_\mu u\|_{L^{r}_{x}}\lesssim\mu^{-\sigma}\|\mcb e_{-\ell}u\|_{\mathcal{B}_{r,q}^{-\sigma}}\,.
    \end{equation}

We do the proof in the case $\alpha<2$ since it is the hardest one. We first write, using Lemma \ref{ITexp},
    \begin{equs}
        \mcb e_{-\ell}(x)\big(\mathcal{R}_\mu^2G_\mu u\big)(t,x)&=\mcb e_{-\ell}(x)\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d}\big(\mathcal{R}_\mu^2 G_\mu)(t,x-y)u(y)\,\mathrm{d} y\\
        &=\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d}\mcb e_{-\ell}(x)\mcb e_\ell(y)\big(\mathcal{R}_\mu^2 G_\mu)(t,x-y)\mcb e_{-\ell}(y)u(y)\,\mathrm{d} y\,.
    \end{equs}
    Let us take a closer look at the kernel appearing here. First, we can write that there is a finite set $\mathfrak{P}$ such that
    \begin{equs}
        \big(\mathcal{R}_\mu^2 G_\mu)(t,x-y)=\sum_{\pi\in\mathfrak{P}}G_\mu^\pi(t,x-y)\,,
    \end{equs}
    where each $G_\mu^\pi(t,x-y)$ is of the form $\chi^{(2N-n)}(t/\mu^\alpha)P_\pi(\mu^2/t) G(t,x-y)$ for some polynomial of degree bounded by $n$ for some $0\leqslant n\leqslant 2N$, following Lemma \ref{fracheatkernel}. We get, thanks to Lemma \ref{ITexp},
    \begin{equs}
        \mcb e_{-\ell}(x)\mcb e_\ell(y)|G_\mu^\pi(t,x-y)|&\lesssim\mcb e_\ell(x;y)\chi(t/\mu^\alpha)t^{-\frac{d}{\alpha}} \big(1+{|x-y|}/{t^{1/\alpha}}\big)^{-(d+\alpha)}{\mathrm{e}}^{-c m|x-y|}\\
        &\lesssim\chi(t/\mu^\alpha)t^{-\frac{d}{\alpha}} \big(1+{|x-y|}/{t^{1/\alpha}}\big)^{-(d+\alpha)}\,.
    \end{equs}
    We can conclude with standard heat kernel estimates and the fact that $\chi$ imposes $t\geqslant\mu^\alpha$.

\label{estimdotGmu}
The following holds uniformly in $\mu\in(0,1]$, $\ell\geqslant0$, and $p\in[1,\infty]$,
    \begin{equation}
        \big\|\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^{\varsigma}\mcb e_\ell\mathcal{R}_\mu\dot G_\mu\big\|_{L_{t,x}^{1,p}}\lesssim\mu^{-1+\alpha-d(1-1/p)}\,,
    \end{equation}
    where $0\leqslant\varsigma<\alpha$ if $\alpha<2$ and $\varsigma\geqslant0$ if $\alpha=2$.
    Moreover, we have the weighted estimate
    \begin{equs}\label{GmuL1weight}
        \bgroup\bgroup\bgroup\bgroup\left(\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d}\bgroup\bgroup\bgroup\bgroup\left|\int_0^ts^{-\kappa}\big|\big(\mathcal{R}^2_\mu\dot G_\mu\big)(s,y)\big|\,\mathrm{d} s\mcb e_{\ell}(y)\right|\egroup\egroup\egroup\egroup^p\,\mathrm{d} y\right)\egroup\egroup\egroup\egroup^\frac{1}{p}\lesssim\mu^{-1+\alpha-d(1-1/p)-\kappa}\,.
    \end{equs}

Let us prove the first estimate. We prove it for $\alpha<2$ and the other case is easier, as one can benefit from the Gaussian decay of the heat kernel in $x/\sqrt{t}$. Thanks to Lemma \ref{fracheatkernel}, we have the pointwise estimate
    \begin{multline*}
        |\mathcal{R}_\mu\dot G_\mu(t,x)|\lesssim \sum_{n=0}^N\mu^{-1-\alpha}\chi^{(N-n+1)}(t/\mu^\alpha)\\\times\sum_{k=0}^N t^{-\frac{d+n\alpha+2kd}{\alpha}+1}\mu^\frac{n\alpha+2kd}{\alpha} \big(1+{|x|}/{t^{1/\alpha}}\big)^{-(d+\alpha+2kd)}{\mathrm{e}}^{-cm|x|}\,.
    \end{multline*}
    This allows to get
    \begin{multline*}
        \big\|\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^{\varsigma}\mcb e_\ell\mathcal{R}_\mu\dot G_\mu\big\|_{L_{t,x}^{1,p}}\lesssim \mu^{-1-\alpha}\sum_{n,k=0}^N\int_{\mu^\alpha}^{2\mu^\alpha}t^{-\frac{d+n\alpha+2kd}{\alpha}+1}\mu^\frac{n\alpha+2kd}{\alpha}\\\times\bgroup\bgroup\bgroup\bgroup\left(\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d}\langle t,x\rangle_\mu^{p\varsigma}\big(1+{|x|}/{t^{1/\alpha}}\big)^{-p(d+\alpha+2kd)}{\mathrm{e}}^{p\big(\ell\langle x\rangle^\frac{1}{2}-cm|x|\big)}\,\mathrm{d} x\right)\egroup\egroup\egroup\egroup^\frac{1}{p}\,\mathrm{d} t\,.
    \end{multline*}
    We can now perform the changes of variables $t\to\mu^\alpha t$ and $x\to\mu x$. It yields
    \begin{equs}
        &\big\|\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^{\varsigma}\mathcal{R}_\mu\dot G_\mu\big\|_{L_{t,x}^{1,p}}\\
        &\lesssim\mu^{-1+\alpha-d(1-1/p)}\sum_{n,k=0}^N\int_1^2 t^{-\frac{d+n\alpha+2kd}{\alpha}+1}\bgroup\bgroup\bgroup\bgroup\left(\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d}\langle t,x\rangle^{p\varsigma}\big(1+{|x|}/{t^{1/\alpha}}\big)^{-p(d+\alpha+2kd)}\,\mathrm{d} x\right)\egroup\egroup\egroup\egroup^\frac{1}{p}\,\mathrm{d} t\\
        &\lesssim \mu^{-1+\alpha-d(1-1/p)}\sum_{k=0}^N\bgroup\bgroup\bgroup\bgroup\left(\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d}\big(1+{|x|}\big)^{-p(d+\alpha-\varsigma+2Nd)}\,\mathrm{d} x\right)\egroup\egroup\egroup\egroup^\frac{1}{p}\,.
    \end{equs}
    This last integral being finite, we get the result. Note that at this point, it is crucial that the exponent on $\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu$ is smaller than $\alpha$ for the integral to be convergent. We now turn to the second estimate. With the same arguments, it can be bounded by
    \begin{multline*}
        \mu^{-1-\alpha-d(1-1/p)-\kappa}\sum_{n,k=0}^N\bigg(\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d}\bgroup\bgroup\bgroup\bgroup\left|\int_1^2 s^{-\frac{d+2n\alpha+2kd}{\alpha}+1-\kappa}\big(1+{|y|}/{s^{1/\alpha}}\big)^{-d+\alpha+4kd}\,\mathrm{d} s\right|\egroup\egroup\egroup\egroup^p\\
        \times{\mathrm{e}}^{p\big(\ell|y|^{1/2}-cm\mu|y|\big)}\,\mathrm{d} y\bigg)^\frac{1}{p}
    \end{multline*}
    Noticing that the exponential above is bounded, we get the result as above.

\label{intKmuweight}
The following estimate holds uniformly in $\mu\in(0,1]$ and $x\in{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d$,
\begin{equation}
\int_{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}\langle t,x\rangle_\mu^{\alpha-\beta}K_{1,\mu}^{*N}(t,x)\,\mathrm{d} t\lesssim \langle x\rangle_\mu^{\alpha-\beta}Q_\mu^{*N}(x).
\end{equation}

We first compute $K_\mu$ explicitely:
\begin{equs}
    K_{1,\mu}^{*N}(t,x)=\mu^{-N\alpha }\BF{1}_{(0,\infty)}(t)\frac{t^{N-1}}{(N-1)!}{\mathrm{e}}^{-t/\mu^\alpha}Q_\mu^{*N}(x).
\end{equs}
Moreover, we have, for $(t,x)\in{\Lambda}$, $\langle t,x\rangle_\mu^{\alpha-\beta}\lesssim(1+t^{2/\alpha}/\mu^2)^\frac{\alpha-\beta}{2}\langle x\rangle_\mu^{\alpha-\beta}$. It yields
\begin{equs}
    \int_{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}\langle t,x\rangle_\mu^{\alpha-\beta}K_{1,\mu}^{*N}(t,x)\,\mathrm{d} t\lesssim\mu^{-N\alpha}\langle x\rangle_\mu^{\alpha-\beta}Q_\mu^{*N}(x)\int_0^\infty\bgroup\bgroup\bgroup\bgroup\left(1+\frac{t^{2/\alpha}}{\mu^2}\right)\egroup\egroup\egroup\egroup^\frac{\alpha-\beta}{2}t^{N-1}{\mathrm{e}}^{-t/\mu^\alpha}\,\mathrm{d} t.
\end{equs}
Performing the change of variable $t\to\mu^\alpha t$ in the last integral, we get that it equals
\begin{equs}
\mu^{N\alpha}\int_0^\infty(1+t^{2/\alpha})^\frac{\alpha-\beta}{2}t^{N-1}{\mathrm{e}}^{-t}\,\mathrm{d} t\lesssim\mu^{N\alpha}.
\end{equs}
From this, we get the result.

Let $a\in[0,3/2]$ and $s\leqslant t$. The following estimates hold for $t\in(0,1]$,
    \begin{equation}\label{eq:estMt}
        \Big|\partial_t^{\mathfrak{l}_0}\partial_x^{\mathfrak{l}_1}\partial_y^{\mathfrak{l}_2}\Big({\mathrm{e}}^{as\frac{|x|^2+|y|^2}{8}}M(t,x,y)\Big)\Big|\lesssim t^{-\mathfrak{l}_0-\frac{|\mathfrak{l}_1|+|\mathfrak{l}_2|}{2}}G(8t,x-y){\mathrm{e}}^{-3t\frac{|x+y|^2}{32}}\,,                               
    \end{equation}
    and
    \begin{equs}\begin{aligned}
  \label{eq:estimatediffkernels}
\Big|\partial_t^{\mathfrak{l}_0}\partial_x^{\mathfrak{l}_1}\partial_y^{\mathfrak{l}_2}\Big({\mathrm{e}}^{s\frac{|x|^2+|y|^2}{8}}\big(M(t,x,y)-&{\mathrm{e}}^{-t\frac{|x|^2+|y|^2}{4}}G(t,x-y)\big)\Big)\Big|\\&\lesssim t^{1-\mathfrak{l}_0-\frac{|\mathfrak{l}_1|+|\mathfrak{l}_2|}{2}}\big(|x|^2+|y|^2\big)G(8t,x-y)\,.                               
           \end{aligned}
    \end{equs}

Let us start with the first estimate. We have
    \begin{equs}
         ~&\Big|\partial_t^{\mathfrak{l}_0}\partial_x^{\mathfrak{l}_1}\partial_y^{\mathfrak{l}_2}\Big({\mathrm{e}}^{as\frac{|x|^2+|y|^2}{8}}M(t,x,y)\Big)\Big|\lesssim\sum_{i_1=0}^{\mathfrak{l}_1}\sum_{i_2=0}^{\mathfrak{l}_2}\big|\partial_t^{\mathfrak{l}_0}\partial_x^{i_1}\partial_y^{i_2}M(t,x,y)\big|\Big|\partial_x^{\mathfrak{l}_1-i_1}\partial_y^{\mathfrak{l}_2-i_2}{\mathrm{e}}^{as\frac{|x|^2+|y|^2}{8}}\Big|\\
         &\lesssim \sum_{i_1=0}^{\mathfrak{l}_1}\sum_{i_2=0}^{\mathfrak{l}_2}t^{-\mathfrak{l}_0-\frac{|i_1|+|i_2|}{2}}\bigg(1+\frac{|x-y|}{\sqrt{t}}\bigg)^{|\mathfrak{l}_0|}\big(1+\sqrt{t}|x|\big)^{|i_1|}\big(1+\sqrt{t}|y|\big)^{|i_2|}{\mathrm{e}}^{-\frac{|x-y|^2}{4t}}{\mathrm{e}}^{-t\frac{|x+y|^2}{4}}\\
         &\qquad\times s^{\frac{|\mathfrak{l}_1-i_1|+|\mathfrak{l}_2-i_2|}{2}}(1+\sqrt{s}|x|)^{|\mathfrak{l}_1-i_1|}(1+\sqrt{s}|y|)^{|\mathfrak{l}_2-i_2|}{\mathrm{e}}^{as\frac{|x|^2+|y|^2}{8}}\\
         &\lesssim \sum_{i_1=0}^{\mathfrak{l}_1}\sum_{i_2=0}^{\mathfrak{l}_2}t^{-\mathfrak{l}_0-\frac{|i_1|+|i_2|}{2}}{\mathrm{e}}^{-7\frac{|x-y|^2}{32t}}{\mathrm{e}}^{-7t\frac{|x+y|^2}{32}}s^{\frac{|\mathfrak{l}_1-i_1|+|\mathfrak{l}_2-i_2|}{2}}{\mathrm{e}}^{3s\frac{|x|^2+|y|^2}{16}}\\
         &\lesssim t^{-\mathfrak{l}_0-\frac{|\mathfrak{l}_1|+|\mathfrak{l}_2|}{2}}{\mathrm{e}}^{-\frac{|x-y|^2}{32t}}{\mathrm{e}}^{-3\frac{|x-y|^2}{16t}-7t\frac{|x+y|^2}{32}+3t\frac{|x|^2+|y|^2}{16}}
    \end{equs}
    We rework a bit the term in the second exponential.
    \begin{equs}
        \frac{3t}{16}(|x|^2+|y|^2)-\frac{7t}{32}|x+y|^2-\frac{3}{16t}|x-y|^2\leqslant \frac{t}{32}\Big(6(|x|^2+|y|^2)-7|x+y|^2-6|x-y|^2\Big)\,.
    \end{equs}
    We then get
    \begin{equs}
       6(|x|^2+|y|^2)-7|x+y|^2-6|x-y|^2&=-6(|x|^2+|y|^2)-|x+y|^2\\


       &\leqslant -|x+y|^2\,,
    \end{equs}
    which yields the result. The second estimate follows the same lines. One has to note that
    \begin{multline*}
        \big|\partial_t^{\mathfrak{l}_0}\partial_x^{\mathfrak{l}_1}\partial_y^{\mathfrak{l}_2}\big(M(t,x,y)-{\mathrm{e}}^{-t\frac{|x|^2+|y|^2}{4}}G(t,x-y)\big)\big|\\\lesssim t^{1-\mathfrak{l}_0-\frac{|\mathfrak{l}_1|+|\mathfrak{l}_2|}{2}}\big(|x|^2+|y|^2\big)\bigg(1+\frac{|x-y|}{\sqrt{t}}\bigg)^{|\mathfrak{l}_0|}\big(1+\sqrt{t}|x|\big)^{|\mathfrak{l}_1|}\big(1+\sqrt{t}|y|\big)^{|\mathfrak{l}_2|}{\mathrm{e}}^{-\frac{|x-y|^2}{4t}}{\mathrm{e}}^{-t\frac{|x|^2+|y|^2}{4}}\,,
    \end{multline*}
    and proceed in the same lines.

\label{lemma:estimMmu}
    For every $n,m$, $\varsigma>0$, and $\mu\in(0,1]$,
    \begin{equation}
        \big\|\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle^\varsigma_\mu(\mathcal{T}_{\mu,n}\otimes \mathcal{T}_{\mu,m})\dot M_\mu\big\|_{\mathcal{L}(L_{t,x}^{\infty,p},L_{t,x}^{\infty,r})}\lesssim\mu^{1-d(1/r-1/p)}\,,
    \end{equation}
    and
    \begin{equation}\label{eq:PmuTmuMmu}
        \big\|(\mathscr{P}_\mu\otimes \mathcal{T}_{\mu,m})\dot M_\mu\big\|_{\mathcal{L}(L_{t,x}^{\infty,p},L_{t,x}^{\infty,r})}\lesssim\mu^{1-d(1/r-1/p)}\,,
    \end{equation}
    $\mathcal{T}_{\mu,n}$ was defined in (\@saveref{eq:defTmu}).

For this proof we let $a=a_n\vee a_m\in[1,2)$. We recall that $\dot M_\mu(t,x,y)=-2\mu^{-3}t\chi'(t/\mu^2)M(t,x,y)$. Then, applying (\@saveref{eq:estMt}) with $s=\mu^2$ (we know that $\mu^2\leqslant t$ thanks to the support properties of $\chi$), we get
    \begin{equs}
        \big|\big((\mathcal{T}_{\mu,n}\otimes \mathcal{T}_{\mu,m})\dot M_\mu\big)(t,x,y)\big|&\lesssim\sum_{n=0}^N\mu^{-3}t\chi^{(N-n+1)}(t/\mu^2)t^{-N(1+2d)}\mu^{2N(1+2d)}G(8t/3,x-y)\\
        &\lesssim|\dot G_\mu(8t,x-y)|\,.
    \end{equs}
    We have brutally bounded the Gaussian weight by $1$. Then, by Young's convolution inequality,
    \begin{equs}
        ~&\big\|\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle^\varsigma_\mu(\mathcal{T}_{\mu,n}\otimes \mathcal{T}_{\mu,m})\dot M_\mu\big\|_{\mathcal{L}(L_{t,x}^{\infty,p},L_{t,x}^{\infty,r})}\lesssim\|\langle 
  \mathbin{\mathpalette\bigcdot@{}} 
\rangle_\mu^\varsigma \dot G_\mu\|_{L_{t,x}^{1,q}}\lesssim\mu^{1-d(1/r-1/p)}\,,
    \end{equs}
    where $\frac{1}{q}=1+\frac{1}{p}-\frac{1}{r}$, and the last step follows Lemma \ref{estimdotGmu}, but with the classical Laplacian ($\alpha=2$). The treatment of the second estimate follows the same lines, observing that
    \begin{equs}
        |(\mathscr{P}_\mu\otimes\mathrm{Id})M(t,x,y)|=|((1-\mu^{4}\mathrm{H}^2)^N\otimes\mathrm{Id})M(t,x,y)|\lesssim\bigg(1+\frac{\mu^{4}}{t^{2}}\bigg)^N| G(t,x-y)|{\mathrm{e}}^{-3t\frac{|x|^2+|y|^2}{16}}\,.
    \end{equs}

\label{lemma:diffMG}
    The following holds for $\mu\in(0,1]$
    \begin{equation}
        \big|\mathcal{T}_{\mu,0}^{\otimes2}\big(\dot M_\mu-\mcb W_\mu^{-1}\dot G_\mu\big)(t,x,y)\big|\lesssim \mu^2\big(\mu^2+|x|^2+|y|^2\big)|\dot G_\mu(8t,x-y)|\,.
    \end{equation}

We first separate the following quantity in two terms
    \begin{equs}
        ~&{\mathrm{e}}^{\mu^2\frac{|x|^2+|y|^2}{8}}\Big(\dot M_\mu(t,x,y)-{\mathrm{e}}^{-\mu^2\frac{|x|^2+|y|^2}{8}}\dot G_\mu(t,x-y)\Big)\\
        &={\mathrm{e}}^{\mu^2\frac{|x|^2+|y|^2}{8}}\Big(\dot M_\mu(t,x,y)-{\mathrm{e}}^{-t\frac{|x|^2+|y|^2}{4}}\dot G_\mu(t,x-y)\Big)+\Big({\mathrm{e}}^{-(2t-\mu^2)\frac{|x|^2+|y|^2}{8}}-1\Big)\dot G_\mu(t,x-y)\\
        &\stackrel{\mbox{\tiny def}}{=} D_\mu^1(t,x,y)+D_\mu^2(t,x,y)\,.
    \end{equs}
    With this notation, we have
    \begin{equs}
        \mathcal{T}_{\mu,0}^{\otimes2}(\dot M_\mu-\mcb W_\mu^{-1}\dot G_\mu)=\mathcal{R}_\mu^{\otimes2}(D_\mu^1+D_\mu^2)\,.
    \end{equs}
    For the first term, we write
    \begin{multline*}
        {\mathrm{e}}^{\mu^2\frac{|x|^2+|y|^2}{8}}\Big(\dot M_\mu(t,x,y)-{\mathrm{e}}^{-t\frac{|x|^2+|y|^2}{4}}\dot G_\mu(t,x-y)\Big)\\
        =\mu^{-3}t\chi'(t/\mu^2){\mathrm{e}}^{\mu^2\frac{|x|^2+|y|^2}{8}}\Big(M(t,x,y)-{\mathrm{e}}^{-t\frac{|x|^2+|y|^2}{4}}G(t,x-y)\Big)\,.
    \end{multline*}
    Then, thanks to (\@saveref{eq:estimatediffkernels}), we have
    \begin{equs}
        ~&\big|\big(\mathcal{R}_\mu^{\otimes2}D_\mu^1\big)(t,x,y)\big|\\
        &\lesssim\sum_{n=0}^N\mu^{-3}t\chi^{(N-n+1)}(t/\mu^2) t^{1-n(1+2d)}\mu^{n(1+2d)}\big(|x|^2+|y|^2\big)G(8t/3,x-y)\\
        &\lesssim\mu^2\big(|x|^2+|y|^2\big)\dot G_\mu(8t,x-y)\,.
    \end{equs}
    For the second term we can write, using that $\mu^2\leqslant2t-\mu^2\leqslant3\mu^2$ (again thanks to the support properties of $\chi$),
    \begin{equs}
        ~&|(\mathcal{R}_{\mu}^{\otimes2}D_\mu^2)(t,x,y)|\\
        &\lesssim \bgroup\bgroup\bgroup\bgroup\left(\Big({\mathrm{e}}^{-(2t-\mu^2)\frac{|x|^2+|y|^2}{8}}-1\Big)+\sum_{n=1}^N\mu^{4n}\big(1+\mu(|x|+|y|)\big)^{2n}{\mathrm{e}}^{-(2t-\mu^2)\frac{|x|^2+|y|^2}{8}}\right)\egroup\egroup\egroup\egroup\\
        &\quad\times\mu^{-3}t\chi^{(N-n+1)}(t/\mu^2) t^{1-(1+2d)(N-n)}\mu^{(1+2d)(N-n)}G(t,x-y)\\
        &\lesssim \bgroup\bgroup\bgroup\bgroup\left(\mu^2(|x|^2+|y|^2)+\sum_{n=1}^N\mu^{4n}\big(1+\mu(|x|+|y|)\big)^{2n}{\mathrm{e}}^{-\mu^2\frac{|x|^2+|y|^2}{8}}\right)\egroup\egroup\egroup\egroup\dot G_\mu(t,x-y)\\
        &\lesssim \mu^2(\mu^2+|x|^2+|y|^2)\dot G_\mu(t,x-y)\,,
    \end{equs}
    which concludes the proof.

\label{lemma:heatflowmehler}
    Let $\sigma$, $1<r<\infty$ and $1\leqslant q\leqslant\infty$. For any $u\in\mathscr{B}_{r,q}^{-\sigma}$, it holds
    \begin{equation}
        \|\mathcal{T}_\mu M_\mu u\|_{L_x^r}\lesssim\mu^{-\sigma}\|u\|_{\mathscr{B}_{r,q}^{-\sigma}}\,.
    \end{equation}

First, we factorize $M_\mu(t)=M_\mu((1-\varepsilon)t)M(\varepsilon t)$, for some small enough $\varepsilon>0$ so that $a_n<2-2\varepsilon$, using the semigroup property. Thanks to (\@saveref{eq:estMt}), we know that $(\mathcal{T}_\mu\otimes\mathrm{Id}) M_\mu((1-\varepsilon)t)$ is a sum over a finite set $\mathfrak{P}$ of kernels
    \begin{equs}
        \big((\mathcal{T}_\mu\otimes\mathrm{Id}) M_\mu((1-\varepsilon) 
  \mathbin{\mathpalette\bigcdot@{}} 
)\big)(t,x,y)=\sum_{\pi\in \mathfrak{P}} M_\mu^\pi(t,x,y)\,,
    \end{equs}
    where all the kernels $M_\mu^\pi$ are bounded by a quantity of the form
    \begin{equs}
         \chi^{(N-n)}(t/\mu^2)t^{-N(1+d)}\mu^{2N(1+d)}G(8t/3,x-y)e^{-3t\frac{|x+y|^2}{32}}\lesssim G(8t,x-y)e^{-3t\frac{|x+y|^2}{32}}\BF{1}_{t\geqslant\mu^2}\,,
    \end{equs}
    for some $0\leqslant n\leqslant N$. We then have
    \begin{equs}
        \sup_{x\in{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d}\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d} |M_\mu^\pi(t,x,y)|\,\mathrm{d} y + \sup_{y\in{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d}\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d} |M_\mu^\pi(t,x,y)|\,\mathrm{d} x\lesssim \BF{1}_{t\geqslant\mu^2}\,,
    \end{equs}
    and the Schur test implies
    \begin{equs}
        \|\mathcal{T}_\mu M_\mu u\|_{L_x^r}\leqslant\sum_{\pi\in \mathfrak{P}} \bgroup\bgroup\bgroup\bgroup\left(\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d}\bgroup\bgroup\bgroup\bgroup\left|\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d}M_\mu^\pi(t,x,y)u(y)\,\mathrm{d} y\right|\egroup\egroup\egroup\egroup^r\,\mathrm{d} x\right)\egroup\egroup\egroup\egroup^\frac{1}{r} \lesssim \BF{1}_{t\geqslant\mu^2} \|M(\varepsilon t)u\|_{L_x^r}\,.
    \end{equs}
    Thus, by Proposition 3.4.3. in \cite{Ha06},
    \begin{equs}\label{Eq:IntermediateSchauderMehlerExponentialWeight}
        \|\mathcal{T}_\mu M_\mu u\|_{L_x^r}\lesssim\mu^{-\sigma}\|u\|_{\mathscr{H}^{-\sigma,r}}\,.
    \end{equs}
    The result follows by real interpolation, using Proposition \ref{Prop:HermiteSpacesInterpolation}.

Let $p,r\in[1,\infty]$, we have
    \begin{equation}\label{eq:msQleq1}
        \|\mathscr{Q}_\mu\|_{\mathcal{L}(L_{x}^{\infty})}\leqslant1\,,
    \end{equation}
    uniformly in $\mu$, and
    \begin{equation}\label{eq:msQmumsQnu}
        \|(\mathscr{Q}_\mu-\mathrm{Id})\mathscr{Q}_\nu\|_{\mathcal{L}(L_{x}^{\infty})}\lesssim\mu^2\nu^{-2}\,,
    \end{equation}
    uniformly in $\mu\leqslant\nu$.

For the first statement, we use the Mehler kernel representation
    \begin{equs}
        \mathscr{Q}_\mu(x,y)=\int_0^\infty M(\mu^2 s,x,y){\mathrm{e}}^{-s}\,\mathrm{d} s\,.
    \end{equs}
    We then just have to use the bound $|M(\mu^2s,x,y)|\leqslant |G(\mu^2 s,x-y)|$, and conclude as in the proof of (\@saveref{eq:normKmu}). For the second one, we write
    \begin{equs}
        (1-(1+\mu^2\mathrm{H})^{-1})(1+\nu^2\mathrm{H})^{-1}&=\mu^2\mathrm{H}(1+\mu^2\mathrm{H})^{-1}(1+\nu^2\mathrm{H})^{-1}\\
        &=\mu^2\nu^{-2}(1-(1+\nu^2\mathrm{H})^{-1})(1+\mu^2\mathrm{H})^{-1}\,,
    \end{equs}
    and we conclude with the help of (\@saveref{eq:msQleq1}).

Let $\psi\colon\Lambda\to{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}$, $0<\nu\leqslant\mu\leqslant1$, $n\leqslant m$, and $p\in[1,\infty]$, then
    \begin{equs}\label{eq:lessJn}
        \|J_{\mu,m}\psi\|_{L_{t,x}^p}\lesssim\|J_{\mu,n}\psi\|_{L_{t,x}^p}\,,
    \end{equs}
    and
    \begin{equs}\label{eq:lessJmu}
        \|J_{\mu,n}\psi\|_{L_{t,x}^p}\lesssim\|J_{\nu,n}\psi\|_{L_{t,x}^p}\,.
    \end{equs}

We start with the proof of the first statement. We have
    \begin{equs}
        \big(J_{\mu,m}\psi\big)(t,x)&=\int_0^\infty\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d} K_\mu(t-s,x-y){\mathrm{e}}^{-a_m\mu^2\frac{|y|^2}{8}}\psi(s,y)\,\mathrm{d} y\,\mathrm{d} s\\
        &=\int_0^\infty\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d} K_\mu(t-s,x-y){\mathrm{e}}^{-a_{n-m}\mu^2\frac{|y|^2}{8}}{\mathrm{e}}^{-a_n\mu^2\frac{|y|^2}{8}}\psi(s,y)\,\mathrm{d} y\,\mathrm{d} s\\
        &=\int_0^\infty\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d} \mathcal{R}_\mu\Big( K_\mu(t-s,x-y){\mathrm{e}}^{-a_{n-m}\mu^2\frac{|y|^2}{8}}\Big)\big(J_{\mu,n}\psi\big)(s,y)\,\mathrm{d} y\,\mathrm{d} s\,.
    \end{equs}
    $\mathcal{R}_\mu$ is here applied on $(s,y)$. Thus we get using Young's convolution inequality then (\@saveref{eq:estimreloue}),
    \begin{equs}
        \|J_{\mu,m}\psi\|_{L_{t,x}^p}&\leqslant\sup_{t,x}\int_0^\infty\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d} \Big|\mathcal{R}_\mu\Big( K_\mu(t-s,x-y){\mathrm{e}}^{-a_{n-m}\mu^2\frac{|y|^2}{8}}\Big)\Big|\,\mathrm{d} y\,\mathrm{d} s\times\|J_{\mu,n}\psi\|_{L_{t,x}^p}\\
        &\lesssim\sup_{t,x}\int_0^\infty\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d}{\@fontswitch\relax\mathcal S}_\mu \Tilde K(t-s,x-y)\big(1+\mu^2|y|^2\big)^N{\mathrm{e}}^{-a\mu^2\frac{|y|^2}{8}} \,\mathrm{d} y\,\mathrm{d} s\times\|J_{\mu,n}\psi\|_{L_{t,x}^p}\\
        &\lesssim\sup_{t,x}\int_0^\infty\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d}{\@fontswitch\relax\mathcal S}_\mu \Tilde K(t-s,x-y) \,\mathrm{d} y\,\mathrm{d} s\times\|J_{\mu,n}\psi\|_{L_{t,x}^p}\\
        &=\|\Tilde K\|_{L^1_{t,x}}\|J_{\mu,n}\psi\|_{L_{t,x}^p}\lesssim\|J_{\mu,n}\psi\|_{L_{t,x}^p}\,.
    \end{equs}
    The proof of the second statement is somewhat similar. We have
    \begin{equs}
        \big(J_{\mu,n}\psi\big)(t,x)&=\int_0^\infty\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d} K_\mu(t-s,x-y){\mathrm{e}}^{-a_n\mu^2\frac{|y|^2}{8}}\psi(s,y)\,\mathrm{d} y\,\mathrm{d} s\\
        &=\int_0^\infty\int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d} \mathcal{R}_\nu K_\mu(t-s,x-y){\mathrm{e}}^{-a_n(\mu^2-\nu^2)\frac{|y|^2}{8}}\big(J_{\nu,n}\psi\big)(s,y)\,\mathrm{d} y\,\mathrm{d} s\,.
    \end{equs}
    Using again Young's convolution inequality, we have
    \begin{equs}
        \|J_{\mu,n}\psi\|_{L_{t,x}^p}\leqslant\|\mathcal{R}_\nu K_\mu\|_{L^1_{t,x}}\|J_{\nu,n}\psi\|_{L_{t,x}^p}\lesssim\|J_{\nu,n}\psi\|_{L_{t,x}^p}\,,
    \end{equs}
    where the last bound follows from (\@saveref{eq:Kmunu}).

Let $a\in[0,2)$, and $\mu\in(0,1]$. There is an integrable kernel $\Tilde K$ with exponential decay such that
    \begin{equation}\label{eq:estimreloue}
        \Big|\mathcal{R}_\mu\Big( K_\mu{\mathrm{e}}^{-a\mu^2\frac{| 
  \mathbin{\mathpalette\bigcdot@{}} 
|^2}{8}}\Big)(t,x)\Big|\lesssim {\@fontswitch\relax\mathcal S}_\mu\Tilde K(t,x)\big(1+\mu^2|x|^2\big)^N{\mathrm{e}}^{-a\mu^2\frac{|x|^2}{8}}\,.
    \end{equation}
    There is an integrable kernel $\hat K$ with exponential decay such that
    \begin{equation}\label{eq:estimrelouex2}
        \Big|\mathcal{R}_\mu\Big( K_\mu| 
  \mathbin{\mathpalette\bigcdot@{}} 
|^2{\mathrm{e}}^{-a\mu^2\frac{| 
  \mathbin{\mathpalette\bigcdot@{}} 
|^2}{8}}\Big)(t,x)\Big|\lesssim {\@fontswitch\relax\mathcal S}_\mu\hat K(t,x)\big(1+|x|^2\big)\big(1+\mu^2|x|^2\big)^N{\mathrm{e}}^{-a\mu^2\frac{|x|^2}{8}}\,.
    \end{equation}

We only provide the main ingredients of the proof. Thanks to the Leibniz rule, the operators in $\mathcal{R}_\mu$ are distributed on the two (or three terms) of the expression. When they act on $K_\mu$, they only reduce the convolution exponent, up to creating a Dirac delta. For the other terms, we use that
    \begin{equs}
        \mu^{|k|}\Big|\partial_x^k{\mathrm{e}}^{-a\mu^2\frac{|x|^2}{8}}\Big|\lesssim\mu^{2|k|}\big(1+\mu|x|\big)^{|k|}{\mathrm{e}}^{-a\mu^2\frac{|x|^2}{8}}\,,
    \end{equs}
    for every multi-index $k$.

The following estimate holds for $z_1,z_2,z_3\in{\Lambda}$, $\mu\in(0,1]$,
    \begin{equs}\label{triangleineq}
        \langle z_1;z_3\rangle_{\mu}&\lesssim\langle z_1;z_2\rangle_{\mu}\langle z_2;z_3\rangle_{\mu}\,.
    \end{equs}
    Moreover, for $z\in{\Lambda}$, and $\nu\leqslant\mu$,
    \begin{equs}\label{estimweight}
    \frac{\langle z\rangle_{\mu}^{\alpha-\beta}}{\langle z\rangle_{\nu}^{\alpha-\beta}}\big(1-\langle z\rangle_{\mu}^{-2}\big)&\lesssim\mu^{\beta-\alpha}\nu^{\alpha-\beta}\,.
    \end{equs}

\label{ITexp}
    We have, for $\ell>0$ and $x_1,x_2\in{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d$,
    \begin{equation}
        \mcb e_{-\ell}(x_1)\mcb e_{\ell}(x_2)\lesssim \mcb e_{\ell}(x_1;x_2)\,.
    \end{equation}

\label{HaiLabestim}
    The following holds for $s<t$ and $\ell\in{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}$.
    \begin{equation}
        \sup_{x\in{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d}\frac{\langle x\rangle^\kappa\mcb e_{\ell+s}(x)}{\mcb e_{\ell+t}(x)}\lesssim (t-s)^{-\kappa/2}\,.
    \end{equation}

This is a simple consequence of the inequality
    \begin{equs}
        \sup_{x\in{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d}\frac{\langle x\rangle^\kappa\mcb e_{\ell+s}(x)}{\mcb e_{\ell+t}(x)}\leqslant \bgroup\bgroup\bgroup\bgroup\left(\frac{\kappa}{2(t-s)}\right)\egroup\egroup\egroup\egroup^\frac{\kappa}{2}{\mathrm{e}}^{-\kappa/2}\,.
    \end{equs}

\label{Lem:LooseAsymptoticFractionalHeatTrace}
    When $t$ goes to $0$,
    $$\operatorname{Tr}\bgroup\bgroup\bgroup\bgroup\left({\mathrm{e}}^{-t|\nabla|^\alpha}\right)\egroup\egroup\egroup\egroup\sim \frac{2\pi^{d/2}\Gamma(d/\alpha)}{\alpha\Gamma(d/2)} t^{-\frac{d}{\alpha}}.$$

The result follows from Poisson formula
    $$\operatorname{Tr}\bgroup\bgroup\bgroup\bgroup\left({\mathrm{e}}^{-t|\nabla|^\alpha}\right)\egroup\egroup\egroup\egroup = \sum_{k\in{{\mathchoice{\hbox{\bfZ}}{\hbox{\bfZ}} 
        {\hbox{\scriptsize\bfZ}}{\hbox{\tiny\bfZ}}}}^d}{\mathrm{e}}^{-t|k|^\alpha} = t^{-\frac{d}{\alpha}}\sum_{k\in{{\mathchoice{\hbox{\bfZ}}{\hbox{\bfZ}} 
        {\hbox{\scriptsize\bfZ}}{\hbox{\tiny\bfZ}}}}^d}F(2\pi k/t^{1/\alpha})\,,$$
    with $F = \mathcal{F}({\mathrm{e}}^{-|x|^\alpha})$, verifying $F(0) = \frac{2\pi^{d/2}\Gamma(d/\alpha)}{\alpha\Gamma(d/2)}$ and $F(\eta)\leqslant \frac{2\pi^{d/2}\Gamma(d/\alpha)}{\alpha\Gamma(d/2)} |\eta|^{-d-\alpha}$.

\label{Cor:WeylLawEquivTrace}
    Let $A$ be a selfadjoint operator on $L_x^2({{\mathchoice{\hbox{\bfT}}{\hbox{\bfT}} 
        {\hbox{\scriptsize\bfT}}{\hbox{\tiny\bfT}}}}^d)$ with discrete spectrum $(\lambda_n)_{n\in{{\mathchoice{\hbox{\bfN}}{\hbox{\bfN}} 
        {\hbox{\scriptsize\bfN}}{\hbox{\tiny\bfN}}}}}$. Assume
    $$\operatorname{Tr}\bgroup\bgroup\bgroup\bgroup\left({\mathrm{e}}^{-t|\nabla|^\alpha}\right)\egroup\egroup\egroup\egroup\sim \operatorname{Tr}\bgroup\bgroup\bgroup\bgroup\left({\mathrm{e}}^{-tA}\right)\egroup\egroup\egroup\egroup$$
    as $t$ goes to 0. Then, 
    $$\mathcal{N}_A(\lambda) = \#\{n\in{{\mathchoice{\hbox{\bfN}}{\hbox{\bfN}} 
        {\hbox{\scriptsize\bfN}}{\hbox{\tiny\bfN}}}},\; \lambda_n\leqslant\lambda\}\sim \frac{\pi^{\frac{d}{2}}\lambda^{\frac{d}{\alpha}}}{\Gamma\bgroup\bgroup\bgroup\bgroup\left(\frac{d}{2}+1\right)\egroup\egroup\egroup\egroup}$$
    as $\lambda$ goes to $\infty$.

\label{Lem:LooseAsymptoticMehlerTrace}
    When $t$ goes to $0$,
    $$\operatorname{Tr}\bgroup\bgroup\bgroup\bgroup\left({\mathrm{e}}^{t(\Delta-|x|^2)}\right)\egroup\egroup\egroup\egroup\sim (2t)^{-d}.$$

The result follows from the direct computation
    $$\operatorname{Tr}\bgroup\bgroup\bgroup\bgroup\left({\mathrm{e}}^{t(\Delta-|x|^2)}\right)\egroup\egroup\egroup\egroup = \int_{{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d} M(t,x,x)\,\mathrm{d} x = \bgroup\bgroup\bgroup\bgroup\left(2\tanh(t)\sinh(2t)\right)\egroup\egroup\egroup\egroup^{-\frac{d}{2}}\sim (2t)^{-d}.$$

\label{Cor:WeylLawEquivTraceOH}
    Let $A$ be a self-adjoint operator on $L_x^2({{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d)$ with discrete spectrum $(\lambda_n)_{n\in{{\mathchoice{\hbox{\bfN}}{\hbox{\bfN}} 
        {\hbox{\scriptsize\bfN}}{\hbox{\tiny\bfN}}}}}$. Assume
    $$\operatorname{Tr}\bgroup\bgroup\bgroup\bgroup\left({\mathrm{e}}^{t(\Delta-|x|^2)}\right)\egroup\egroup\egroup\egroup\sim \operatorname{Tr}\bgroup\bgroup\bgroup\bgroup\left({\mathrm{e}}^{-tA}\right)\egroup\egroup\egroup\egroup\,,$$
    as $t$ goes to $0$. Then, 
    $$\mathcal{N}_A(\lambda) = \#\{n\in{{\mathchoice{\hbox{\bfN}}{\hbox{\bfN}} 
        {\hbox{\scriptsize\bfN}}{\hbox{\tiny\bfN}}}},\; \lambda_n\leqslant\lambda\}\sim \frac{\lambda^{d}}{2^{d}\Gamma\bgroup\bgroup\bgroup\bgroup\left(d+1\right)\egroup\egroup\egroup\egroup}\,,$$
    as $\lambda$ goes to $\infty$.

Item 1. is a classical consequence of the bounded imaginary powers of $H$ over $L^p_x({{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d)$ (see Proposition 3.5.5. in \cite{Ha06} for the interpolation result and \cite{He90} showing $H$ is in fact BIP on $L^p_x({{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d)$). Item 2. is a direct application of Riesz-Thorin theorem. Item 3. follows by Theorem 6.5.3. and Corollary 6.5.5. in \cite{Ha06} as $\mathscr{Q}_\mu-\mathrm{Id} = \psi\bgroup\bgroup\bgroup\bgroup\left(\mu\sqrt{H}\right)\egroup\egroup\egroup\egroup$ with $\psi(z)=\bgroup\bgroup\bgroup\bgroup\left(1+z^2\right)\egroup\egroup\egroup\egroup^{-1}-1$ verifying $z^{-\eta}\psi(z)\sim z^{2-\eta}$ when $z$ goes to $0$ and $z^{-\eta}\psi(z)\sim z^{-\eta}$ when $z$ goes to $\infty$. Finally, Item 4. follows from Item 3. by a standard shift of regularity using powers of $H$ and the bounded $\mathcal{H}^\infty$-calculus of $H$ on $L_x^p({{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}^d)$ (which is a direct consequence of \cite{He90}).

\label{Prop:HermiteSpacesEmbeddings}
    Let $1<p<q<\infty$ and $\eta,\sigma\in{{\mathchoice{\hbox{\bfR}}{\hbox{\bfR}} 
        {\hbox{\scriptsize\bfR}}{\hbox{\tiny\bfR}}}}$. Then, the following holds.
    \begin{enumerate}
        \par\hangindent 40\p@ If $\frac{1}{p}-\frac{\eta}{d}\leqslant\frac{1}{q}-\frac{\sigma}{d}$, then $\mathscr{H}^{\eta,p}\subset\mathscr{H}^{\sigma,q}$. Moreover, if $\frac{1}{p}-\frac{\eta}{d}<\frac{1}{q}-\frac{\sigma}{d}$, then the inclusion is compact.
        \par\hangindent 40\p@ If $\eta>\frac{d}{p}$, then $\mathscr{H}^{\eta,p}\subset L^\infty_x$ compactly.
        \par\hangindent 40\p@ If $\frac{1}{p}+\frac{\eta}{d}<\frac{1}{q}+\frac{\sigma}{d}$, then $\mathscr{H}^{\sigma,q}\subset\mathscr{H}^{\eta,p}$ compactly.
        \par\hangindent 40\p@ If $\eta>d\bgroup\bgroup\bgroup\bgroup\left(1-\frac{1}{p}\right)\egroup\egroup\egroup\egroup$, then $\mathscr{H}^{\eta,p}\subset L^1_x$ compactly.
        \par\hangindent 40\p@ If $\eta<1$, then $\mathscr{B}^{\eta}_{p,1}\subset\mathscr{H}^{\eta,p}\subset\mathscr{B}^{\eta}_{p,\infty}\subset\mathscr{B}^{\eta-\varepsilon}_{p,1}$ for any $\varepsilon>0$.
    \end{enumerate}
